(378732,42082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn jemand einen Ausschlag aufkratzt, ... er normalerweise noch röter.'::text,'wird'::text,'wurde'::text,'wird'::text,'Wenn jemand einen Ausschlag aufkratzt, wird er normalerweise noch röter.'::text),
(378736,42082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо хтось розчісує висип, він зазвичай ... ще червонішим.'::text,'стає'::text,'став'::text,'стане'::text,'Якщо хтось розчісує висип, він зазвичай стає ще червонішим.'::text),
(378735,42082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si alguien se rasca un sarpullido, normalmente se ... más rojo.'::text,'pone'::text,'puso'::text,'pondrá'::text,'Si alguien se rasca un sarpullido, normalmente se pone más rojo.'::text),
(378734,42082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si quelqu''un gratte une éruption, elle ... généralement plus rouge.'::text,'devient'::text,'est devenue'::text,'deviendra'::text,'Si quelqu''un gratte une éruption, elle devient généralement plus rouge.'::text),
(378737,42082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri kızarıklığı kaşırsa, kızarıklık genelde daha da ...'::text,'kızarır'::text,'kızardı'::text,'kızaracak'::text,'Biri kızarıklığı kaşırsa, kızarıklık genelde daha da kızarır.'::text),
(378738,42082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha valaki vakarja a kiütést, az általában ... pirosabb.'::text,'lesz'::text,'lett'::text,'lesz'::text,'Ha valaki vakarja a kiütést, az általában lesz pirosabb.'::text),
(378750,42084,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir erzählt, dass sie keine Handschuhe getragen hat, bevor der Ausschlag kam, und ...'::text,'ihre Freundin auch nicht.'::text,'ihre Freundin auch nicht.'::text,'ihre Freundin auch.'::text,'Hör zu, sie hat mir erzählt, dass sie keine Handschuhe getragen hat, bevor der Ausschlag kam, und ihre Freundin auch nicht.'::text),
(378754,42084,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала мені, що не вдягла рукавички, перш ніж з''явився висип, і ...'::text,'її подруга теж ні.'::text,'її подруга теж ні.'::text,'її подруга теж.'::text,'Слухай, вона сказала мені, що не вдягла рукавички, перш ніж з''явився висип, і її подруга теж ні.'::text),
(378753,42084,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que no llevaba guantes antes de que apareciera el sarpullido, y ...'::text,'su amiga tampoco.'::text,'su amiga tampoco.'::text,'su amiga también.'::text,'Escucha, me dijo que no llevaba guantes antes de que apareciera el sarpullido, y su amiga tampoco.'::text),
(378752,42084,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit qu''elle ne portait pas de gants avant que l''éruption apparaisse, et ...'::text,'son amie non plus.'::text,'son amie non plus.'::text,'son amie aussi.'::text,'Écoute, elle m''a dit qu''elle ne portait pas de gants avant que l''éruption apparaisse, et son amie non plus.'::text),
(378755,42084,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana kızarıklık çıkmadan önce eldiven takmadığını söyledi, ...'::text,'arkadaşı da takmamış.'::text,'arkadaşı da takmamış.'::text,'arkadaşı da takmış.'::text,'Dinle, bana kızarıklık çıkmadan önce eldiven takmadığını söyledi, arkadaşı da takmamış.'::text),
(378756,42084,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy nem vett fel kesztyűt, mielőtt megjelent a kiütés, és ...'::text,'a barátnője sem.'::text,'a barátnője sem.'::text,'a barátnője is.'::text,'Figyelj, azt mondta, hogy nem vett fel kesztyűt, mielőtt megjelent a kiütés, és a barátnője sem.'::text),
(378759,42085,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie schwört, dass die Creme den Ausschlag bis Freitag ...'::text,'weggemacht haben wird'::text,'wegmachen wird'::text,'gerade wegmachen wird'::text,'Bestie, sie schwört, dass die Creme den Ausschlag bis Freitag weggemacht haben wird.'::text),
(378763,42085,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона клянеться, що крем ... цей висип до п''ятниці.'::text,'прибере'::text,'прибере'::text,'прибиратиме'::text,'Подруго, вона клянеться, що крем прибере цей висип до п''ятниці.'::text),
(378762,42085,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, jura que la crema ... ese sarpullido para el viernes.'::text,'habrá quitado'::text,'quitará'::text,'estará quitando'::text,'Amiga, jura que la crema habrá quitado ese sarpullido para el viernes.'::text),
(378761,42085,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle jure que la crème ... cette éruption d''ici vendredi.'::text,'aura fait disparaître'::text,'fera disparaître'::text,'sera en train de faire disparaître'::text,'Ma belle, elle jure que la crème aura fait disparaître cette éruption d''ici vendredi.'::text),
(378764,42085,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kremin o kızarıklığı cumaya kadar ... yemin ediyor.'::text,'geçirmiş olacağına'::text,'geçireceğine'::text,'geçiriyor olacağına'::text,'Kanka, kremin o kızarıklığı cumaya kadar geçirmiş olacağına yemin ediyor.'::text),
(378765,42085,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, esküszik, hogy a krém péntekre ... a kiütést.'::text,'eltünteti'::text,'el fogja tüntetni'::text,'tüntetni fogja'::text,'Csajszi, esküszik, hogy a krém péntekre eltünteti a kiütést.'::text),
(378768,42086,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie ihre Gartenhandschuhe getragen hätte, ... sie den Ausschlag am Arm nicht bekommen.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn sie ihre Gartenhandschuhe getragen hätte, hätte sie den Ausschlag am Arm nicht bekommen.'::text),
(378772,42086,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона вдягла садові рукавички, вона ... висипу на руці.'::text,'не отримала б'::text,'не отримає'::text,'не отримала'::text,'Якби вона вдягла садові рукавички, вона не отримала б висипу на руці.'::text),
(378771,42086,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera llevado sus guantes de jardinería, ... el sarpullido del brazo.'::text,'no habría tenido'::text,'no tendrá'::text,'no tuvo'::text,'Si hubiera llevado sus guantes de jardinería, no habría tenido el sarpullido del brazo.'::text),
(378770,42086,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait porté ses gants de jardinage, elle ... l''éruption sur le bras.'::text,'n''aurait pas eu'::text,'n''aura pas'::text,'n''a pas eu'::text,'Si elle avait porté ses gants de jardinage, elle n''aurait pas eu l''éruption sur le bras.'::text),
(378773,42086,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçe eldivenlerini taksaydı, kolundaki kızarıklık ...'::text,'çıkmazdı'::text,'çıkmayacak'::text,'çıkmadı'::text,'Bahçe eldivenlerini taksaydı, kolundaki kızarıklık çıkmazdı.'::text),
(378774,42086,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha felvette volna a kerti kesztyűjét, ... a kiütés a karján.'::text,'nem lett volna'::text,'nem lesz'::text,'nem lett'::text,'Ha felvette volna a kerti kesztyűjét, nem lett volna a kiütés a karján.'::text),
(378777,42087,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast angeboten, ihr Creme auf den Ausschlag ..., bevor sie überhaupt gefragt hat.'::text,'aufzutragen'::text,'Auftragen'::text,'auftragen'::text,'Ehrlich, du hast angeboten, ihr Creme auf den Ausschlag aufzutragen, bevor sie überhaupt gefragt hat.'::text),
(378781,42087,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти запропонував ... крем на її висип, ще до того як вона попросила.'::text,'нанести'::text,'нанесення'::text,'нанести'::text,'Чесно, ти запропонував нанести крем на її висип, ще до того як вона попросила.'::text),
(378780,42087,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, te ofreciste a ... crema en su sarpullido antes de que ella lo pidiera.'::text,'poner'::text,'poniendo'::text,'poner'::text,'La verdad, te ofreciste a poner crema en su sarpullido antes de que ella lo pidiera.'::text),
(378779,42087,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as proposé ... de la crème sur son éruption avant même qu''elle demande.'::text,'de mettre'::text,'mettant'::text,'mettre'::text,'Franchement, tu as proposé de mettre de la crème sur son éruption avant même qu''elle demande.'::text),
(378782,42087,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, o daha istemeden kızarıklığına krem ... teklif ettin.'::text,'sürmeyi'::text,'sürme'::text,'sür'::text,'Açıkçası, o daha istemeden kızarıklığına krem sürmeyi teklif ettin.'::text),
(378783,42087,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, felajánlottad, hogy ... krémet a kiütésére, mielőtt még kérte volna.'::text,'kensz'::text,'kenés'::text,'kenni'::text,'Őszintén, felajánlottad, hogy kensz krémet a kiütésére, mielőtt még kérte volna.'::text),
(378786,42088,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... Medizin studiert haben, so ruhig, wie du mit dem Ausschlag umgegangen bist. Ehrlich.'::text,'musst'::text,'solltest'::text,'kannst nicht'::text,'Du musst Medizin studiert haben, so ruhig, wie du mit dem Ausschlag umgegangen bist. Ehrlich.'::text),
(378790,42088,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... медицину, так спокійно ти впорався з тим висипом. Чесно.'::text,'точно вивчав'::text,'мав би вивчати'::text,'не міг вивчати'::text,'Ти точно вивчав медицину, так спокійно ти впорався з тим висипом. Чесно.'::text),
(378789,42088,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... estudiado medicina, por lo tranquilo que manejaste ese sarpullido. En serio.'::text,'debes de haber'::text,'deberías haber'::text,'no puedes haber'::text,'Tú debes de haber estudiado medicina, por lo tranquilo que manejaste ese sarpullido. En serio.'::text),
(378788,42088,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... médecine, vu comment tu as géré cette éruption si calmement. Franchement.'::text,'as dû faire'::text,'aurais dû faire'::text,'n''as pas pu faire'::text,'Tu as dû faire médecine, vu comment tu as géré cette éruption si calmement. Franchement.'::text),
(378791,42088,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen tıp ..., o kızarıklığı öyle sakin hallettin ki. Cidden.'::text,'okumuş olmalısın'::text,'okumalıydın'::text,'okumuş olamazsın'::text,'Sen tıp okumuş olmalısın, o kızarıklığı öyle sakin hallettin ki. Cidden.'::text),
(378792,42088,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ... orvosira, olyan nyugodtan kezelted azt a kiütést. Komolyan.'::text,'biztos jártál'::text,'járnod kellett volna'::text,'nem járhattál'::text,'Te biztos jártál orvosira, olyan nyugodtan kezelted azt a kiütést. Komolyan.'::text),
(378795,42089,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hätte einen Arzt auf den Ausschlag ... lassen können, aber eine lachende Freundin war natürlich besser.'::text,'schauen'::text,'zu schauen'::text,'schauend'::text,'Sie hätte einen Arzt auf den Ausschlag schauen lassen können, aber eine lachende Freundin war natürlich besser.'::text),
(378799,42089,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона могла б дати лікарю ... на висип, але подруга, яка регоче, явно була кращим варіантом.'::text,'подивитися'::text,'подивитися'::text,'дивлячись'::text,'Вона могла б дати лікарю подивитися на висип, але подруга, яка регоче, явно була кращим варіантом.'::text),
(378798,42089,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Podría haber hecho que un médico le ... el sarpullido, pero una amiga riéndose era claramente mejor.'::text,'mirara'::text,'mirar'::text,'mirando'::text,'Podría haber hecho que un médico le mirara el sarpullido, pero una amiga riéndose era claramente mejor.'::text),
(378797,42089,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle aurait pu faire ... son éruption par un médecin, mais une amie morte de rire, c''était clairement mieux.'::text,'examiner'::text,'d''examiner'::text,'examinant'::text,'Elle aurait pu faire examiner son éruption par un médecin, mais une amie morte de rire, c''était clairement mieux.'::text),
(378800,42089,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızarıklığa bir doktora ... ama gülen bir arkadaş belli ki daha iyiydi.'::text,'baktırabilirdi'::text,'bakmak'::text,'bakarak'::text,'Kızarıklığa bir doktora baktırabilirdi ama gülen bir arkadaş belli ki daha iyiydi.'::text),
(378801,42089,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy orvossal is ... a kiütést, de egy röhögő barátnő nyilván jobb volt.'::text,'megnézethette volna'::text,'megnézni'::text,'nézve'::text,'Egy orvossal is megnézethette volna a kiütést, de egy röhögő barátnő nyilván jobb volt.'::text),
(378813,42091,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Pflanze, ... Blätter ihr den Ausschlag verpasst haben, ist echt ziemlich böse.'::text,'deren'::text,'die'::text,'die'::text,'Bro, die Pflanze, deren Blätter ihr den Ausschlag verpasst haben, ist echt ziemlich böse.'::text),
(378817,42091,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, та рослина, ... листя викликало в неї той висип, чесно кажучи, зла.'::text,'чиє'::text,'яка'::text,'що'::text,'Бро, та рослина, чиє листя викликало в неї той висип, чесно кажучи, зла.'::text),
(378816,42091,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la planta ... hojas le dieron ese sarpullido es medio malvada.'::text,'cuyas'::text,'la cual'::text,'que'::text,'Bro, la planta cuyas hojas le dieron ese sarpullido es medio malvada.'::text),
(378815,42091,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, la plante ... les feuilles lui ont donné cette éruption est un peu diabolique, genre.'::text,'dont'::text,'qui'::text,'que'::text,'Frérot, la plante dont les feuilles lui ont donné cette éruption est un peu diabolique, genre.'::text),
(378818,42091,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... yaprakları ona o kızarıklığı yapan bitki biraz şeytani.'::text,''::text,NULL::text,NULL::text,'Kanka, yaprakları ona o kızarıklığı yapan bitki biraz şeytani.'::text),
(378819,42091,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a növény, ... levelei kiütést okoztak neki, kicsit gonosz.'::text,'amelynek'::text,'amely'::text,'ami'::text,'Tesó, az a növény, amelynek levelei kiütést okoztak neki, kicsit gonosz.'::text),
(378822,42092,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat ... am Unterarm, nicht im Gesicht.'::text,'einen Ausschlag'::text,'Ausschlag'::text,'den Ausschlag'::text,'Sie hat einen Ausschlag am Unterarm, nicht im Gesicht.'::text),
(378826,42092,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї ... на передпліччі, а не на обличчі.'::text,'висип'::text,'висип'::text,'висип'::text,'У неї висип на передпліччі, а не на обличчі.'::text),
(378825,42092,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene ... en el antebrazo, no en la cara.'::text,'un sarpullido'::text,'sarpullido'::text,'el sarpullido'::text,'Tiene un sarpullido en el antebrazo, no en la cara.'::text),
(378824,42092,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a ... sur l''avant-bras, pas sur le visage.'::text,'une éruption'::text,'éruption'::text,'l''éruption'::text,'Elle a une éruption sur l''avant-bras, pas sur le visage.'::text),
(378827,42092,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ön kolunda ... var, yüzünde değil.'::text,'bir kızarıklık'::text,'kızarıklık'::text,'kızarıklık'::text,'Ön kolunda bir kızarıklık var, yüzünde değil.'::text),
(378828,42092,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alkarján ... van, nem az arcán.'::text,'egy kiütés'::text,'kiütés'::text,'a kiütés'::text,'Az alkarján egy kiütés van, nem az arcán.'::text),
(336675,37409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... in der Straßenbahn, als ihr Dutt fast zusammenbrach. Katastrophe!'::text,'las gerade'::text,'las'::text,'hat gelesen'::text,'Sie las gerade in der Straßenbahn, als ihr Dutt fast zusammenbrach. Katastrophe!'::text),
(336679,37409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... в трамваї, коли її гулька мало не розвалилася. Катастрофа!'::text,'читала'::text,'прочитала'::text,'прочитала'::text,'Вона читала в трамваї, коли її гулька мало не розвалилася. Катастрофа!'::text),
(336678,37409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... en el tranvía cuando su moño casi se deshizo. ¡Desastre!'::text,'estaba leyendo'::text,'leyó'::text,'ha leído'::text,'Ella estaba leyendo en el tranvía cuando su moño casi se deshizo. ¡Desastre!'::text),
(336677,37409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans le tram quand son chignon a failli s''effondrer. La cata !'::text,'lisait'::text,'a lu'::text,'a lu'::text,'Elle lisait dans le tram quand son chignon a failli s''effondrer. La cata !'::text),
(336680,37409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topuzu neredeyse dağıldığında tramvayda ... — tam bir felaket!'::text,'okuyordu'::text,'okudu'::text,'okudu'::text,'Topuzu neredeyse dağıldığında tramvayda okuyordu — tam bir felaket!'::text),
(336681,37409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő épp ... a villamoson, amikor a kontya majdnem szétesett. Katasztrófa!'::text,'olvasott'::text,'olvasott'::text,'elolvasott'::text,'Ő épp olvasott a villamoson, amikor a kontya majdnem szétesett. Katasztrófa!'::text),
(336684,37410,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, ich hab gehört, sie ... seit Montag dasselbe Buch, immer noch mit diesem perfekten Dutt.'::text,'liest schon'::text,'liest gerade'::text,'liest'::text,'Girl, ich hab gehört, sie liest schon seit Montag dasselbe Buch, immer noch mit diesem perfekten Dutt.'::text),
(336688,37410,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, чула, що вона ... ту саму книжку з понеділка, досі з тією ідеальною гулькою.'::text,'читає вже'::text,'зараз читає'::text,'читає'::text,'Подруго, чула, що вона читає вже ту саму книжку з понеділка, досі з тією ідеальною гулькою.'::text),
(336687,37410,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que ... el mismo libro desde el lunes, todavía con ese moño perfecto.'::text,'lleva leyendo'::text,'está leyendo'::text,'lee'::text,'Amiga, he oído que lleva leyendo el mismo libro desde el lunes, todavía con ese moño perfecto.'::text),
(336686,37410,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il paraît qu''elle ... le même livre depuis lundi, toujours avec ce chignon parfait.'::text,'lit'::text,'est en train de lire'::text,'lit'::text,'Meuf, il paraît qu''elle lit le même livre depuis lundi, toujours avec ce chignon parfait.'::text),
(336689,37410,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre pazartesiden beri aynı kitabı ..., hâlâ o kusursuz topuzla.'::text,'okuyormuş'::text,'okuyormuş'::text,'okurmuş'::text,'Kızım, duyduğuma göre pazartesiden beri aynı kitabı okuyormuş, hâlâ o kusursuz topuzla.'::text),
(336690,37410,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy hétfő óta ugyanazt a könyvet ..., még mindig azzal a tökéletes konttyal.'::text,'olvassa'::text,'olvassa'::text,'olvassa'::text,'Csajszi, azt hallottam, hogy hétfő óta ugyanazt a könyvet olvassa, még mindig azzal a tökéletes konttyal.'::text),
(336693,37411,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich hat sie zweimal gegähnt, während sie auf der Bank ..., samt Dutt.'::text,'las'::text,'las'::text,'gelesen hat'::text,'Okay, also angeblich hat sie zweimal gegähnt, während sie auf der Bank las, samt Dutt.'::text),
(336697,37411,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, вона двічі позіхнула, поки ... на лавці, разом зі своєю гулькою.'::text,'читала'::text,'прочитала'::text,'прочитала'::text,'Коротше, кажуть, вона двічі позіхнула, поки читала на лавці, разом зі своєю гулькою.'::text),
(336696,37411,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer bostezó dos veces mientras ... en el banco, con moño y todo.'::text,'leía'::text,'leyó'::text,'ha leído'::text,'Vale, pues al parecer bostezó dos veces mientras leía en el banco, con moño y todo.'::text),
(336695,37411,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment elle a bâillé deux fois pendant qu''elle ... sur le banc, chignon compris.'::text,'lisait'::text,'a lu'::text,'a lu'::text,'Bon, apparemment elle a bâillé deux fois pendant qu''elle lisait sur le banc, chignon compris.'::text),
(336698,37411,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, anlaşılan bankta ... iki kez esnemiş, topuzuyla birlikte.'::text,'okurken'::text,'okuduğunda'::text,'okumuşken'::text,'Neyse, anlaşılan bankta okurken iki kez esnemiş, topuzuyla birlikte.'::text),
(336699,37411,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag kétszer ásított, miközben a padon ..., konttyal együtt.'::text,'olvasott'::text,'olvasott'::text,'elolvasott'::text,'Szóval, állítólag kétszer ásított, miközben a padon olvasott, konttyal együtt.'::text),
(336702,37412,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ohne Witz, sie hat heute 200 Seiten ..., und der Dutt hat sich kein einziges Mal bewegt, echt.'::text,'gelesen'::text,'gelesen'::text,'gelesen'::text,'Ohne Witz, sie hat heute 200 Seiten gelesen, und der Dutt hat sich kein einziges Mal bewegt, echt.'::text),
(336706,37412,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, вона сьогодні ... 200 сторінок, і та гулька ні разу не зрушила, реально.'::text,'прочитала'::text,'читала'::text,'читає'::text,'Чесно, вона сьогодні прочитала 200 сторінок, і та гулька ні разу не зрушила, реально.'::text),
(336705,37412,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, hoy ... 200 páginas y ese moño no se ha movido ni una vez, en serio.'::text,'ha leído'::text,'ha estado leyendo'::text,'está leyendo'::text,'No te voy a mentir, hoy ha leído 200 páginas y ese moño no se ha movido ni una vez, en serio.'::text),
(336704,37412,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, elle ... 200 pages aujourd''hui et ce chignon n''a pas bougé une seule fois, sérieux.'::text,'a lu'::text,'a lu'::text,'est en train de lire'::text,'Sans mentir, elle a lu 200 pages aujourd''hui et ce chignon n''a pas bougé une seule fois, sérieux.'::text),
(336707,37412,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bugün 200 sayfa ... ve o topuz bir kez bile kıpırdamadı, cidden.'::text,'okudu'::text,'okuyor'::text,'okuyor'::text,'Yalan yok, bugün 200 sayfa okudu ve o topuz bir kez bile kıpırdamadı, cidden.'::text),
(336708,37412,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, ma ... 200 oldalt, és az a konty egyszer se mozdult meg, komolyan.'::text,'elolvasott'::text,'olvasott'::text,'olvas'::text,'Nem fogok hazudni, ma elolvasott 200 oldalt, és az a konty egyszer se mozdult meg, komolyan.'::text),
(336711,37413,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bevor sie überhaupt in die Tram gestiegen ist, ... sie sich die Haare zu einem Dutt gedreht, das ist ein Vibe.'::text,'hatte'::text,'hat'::text,'dreht'::text,'Bro, bevor sie überhaupt in die Tram gestiegen ist, hatte sie sich die Haare zu einem Dutt gedreht, das ist ein Vibe.'::text),
(336715,37413,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... волосся в гульку ще до того, як сіла в трамвай, це вайб.'::text,'закрутила'::text,'закрутила'::text,'закручує'::text,'Бро, вона закрутила волосся в гульку ще до того, як сіла в трамвай, це вайб.'::text),
(336714,37413,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ya se ... el pelo en un moño antes de subir al tranvía, qué vibe.'::text,'había recogido'::text,'ha recogido'::text,'recoge'::text,'Bro, ya se había recogido el pelo en un moño antes de subir al tranvía, qué vibe.'::text),
(336713,37413,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... ses cheveux en chignon avant même de monter dans le tram, c''est un mood.'::text,'avait attaché'::text,'a attaché'::text,'attache'::text,'Frérot, elle avait attaché ses cheveux en chignon avant même de monter dans le tram, c''est un mood.'::text),
(336716,37413,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tramvaya binmeden önce saçını çoktan topuz ..., bu bir vibe.'::text,'yapmıştı'::text,'yaptı'::text,'yapıyor'::text,'Kanka, tramvaya binmeden önce saçını çoktan topuz yapmıştı, bu bir vibe.'::text),
(336717,37413,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, még azelőtt ... a haját kontyba, hogy felszállt volna a villamosra, ez egy vibe.'::text,'feltekerte'::text,'feltekerte'::text,'feltekeri'::text,'Tesó, még azelőtt feltekerte a haját kontyba, hogy felszállt volna a villamosra, ez egy vibe.'::text),
(336720,37414,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hält der Dutt noch 3 Kapitel, dann ... sie ihr wöchentliches Leseziel.'::text,'erreicht'::text,'erreichte'::text,'erreichte'::text,'Hält der Dutt noch 3 Kapitel, dann erreicht sie ihr wöchentliches Leseziel.'::text),
(336724,37414,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо гулька протримається ще 3 розділи, вона ... свою тижневу ціль із читання.'::text,'виконає'::text,'виконала б'::text,'виконала'::text,'Якщо гулька протримається ще 3 розділи, вона виконає свою тижневу ціль із читання.'::text),
(336723,37414,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el moño aguanta 3 capítulos más, ... su objetivo semanal de lectura.'::text,'cumplirá'::text,'cumpliría'::text,'cumplió'::text,'Si el moño aguanta 3 capítulos más, cumplirá su objetivo semanal de lectura.'::text),
(336722,37414,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chignon tient encore 3 chapitres, elle ... son objectif de lecture hebdomadaire.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'Si le chignon tient encore 3 chapitres, elle atteindra son objectif de lecture hebdomadaire.'::text),
(336725,37414,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topuz 3 bölüm daha dayanırsa haftalık okuma hedefine ...'::text,'ulaşacak'::text,'ulaşırdı'::text,'ulaştı'::text,'Topuz 3 bölüm daha dayanırsa haftalık okuma hedefine ulaşacak.'::text),
(336726,37414,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a konty kibír még 3 fejezetet, ... a heti olvasási célját.'::text,'teljesíti'::text,'teljesítené'::text,'teljesítette'::text,'Ha a konty kibír még 3 fejezetet, teljesíti a heti olvasási célját.'::text),
(336729,37415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihre Haare nicht im Dutt wären, ... sie nach unten, weil Haare da nun mal hingehören.'::text,'hingen'::text,'werden hängen'::text,'hängen'::text,'Wenn ihre Haare nicht im Dutt wären, hingen sie nach unten, weil Haare da nun mal hingehören.'::text),
(336733,37415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби її волосся не було в гульці, воно ... вниз, бо саме туди волосся і йде.'::text,'звисало б'::text,'звисатиме'::text,'звисає'::text,'Якби її волосся не було в гульці, воно звисало б вниз, бо саме туди волосся і йде.'::text),
(336732,37415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su pelo no estuviera en un moño, ... hacia abajo, porque ahí es donde va el pelo.'::text,'colgaría'::text,'colgará'::text,'cuelga'::text,'Si su pelo no estuviera en un moño, colgaría hacia abajo, porque ahí es donde va el pelo.'::text),
(336731,37415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ses cheveux n''étaient pas en chignon, ils ... vers le bas, parce que c''est là que vont les cheveux.'::text,'tomberaient'::text,'tomberont'::text,'tombent'::text,'Si ses cheveux n''étaient pas en chignon, ils tomberaient vers le bas, parce que c''est là que vont les cheveux.'::text),
(336734,37415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saçı topuz olmasaydı aşağı ..., çünkü saç oraya gider.'::text,'sarkardı'::text,'sarkacak'::text,'sarkar'::text,'Saçı topuz olmasaydı aşağı sarkardı, çünkü saç oraya gider.'::text),
(336735,37415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a haja nem lenne kontyban, lefelé ..., mert a haj oda való.'::text,'lógna'::text,'fog lógni'::text,'lóg'::text,'Ha a haja nem lenne kontyban, lefelé lógna, mert a haj oda való.'::text),
(336738,37416,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Haare ... zu einem Dutt gedreht, bevor sie an dem Morgen das Haus verließ.'::text,'wurden'::text,'werden'::text,'drehten'::text,'Ihre Haare wurden zu einem Dutt gedreht, bevor sie an dem Morgen das Haus verließ.'::text),
(336742,37416,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її волосся ... в гульку, перш ніж вона того ранку вийшла з дому.'::text,'було закручене'::text,'закручене'::text,'закрутило'::text,'Її волосся було закручене в гульку, перш ніж вона того ранку вийшла з дому.'::text),
(336741,37416,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su pelo ... en un moño antes de que saliera de casa esa mañana.'::text,'fue recogido'::text,'es recogido'::text,'recogió'::text,'Su pelo fue recogido en un moño antes de que saliera de casa esa mañana.'::text),
(336740,37416,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses cheveux ... en chignon avant qu''elle quitte la maison ce matin-là.'::text,'ont été attachés'::text,'sont attachés'::text,'ont attaché'::text,'Ses cheveux ont été attachés en chignon avant qu''elle quitte la maison ce matin-là.'::text),
(336743,37416,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sabah evden çıkmadan önce saçı topuz ...'::text,'yapıldı'::text,'yapılıyor'::text,'yaptı'::text,'O sabah evden çıkmadan önce saçı topuz yapıldı.'::text),
(336744,37416,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A haját ... kontyba, mielőtt aznap reggel elindult otthonról.'::text,'feltekerték'::text,'feltekerik'::text,'feltekerte'::text,'A haját feltekerték kontyba, mielőtt aznap reggel elindult otthonról.'::text),
(336756,37418,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Dutt hält den ganzen Tag, also ... sie viele Haarnadeln benutzen.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Der Dutt hält den ganzen Tag, also muss sie viele Haarnadeln benutzen.'::text),
(336760,37418,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гулька тримається цілий день, тож вона ... використовувати багато шпильок.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Гулька тримається цілий день, тож вона мусить використовувати багато шпильок.'::text),
(336759,37418,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El moño aguanta todo el día, así que ... usar muchas horquillas.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'El moño aguanta todo el día, así que debe de usar muchas horquillas.'::text),
(336758,37418,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chignon tient toute la journée, donc elle ... utiliser plein d''épingles.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Le chignon tient toute la journée, donc elle doit utiliser plein d''épingles.'::text),
(336761,37418,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topuz bütün gün yerinde duruyor, demek ki çok fazla toka ...'::text,'kullanıyor olmalı'::text,'kullanıyor olamaz'::text,'kullanmamalı'::text,'Topuz bütün gün yerinde duruyor, demek ki çok fazla toka kullanıyor olmalı.'::text),
(336762,37418,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A konty egész nap a helyén marad, szóval ... sok hajtűt használnia.'::text,'biztosan kell'::text,'nem lehet'::text,'nem kellene'::text,'A konty egész nap a helyén marad, szóval biztosan kell sok hajtűt használnia.'::text),
(379209,42135,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... jahrelang schweigend gearbeitet, bevor sie endlich rebellierte, kein Witz.'::text,'hatten'::text,'haben'::text,'arbeiteten'::text,'Bro, sie hatten jahrelang schweigend gearbeitet, bevor sie endlich rebellierte, kein Witz.'::text),
(379213,42135,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вони ... мовчки роками, поки вона нарешті не збунтувалася, без брехні.'::text,'працювали'::text,'працюють'::text,'працювали'::text,'Бро, вони працювали мовчки роками, поки вона нарешті не збунтувалася, без брехні.'::text),
(379212,42135,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... en silencio durante años antes de que ella por fin se rebelara, sin mentir.'::text,'habían estado trabajando'::text,'han estado trabajando'::text,'estaban trabajando'::text,'Bro, habían estado trabajando en silencio durante años antes de que ella por fin se rebelara, sin mentir.'::text),
(379211,42135,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ils ... en silence pendant des années avant qu''elle se rebelle enfin, sans mentir.'::text,'avaient travaillé'::text,'ont travaillé'::text,'travaillaient'::text,'Frérot, ils avaient travaillé en silence pendant des années avant qu''elle se rebelle enfin, sans mentir.'::text),
(379214,42135,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o sonunda isyan edene kadar yıllarca sessizce ..., yalan yok.'::text,'çalışmışlardı'::text,'çalışıyorlar'::text,'çalışıyorlardı'::text,'Kanka, o sonunda isyan edene kadar yıllarca sessizce çalışmışlardı, yalan yok.'::text),
(379215,42135,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, évekig csendben ..., mielőtt ő végre fellázadt, komolyan.'::text,'dolgoztak'::text,'dolgoznak'::text,'dolgoztak'::text,'Tesó, évekig csendben dolgoztak, mielőtt ő végre fellázadt, komolyan.'::text),
(379218,42136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Freitag wird die ganze Etage gegen diesen Chef ..., echt, das schreit nach Revolution.'::text,'rebelliert haben'::text,'rebellieren'::text,'am Rebellieren sein'::text,'Bis Freitag wird die ganze Etage gegen diesen Chef rebelliert haben, echt, das schreit nach Revolution.'::text),
(379222,42136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До п''ятниці весь поверх ... проти того боса, реально, це вже пахне революцією.'::text,'збунтується'::text,'збунтується'::text,'бунтуватиме'::text,'До п''ятниці весь поверх збунтується проти того боса, реально, це вже пахне революцією.'::text),
(379221,42136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el viernes, toda la planta ... contra ese jefe, en serio, esto huele a revolución.'::text,'se habrá rebelado'::text,'se rebelará'::text,'se estará rebelando'::text,'Para el viernes, toda la planta se habrá rebelado contra ese jefe, en serio, esto huele a revolución.'::text),
(379220,42136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici vendredi, tout l''étage ... contre ce chef, sérieux, ça sent la révolution.'::text,'se sera rebellé'::text,'se rebellera'::text,'sera en train de se rebeller'::text,'D''ici vendredi, tout l''étage se sera rebellé contre ce chef, sérieux, ça sent la révolution.'::text),
(379223,42136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cumaya kadar bütün kat o patrona karşı ..., cidden, tam devrim havası.'::text,'ayaklanmış olacak'::text,'ayaklanacak'::text,'ayaklanıyor olacak'::text,'Cumaya kadar bütün kat o patrona karşı ayaklanmış olacak, cidden, tam devrim havası.'::text),
(379224,42136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Péntekre az egész emelet ... az ellen a főnök ellen, komolyan, forradalmi vibe.'::text,'fellázad'::text,'fel fog lázadni'::text,'épp lázadni fog'::text,'Péntekre az egész emelet fellázad az ellen a főnök ellen, komolyan, forradalmi vibe.'::text),
(379227,42137,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Ende der Schicht wird die Belegschaft 8 Stunden lang gegen die neuen Zielvorgaben ...'::text,'rebelliert haben'::text,'rebellieren'::text,'am Rebellieren sein'::text,'Am Ende der Schicht wird die Belegschaft 8 Stunden lang gegen die neuen Zielvorgaben rebelliert haben.'::text),
(379231,42137,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця зміни персонал ... проти нових цілей уже 8 годин.'::text,'бунтуватиме'::text,'збунтується'::text,'бунтуватиме'::text,'До кінця зміни персонал бунтуватиме проти нових цілей уже 8 годин.'::text),
(379230,42137,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final del turno, el personal ... contra los nuevos objetivos durante 8 horas.'::text,'llevará rebelándose'::text,'se rebelará'::text,'se estará rebelando'::text,'Al final del turno, el personal llevará rebelándose contra los nuevos objetivos durante 8 horas.'::text),
(379229,42137,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À la fin du service, le personnel ... contre les nouveaux objectifs pendant 8 heures.'::text,'se sera rebellé'::text,'se rebellera'::text,'sera en train de se rebeller'::text,'À la fin du service, le personnel se sera rebellé contre les nouveaux objectifs pendant 8 heures.'::text),
(379232,42137,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vardiya sonunda personel 8 saattir yeni hedeflere karşı ...'::text,'isyan ediyor olacak'::text,'isyan edecek'::text,'isyan ediyor olacak'::text,'Vardiya sonunda personel 8 saattir yeni hedeflere karşı isyan ediyor olacak.'::text),
(379233,42137,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A műszak végére a személyzet már 8 órája ... az új célok ellen.'::text,'lázad'::text,'fel fog lázadni'::text,'lázadni fog'::text,'A műszak végére a személyzet már 8 órája lázad az új célok ellen.'::text),
(379236,42138,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Chef auf sie gehört hätte, ... die Angestellten nicht gegen ihn rebelliert.'::text,'hätten'::text,'werden'::text,'haben'::text,'Wenn der Chef auf sie gehört hätte, hätten die Angestellten nicht gegen ihn rebelliert.'::text),
(379240,42138,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби бос їх вислухав, працівники ... проти нього.'::text,'не збунтувалися б'::text,'не збунтуються'::text,'не збунтувалися'::text,'Якби бос їх вислухав, працівники не збунтувалися б проти нього.'::text),
(379239,42138,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el jefe los hubiera escuchado, los trabajadores ... contra él.'::text,'no se habrían rebelado'::text,'no se rebelarán'::text,'no se rebelaron'::text,'Si el jefe los hubiera escuchado, los trabajadores no se habrían rebelado contra él.'::text),
(379238,42138,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le chef les avait écoutés, les employés ... contre lui.'::text,'ne se seraient pas rebellés'::text,'ne se rebelleront pas'::text,'ne se sont pas rebellés'::text,'Si le chef les avait écoutés, les employés ne se seraient pas rebellés contre lui.'::text),
(379241,42138,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patron onları dinleseydi, çalışanlar ona karşı ...'::text,'ayaklanmazdı'::text,'ayaklanmayacak'::text,'ayaklanmadı'::text,'Patron onları dinleseydi, çalışanlar ona karşı ayaklanmazdı.'::text),
(379242,42138,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a főnök meghallgatta volna őket, a dolgozók ... ellene.'::text,'nem lázadtak volna fel'::text,'nem fognak fellázadni'::text,'nem lázadtak fel'::text,'Ha a főnök meghallgatta volna őket, a dolgozók nem lázadtak volna fel ellene.'::text),
(379245,42139,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hätte das Personal nicht rebelliert, ... die Probanden jetzt ruhig an ihren Bildschirmen.'::text,'säßen'::text,'hätten gesessen'::text,'werden sitzen'::text,'Hätte das Personal nicht rebelliert, säßen die Probanden jetzt ruhig an ihren Bildschirmen.'::text),
(379249,42139,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби персонал не збунтувався, піддослідні зараз ... тихо за своїми екранами.'::text,'сиділи б'::text,'сиділи б'::text,'сидітимуть'::text,'Якби персонал не збунтувався, піддослідні зараз сиділи б тихо за своїми екранами.'::text),
(379248,42139,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el personal no se hubiera rebelado, los sujetos ... tranquilos frente a sus pantallas ahora.'::text,'estarían sentados'::text,'habrían estado sentados'::text,'estarán sentados'::text,'Si el personal no se hubiera rebelado, los sujetos estarían sentados tranquilos frente a sus pantallas ahora.'::text),
(379247,42139,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le personnel ne s''était pas rebellé, les sujets ... tranquillement devant leurs écrans maintenant.'::text,'seraient assis'::text,'auraient été assis'::text,'seront assis'::text,'Si le personnel ne s''était pas rebellé, les sujets seraient assis tranquillement devant leurs écrans maintenant.'::text),
(379250,42139,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personel ayaklanmasaydı, denekler şu an ekranlarının başında sessizce ...'::text,'oturuyor olurdu'::text,'oturmuş olurdu'::text,'oturacak'::text,'Personel ayaklanmasaydı, denekler şu an ekranlarının başında sessizce oturuyor olurdu.'::text),
(379251,42139,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a személyzet nem lázadt volna fel, az alanyok most csendben ... a képernyőjük előtt.'::text,'ülnének'::text,'ültek volna'::text,'ülni fognak'::text,'Ha a személyzet nem lázadt volna fel, az alanyok most csendben ülnének a képernyőjük előtt.'::text),
(379254,42140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Von ihr ist bekannt, dass sie sich schon einmal, letztes Jahr, gegen den Chef ...'::text,'aufgelehnt hat'::text,'auflehnt'::text,'Auflehnen'::text,'Von ihr ist bekannt, dass sie sich schon einmal, letztes Jahr, gegen den Chef aufgelehnt hat.'::text),
(379258,42140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відомо, що вона вже раз ... проти боса, минулого року.'::text,'бунтувала'::text,'бунтує'::text,'бунтування'::text,'Відомо, що вона вже раз бунтувала проти боса, минулого року.'::text),
(379257,42140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se sabe que ... contra el jefe una vez antes, el año pasado.'::text,'se rebeló'::text,'se rebela'::text,'rebelarse'::text,'Se sabe que se rebeló contra el jefe una vez antes, el año pasado.'::text),
(379256,42140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est connue pour ... contre le chef une fois déjà, l''année dernière.'::text,'s''être rebellée'::text,'se rebeller'::text,'se rebellant'::text,'Elle est connue pour s''être rebellée contre le chef une fois déjà, l''année dernière.'::text),
(379259,42140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun geçen yıl da bir kez patrona karşı ... biliniyor.'::text,'ayaklandığı'::text,'ayaklanacağı'::text,'ayaklanması'::text,'Onun geçen yıl da bir kez patrona karşı ayaklandığı biliniyor.'::text),
(379260,42140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köztudott, hogy egyszer már ... a főnök ellen, tavaly.'::text,'fellázadt'::text,'lázad'::text,'lázadás'::text,'Köztudott, hogy egyszer már fellázadt a főnök ellen, tavaly.'::text),
(379263,42141,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Chef warf ihr vor, das ganze Büro zur Rebellion ...'::text,'angestiftet zu haben'::text,'anzustiften'::text,'angestiftet'::text,'Der Chef warf ihr vor, das ganze Büro zur Rebellion angestiftet zu haben.'::text),
(379267,42141,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бос звинуватив її в тому, що вона ... весь офіс збунтуватися.'::text,'підбурила'::text,'підбурити'::text,'підбурила'::text,'Бос звинуватив її в тому, що вона підбурила весь офіс збунтуватися.'::text),
(379266,42141,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jefe la acusó de ... a toda la oficina de rebelarse.'::text,'convencer'::text,'convencer'::text,'convenció'::text,'El jefe la acusó de convencer a toda la oficina de rebelarse.'::text),
(379265,42141,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chef l''a accusée de ... tout le bureau à se rebeller.'::text,'avoir poussé'::text,'pousser'::text,'poussé'::text,'Le chef l''a accusée de avoir poussé tout le bureau à se rebeller.'::text),
(379268,42141,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patron onu bütün ofisi isyana ... suçladı.'::text,'kışkırtmakla'::text,'kışkırtmak'::text,'kışkırttı'::text,'Patron onu bütün ofisi isyana kışkırtmakla suçladı.'::text),
(379269,42141,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A főnök azzal vádolta, hogy ... az egész irodát a lázadásra.'::text,'rábeszélte'::text,'rábeszélni'::text,'rábeszélte'::text,'A főnök azzal vádolta, hogy rábeszélte az egész irodát a lázadásra.'::text),
(379281,42143,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie ... die Manager die ganze Etage so rebellieren sehen.'::text,'haben'::text,NULL::text,'hat'::text,'Noch nie haben die Manager die ganze Etage so rebellieren sehen.'::text),
(379285,42143,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ще менеджери ... не бачили, щоб увесь поверх так бунтував.'::text,''::text,NULL::text,NULL::text,'Ніколи ще менеджери не бачили, щоб увесь поверх так бунтував.'::text),
(379284,42143,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... visto los jefes a toda la planta rebelarse así.'::text,'han'::text,NULL::text,'ha'::text,'Nunca han visto los jefes a toda la planta rebelarse así.'::text),
(379283,42143,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais les managers ... vu tout l''étage se rebeller comme ça.'::text,'n''ont'::text,NULL::text,'n''a'::text,'Jamais les managers n''ont vu tout l''étage se rebeller comme ça.'::text),
(379286,42143,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yöneticiler ... tüm katın böyle isyan ettiğini hiç görmemişti.'::text,''::text,NULL::text,NULL::text,'Yöneticiler tüm katın böyle isyan ettiğini hiç görmemişti.'::text),
(379287,42143,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... nem látták még a menedzserek, hogy az egész emelet így lázadjon.'::text,''::text,NULL::text,NULL::text,'Soha nem látták még a menedzserek, hogy az egész emelet így lázadjon.'::text),
(379290,42144,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht: Der Chef hat seine neuen Regeln an einem Tag ... bekommen, und das ganze Büro hat rebelliert.'::text,'genehmigt'::text,'genehmigen'::text,'genehmigend'::text,'Super gemacht: Der Chef hat seine neuen Regeln an einem Tag genehmigt bekommen, und das ganze Büro hat rebelliert.'::text),
(379294,42144,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота: бос за один день домігся, щоб його нові правила ..., і весь офіс збунтувався.'::text,'затвердили'::text,'затвердити'::text,'затверджуючи'::text,'Чудова робота: бос за один день домігся, щоб його нові правила затвердили, і весь офіс збунтувався.'::text),
(379293,42144,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran trabajo: el jefe consiguió que ... sus nuevas normas en un día, y toda la oficina se rebeló.'::text,'aprobaran'::text,'aprobar'::text,'aprobando'::text,'Gran trabajo: el jefe consiguió que aprobaran sus nuevas normas en un día, y toda la oficina se rebeló.'::text),
(379292,42144,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo : le chef a fait ... ses nouvelles règles en une journée, et tout le bureau s''est rebellé.'::text,'valider'::text,'valider'::text,'validant'::text,'Bravo : le chef a fait valider ses nouvelles règles en une journée, et tout le bureau s''est rebellé.'::text),
(379295,42144,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş: patron yeni kurallarını bir günde ..., ve bütün ofis isyan etti.'::text,'onaylattı'::text,'onaylamak'::text,'onaylayarak'::text,'Harika iş: patron yeni kurallarını bir günde onaylattı, ve bütün ofis isyan etti.'::text),
(379296,42144,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka: a főnök egy nap alatt ... az új szabályait, és az egész iroda fellázadt.'::text,'elfogadtatta'::text,'elfogadni'::text,'elfogadva'::text,'Szép munka: a főnök egy nap alatt elfogadtatta az új szabályait, és az egész iroda fellázadt.'::text),
(355413,39491,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie das Rezept ..., machte sie einen Salat, weil ein Rezept zum Essenmachen da ist.'::text,'befolgte'::text,'befolgte'::text,'befolgt hat'::text,'Während sie das Rezept befolgte, machte sie einen Salat, weil ein Rezept zum Essenmachen da ist.'::text),
(355417,39491,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... рецепта, вона зробила салат, бо рецепт — це щоб готувати їжу.'::text,'дотримувалася'::text,'дотрималася'::text,'дотрималася'::text,'Поки вона дотримувалася рецепта, вона зробила салат, бо рецепт — це щоб готувати їжу.'::text),
(355416,39491,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... la receta, hizo una ensalada, porque una receta sirve para hacer comida.'::text,'seguía'::text,'siguió'::text,'ha seguido'::text,'Mientras seguía la receta, hizo una ensalada, porque una receta sirve para hacer comida.'::text),
(355415,39491,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... la recette, elle a fait une salade, parce qu''une recette, c''est pour faire à manger.'::text,'suivait'::text,'a suivi'::text,'a suivi'::text,'Pendant qu''elle suivait la recette, elle a fait une salade, parce qu''une recette, c''est pour faire à manger.'::text),
(355418,39491,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tarifi ... bir salata yaptı, çünkü tarif yemek yapmak içindir.'::text,'takip ederken'::text,'takip etti'::text,'takip etmiş'::text,'Tarifi takip ederken bir salata yaptı, çünkü tarif yemek yapmak içindir.'::text),
(355419,39491,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ... a receptet, csinált egy salátát, mert a recept arra való, hogy kaját csináljunk.'::text,'követte'::text,'követte'::text,'követte'::text,'Miközben követte a receptet, csinált egy salátát, mert a recept arra való, hogy kaját csináljunk.'::text),
(355422,39492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Versuchsperson ... das handgeschriebene Rezept seit etwa zwanzig Minuten Schritt für Schritt.'::text,'befolgt'::text,'befolgt gerade'::text,'befolgt'::text,'Die Versuchsperson befolgt das handgeschriebene Rezept seit etwa zwanzig Minuten Schritt für Schritt.'::text),
(355426,39492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт ... рукописного рецепта крок за кроком приблизно двадцять хвилин.'::text,'дотримується'::text,'дотримується'::text,'дотримується'::text,'Суб''єкт дотримується рукописного рецепта крок за кроком приблизно двадцять хвилин.'::text),
(355425,39492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto ... la receta manuscrita paso a paso desde hace aproximadamente veinte minutos.'::text,'sigue'::text,'está siguiendo'::text,'sigue'::text,'El sujeto sigue la receta manuscrita paso a paso desde hace aproximadamente veinte minutos.'::text),
(355424,39492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet ... la recette manuscrite étape par étape depuis environ vingt minutes.'::text,'suit'::text,'est en train de suivre'::text,'suit'::text,'Le sujet suit la recette manuscrite étape par étape depuis environ vingt minutes.'::text),
(355427,39492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek yaklaşık yirmi dakikadır el yazısı tarifi adım adım ...'::text,'takip ediyor'::text,'takip ediyor'::text,'takip eder'::text,'Denek yaklaşık yirmi dakikadır el yazısı tarifi adım adım takip ediyor.'::text),
(355428,39492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany körülbelül húsz perce lépésről lépésre ... a kézzel írt receptet.'::text,'követi'::text,'követi'::text,'követi'::text,'Az alany körülbelül húsz perce lépésről lépésre követi a kézzel írt receptet.'::text),
(355440,39494,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, du hast das handgeschriebene Rezept perfekt ...: Der Salat ist fertig.'::text,'befolgt'::text,'befolgt'::text,'befolgst'::text,'Ganz ehrlich, du hast das handgeschriebene Rezept perfekt befolgt: Der Salat ist fertig.'::text),
(355444,39494,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... того рукописного рецепта ідеально: салат готовий.'::text,'дотрималася'::text,'дотримувалася'::text,'дотримуєшся'::text,'Не буду брехати, ти дотрималася того рукописного рецепта ідеально: салат готовий.'::text),
(355443,39494,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ... esa receta manuscrita a la perfección: la ensalada está lista.'::text,'has seguido'::text,'has estado siguiendo'::text,'estás siguiendo'::text,'No te voy a mentir, has seguido esa receta manuscrita a la perfección: la ensalada está lista.'::text),
(355442,39494,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... cette recette manuscrite à la perfection : la salade est prête.'::text,'as suivi'::text,'as suivi'::text,'suis'::text,'Je vais pas mentir, tu as suivi cette recette manuscrite à la perfection : la salade est prête.'::text),
(355445,39494,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o el yazısı tarifi mükemmel ...: salata hazır.'::text,'uyguladın'::text,'uyguluyordun'::text,'uyguluyorsun'::text,'Yalan yok, o el yazısı tarifi mükemmel uyguladın: salata hazır.'::text),
(355446,39494,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, tökéletesen ... azt a kézzel írt receptet: kész a saláta.'::text,'követted'::text,'követted'::text,'követed'::text,'Nem fogok hazudni, tökéletesen követted azt a kézzel írt receptet: kész a saláta.'::text),
(355449,39495,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie das Olivenöl dazugab, ... sie jeden Schritt des Rezepts befolgt.'::text,'hatte'::text,'hat'::text,'befolgt'::text,'Als sie das Olivenöl dazugab, hatte sie jeden Schritt des Rezepts befolgt.'::text),
(355453,39495,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона налила оливкову олію, вона вже ... кожного кроку рецепта.'::text,'дотрималася'::text,'дотрималася'::text,'дотримується'::text,'Коли вона налила оливкову олію, вона вже дотрималася кожного кроку рецепта.'::text),
(355452,39495,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando echó el aceite de oliva, ya ... cada paso de la receta.'::text,'había seguido'::text,'ha seguido'::text,'sigue'::text,'Para cuando echó el aceite de oliva, ya había seguido cada paso de la receta.'::text),
(355451,39495,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle a versé l''huile d''olive, elle ... chaque étape de la recette.'::text,'avait suivi'::text,'a suivi'::text,'suit'::text,'Quand elle a versé l''huile d''olive, elle avait suivi chaque étape de la recette.'::text),
(355454,39495,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zeytinyağını döktüğünde tarifin her adımını çoktan ...'::text,'uygulamıştı'::text,'uyguladı'::text,'uyguluyor'::text,'Zeytinyağını döktüğünde tarifin her adımını çoktan uygulamıştı.'::text),
(355455,39495,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire ráöntötte az olívaolajat, a recept minden lépését ...'::text,'követte'::text,'követte'::text,'követi'::text,'Mire ráöntötte az olívaolajat, a recept minden lépését követte.'::text),
(355458,39496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie den nächsten Schritt befolgt, ... der Salat in zwei Minuten fertig.'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn sie den nächsten Schritt befolgt, ist der Salat in zwei Minuten fertig.'::text),
(355462,39496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона виконає наступний крок, салат ... готовий за дві хвилини.'::text,'буде'::text,'був би'::text,'був'::text,'Якщо вона виконає наступний крок, салат буде готовий за дві хвилини.'::text),
(355461,39496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sigue el siguiente paso, la ensalada ... lista en dos minutos.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si sigue el siguiente paso, la ensalada estará lista en dos minutos.'::text),
(355460,39496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle suit l''étape suivante, la salade ... prête dans deux minutes.'::text,'sera'::text,'serait'::text,'était'::text,'Si elle suit l''étape suivante, la salade sera prête dans deux minutes.'::text),
(355463,39496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sonraki adımı uygularsa salata iki dakikaya ...'::text,'hazır olacak'::text,'hazır olurdu'::text,'hazırdı'::text,'Bir sonraki adımı uygularsa salata iki dakikaya hazır olacak.'::text),
(355464,39496,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha követi a következő lépést, a saláta két perc múlva kész ...'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha követi a következő lépést, a saláta két perc múlva kész lesz.'::text),
(355467,39497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie sich nicht an die handgeschriebene Seite halten würde, ... der Salat nicht so gut aus.'::text,'sähe'::text,'sieht'::text,'sah'::text,'Wenn sie sich nicht an die handgeschriebene Seite halten würde, sähe der Salat nicht so gut aus.'::text),
(355471,39497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не дотримувалася рукописної сторінки, салат ... так добре.'::text,'не виглядав би'::text,'не виглядатиме'::text,'не виглядав'::text,'Якби вона не дотримувалася рукописної сторінки, салат не виглядав би так добре.'::text),
(355470,39497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no siguiera la página escrita a mano, la ensalada ... tan bien.'::text,'no se vería'::text,'no se verá'::text,'no se veía'::text,'Si no siguiera la página escrita a mano, la ensalada no se vería tan bien.'::text),
(355469,39497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ne suivait pas la page manuscrite, la salade ... aussi belle.'::text,'ne serait pas'::text,'ne sera pas'::text,'n''était pas'::text,'Si elle ne suivait pas la page manuscrite, la salade ne serait pas aussi belle.'::text),
(355472,39497,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El yazısı sayfayı takip etmeseydi, salata bu kadar güzel ...'::text,'görünmezdi'::text,'görünmeyecek'::text,'görünmedi'::text,'El yazısı sayfayı takip etmeseydi, salata bu kadar güzel görünmezdi.'::text),
(355473,39497,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem követné a kézzel írt oldalt, a saláta nem ... ilyen jól.'::text,'nézne ki'::text,'fog kinézni'::text,'nézett ki'::text,'Ha nem követné a kézzel írt oldalt, a saláta nem nézne ki ilyen jól.'::text),
(355476,39498,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... dieses Rezept jahrelang jeden Sonntag von ihrer Oma befolgt.'::text,'wurde'::text,'befolgte'::text,'war'::text,'Girl, angeblich wurde dieses Rezept jahrelang jeden Sonntag von ihrer Oma befolgt.'::text),
(355480,39498,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, цей рецепт роками ... її бабусею щонеділі.'::text,'виконувався'::text,'виконувала'::text,'виконувала'::text,'Подруго, кажуть, цей рецепт роками виконувався її бабусею щонеділі.'::text),
(355479,39498,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer esta receta ... por su abuela todos los domingos durante años.'::text,'era seguida'::text,'siguió'::text,'estaba siguiendo'::text,'Amiga, al parecer esta receta era seguida por su abuela todos los domingos durante años.'::text),
(355478,39498,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment cette recette ... par sa grand-mère tous les dimanches pendant des années.'::text,'était suivie'::text,'suivait'::text,'était en train de suivre'::text,'Meuf, apparemment cette recette était suivie par sa grand-mère tous les dimanches pendant des années.'::text),
(355481,39498,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bu tarif yıllarca her pazar büyükannesi tarafından ...'::text,'uygulanmış'::text,'uygulamış'::text,'uyguluyormuş'::text,'Kızım, bu tarif yıllarca her pazar büyükannesi tarafından uygulanmış.'::text),
(355482,39498,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ezt a receptet évekig minden vasárnap ... a nagymamája.'::text,'követte'::text,'követte'::text,'követte'::text,'Csajszi, állítólag ezt a receptet évekig minden vasárnap követte a nagymamája.'::text),
(355485,39499,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jede Zeile des handgeschriebenen Rezepts, bevor sie das Öl dazugab.'::text,'befolgte'::text,'wurde befolgt'::text,'befolgend'::text,'Sie befolgte jede Zeile des handgeschriebenen Rezepts, bevor sie das Öl dazugab.'::text),
(355489,39499,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... кожного рядка рукописного рецепта, перш ніж налити олію.'::text,'дотрималася'::text,'була дотримана'::text,'дотримуючись'::text,'Вона дотрималася кожного рядка рукописного рецепта, перш ніж налити олію.'::text),
(355488,39499,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cada línea de la receta manuscrita antes de echar el aceite.'::text,'Siguió'::text,'Fue seguida'::text,'Siguiendo'::text,'Siguió cada línea de la receta manuscrita antes de echar el aceite.'::text),
(355487,39499,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... chaque ligne de la recette manuscrite avant de verser l''huile.'::text,'a suivi'::text,'a été suivie'::text,'suivant'::text,'Elle a suivi chaque ligne de la recette manuscrite avant de verser l''huile.'::text),
(355490,39499,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağı dökmeden önce el yazısı tarifin her satırını ...'::text,'uyguladı'::text,'uygulandı'::text,'uygulayarak'::text,'Yağı dökmeden önce el yazısı tarifin her satırını uyguladı.'::text),
(355491,39499,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a kézzel írt recept minden sorát, mielőtt ráöntötte az olajat.'::text,'Követte'::text,'Követték'::text,'Követve'::text,'Követte a kézzel írt recept minden sorát, mielőtt ráöntötte az olajat.'::text),
(355494,39500,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Salat ist gut geworden, ... der Tatsache, dass sie das Rezept Schritt für Schritt befolgt hat.'::text,'dank'::text,'trotz'::text,'im Falle'::text,'Der Salat ist gut geworden, dank der Tatsache, dass sie das Rezept Schritt für Schritt befolgt hat.'::text),
(355498,39500,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Салат вдався ... тому, що вона дотримувалася рецепта крок за кроком.'::text,'завдяки'::text,'попри'::text,'у разі'::text,'Салат вдався завдяки тому, що вона дотримувалася рецепта крок за кроком.'::text),
(355497,39500,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ensalada salió bien ... que siguió la receta paso a paso.'::text,'gracias a'::text,'a pesar de'::text,'en caso de'::text,'La ensalada salió bien gracias a que siguió la receta paso a paso.'::text),
(355496,39500,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La salade est réussie ... fait qu''elle a suivi la recette étape par étape.'::text,'grâce au'::text,'malgré le'::text,'en cas du'::text,'La salade est réussie grâce au fait qu''elle a suivi la recette étape par étape.'::text),
(355499,39500,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Salata, tarifi adım adım uygulaması ... güzel oldu.'::text,'sayesinde'::text,'rağmen'::text,'durumunda'::text,'Salata, tarifi adım adım uygulaması sayesinde güzel oldu.'::text),
(355500,39500,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A saláta annak ... jól sikerült, hogy lépésről lépésre követte a receptet.'::text,'köszönhetően'::text,'ellenére'::text,'esetén'::text,'A saláta annak köszönhetően jól sikerült, hogy lépésről lépésre követte a receptet.'::text),
(379821,42203,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Verwandter ... eine ältere Frau auf die Wange, und dann erhoben alle ihre Gläser.'::text,'küsste'::text,'küsste gerade'::text,'hat geküsst'::text,'Ein Verwandter küsste eine ältere Frau auf die Wange, und dann erhoben alle ihre Gläser.'::text),
(379825,42203,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Родич ... літню жінку в щоку, а потім усі підняли келихи.'::text,'поцілував'::text,'цілував'::text,'поцілував'::text,'Родич поцілував літню жінку в щоку, а потім усі підняли келихи.'::text),
(379824,42203,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un pariente ... a una mujer mayor en la mejilla, y luego todos levantaron sus copas.'::text,'besó'::text,'estaba besando'::text,'ha besado'::text,'Un pariente besó a una mujer mayor en la mejilla, y luego todos levantaron sus copas.'::text),
(379823,42203,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un proche ... une femme âgée sur la joue, puis tout le monde a levé son verre.'::text,'a embrassé'::text,'embrassait'::text,'a embrassé'::text,'Un proche a embrassé une femme âgée sur la joue, puis tout le monde a levé son verre.'::text),
(379826,42203,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir akraba yaşlı bir kadını yanağından ..., sonra herkes kadehini kaldırdı.'::text,'öptü'::text,'öpüyordu'::text,'öpmüş'::text,'Bir akraba yaşlı bir kadını yanağından öptü, sonra herkes kadehini kaldırdı.'::text),
(379827,42203,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy rokon arcon ... egy idősebb nőt, aztán mindenki felemelte a poharát.'::text,'csókolt meg'::text,'csókolt'::text,'megcsókolt'::text,'Egy rokon arcon csókolt meg egy idősebb nőt, aztán mindenki felemelte a poharát.'::text),
(379830,42204,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oma hat bisher fünf Verwandte an der Tür ...'::text,'begrüßt'::text,'begrüßt'::text,'begrüßte'::text,'Oma hat bisher fünf Verwandte an der Tür begrüßt.'::text),
(379834,42204,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бабуся вже ... п''ятьох родичів біля дверей.'::text,'привітала'::text,'вітала'::text,'привітала'::text,'Бабуся вже привітала п''ятьох родичів біля дверей.'::text),
(379833,42204,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora, la abuela ... a cinco parientes en la puerta.'::text,'ha saludado'::text,'ha estado saludando'::text,'saludó'::text,'Hasta ahora, la abuela ha saludado a cinco parientes en la puerta.'::text),
(379832,42204,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, mamie ... cinq proches à la porte.'::text,'a accueilli'::text,'accueille'::text,'a accueilli'::text,'Jusqu''ici, mamie a accueilli cinq proches à la porte.'::text),
(379835,42204,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükanne şimdiye kadar kapıda beş akrabayı ...'::text,'karşıladı'::text,'karşılıyor'::text,'karşıladı'::text,'Büyükanne şimdiye kadar kapıda beş akrabayı karşıladı.'::text),
(379836,42204,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagyi eddig öt rokont ... az ajtóban.'::text,'üdvözölt'::text,'üdvözölt'::text,'üdvözölt'::text,'A nagyi eddig öt rokont üdvözölt az ajtóban.'::text),
(379839,42205,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, sie hat mir gesagt, sie wünscht sich, jeder Verwandte ... das ganze Jahr so glücklich.'::text,'wäre'::text,'ist'::text,'wird sein'::text,'Girl, sie hat mir gesagt, sie wünscht sich, jeder Verwandte wäre das ganze Jahr so glücklich.'::text),
(379843,42205,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що хотіла б, щоб кожен родич ... таким щасливим цілий рік.'::text,'був'::text,'є'::text,'буде'::text,'Подруго, вона сказала мені, що хотіла б, щоб кожен родич був таким щасливим цілий рік.'::text),
(379842,42205,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ojalá cada pariente ... así de feliz todo el año.'::text,'estuviera'::text,'está'::text,'estará'::text,'Amiga, me dijo que ojalá cada pariente estuviera así de feliz todo el año.'::text),
(379841,42205,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit qu''elle aimerait que chaque membre de la famille ... aussi heureux toute l''année.'::text,'soit'::text,'est'::text,'sera'::text,'Meuf, elle m''a dit qu''elle aimerait que chaque membre de la famille soit aussi heureux toute l''année.'::text),
(379844,42205,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana her akrabanın bütün yıl bu kadar mutlu ... dilediğini söyledi.'::text,'olmasını'::text,'olduğunu'::text,'olacağını'::text,'Kızım, bana her akrabanın bütün yıl bu kadar mutlu olmasını dilediğini söyledi.'::text),
(379845,42205,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, azt szeretné, ha minden rokon egész évben ilyen boldog ...'::text,'lenne'::text,'van'::text,'lesz'::text,'Csajszi, azt mondta, azt szeretné, ha minden rokon egész évben ilyen boldog lenne.'::text),
(379848,42206,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, der Mann, ... Kuchen zuerst ankam, ist angeblich ein Verwandter aus dem Ausland.'::text,'dessen'::text,'der'::text,'welcher'::text,'Hör zu, der Mann, dessen Kuchen zuerst ankam, ist angeblich ein Verwandter aus dem Ausland.'::text),
(379852,42206,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, чоловік, ... торт приїхав першим, начебто родич з-за кордону.'::text,'чий'::text,'який'::text,'що'::text,'Слухай, чоловік, чий торт приїхав першим, начебто родич з-за кордону.'::text),
(379851,42206,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, el hombre ... pastel llegó primero es, al parecer, un pariente del extranjero.'::text,'cuyo'::text,'que'::text,'el cual'::text,'Escucha, el hombre cuyo pastel llegó primero es, al parecer, un pariente del extranjero.'::text),
(379850,42206,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, l''homme ... le gâteau est arrivé en premier est apparemment un proche venu de l''étranger.'::text,'dont'::text,'qui'::text,'que'::text,'Écoute, l''homme dont le gâteau est arrivé en premier est apparemment un proche venu de l''étranger.'::text),
(379853,42206,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ... pastası ilk gelen adam güya yurt dışından bir akraba.'::text,''::text,NULL::text,NULL::text,'Dinle, pastası ilk gelen adam güya yurt dışından bir akraba.'::text),
(379854,42206,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, az a férfi, ... a tortája érkezett elsőként, állítólag egy külföldi rokon.'::text,'akinek'::text,'aki'::text,'ami'::text,'Figyelj, az a férfi, akinek a tortája érkezett elsőként, állítólag egy külföldi rokon.'::text),
(379857,42207,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, ..., der einen Kuchen mitgebracht hat, war Opas Bruder.'::text,'der einzige Verwandte'::text,'ein einziger Verwandter'::text,'einziger Verwandter'::text,'Bestie, ich hab gehört, der einzige Verwandte, der einen Kuchen mitgebracht hat, war Opas Bruder.'::text),
(379861,42207,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що ..., який приніс торт, був братом дідуся.'::text,'єдиний родич'::text,'єдиний родич'::text,'єдиний родич'::text,'Подруго, я чула, що єдиний родич, який приніс торт, був братом дідуся.'::text),
(379860,42207,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, he oído que ... que trajo un pastel era el hermano del abuelo.'::text,'el único pariente'::text,'un único pariente'::text,'único pariente'::text,'Amiga, he oído que el único pariente que trajo un pastel era el hermano del abuelo.'::text),
(379859,42207,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il paraît que ... qui a apporté un gâteau était le frère de papi.'::text,'le seul proche'::text,'un seul proche'::text,'seul proche'::text,'Ma belle, il paraît que le seul proche qui a apporté un gâteau était le frère de papi.'::text),
(379862,42207,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre pasta getiren ... dedenin kardeşiymiş.'::text,'tek akraba'::text,'bir tek akraba'::text,'tek akraba'::text,'Kanka, duyduğuma göre pasta getiren tek akraba dedenin kardeşiymiş.'::text),
(379863,42207,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy ..., aki tortát hozott, a nagypapa öccse volt.'::text,'az egyetlen rokon'::text,'egy egyetlen rokon'::text,'egyetlen rokon'::text,'Csajszi, azt hallottam, hogy az egyetlen rokon, aki tortát hozott, a nagypapa öccse volt.'::text),
(379866,42208,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des überfüllten Flurs fand natürlich jeder Verwandte Platz für eine Umarmung.'::text,'Trotz'::text,'Obwohl'::text,'Weil'::text,'Trotz des überfüllten Flurs fand natürlich jeder Verwandte Platz für eine Umarmung.'::text),
(379870,42208,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... переповнений коридор, кожен родич, звісно, знайшов місце для обіймів.'::text,'Попри'::text,'Хоча'::text,'Тому що'::text,'Попри переповнений коридор, кожен родич, звісно, знайшов місце для обіймів.'::text),
(379869,42208,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el pasillo abarrotado, cada pariente encontró sitio para un abrazo, claro.'::text,'A pesar de'::text,'Aunque'::text,'Porque'::text,'A pesar de el pasillo abarrotado, cada pariente encontró sitio para un abrazo, claro.'::text),
(379868,42208,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le couloir bondé, chaque proche a évidemment trouvé de la place pour un câlin.'::text,'Malgré'::text,'Bien que'::text,'Parce que'::text,'Malgré le couloir bondé, chaque proche a évidemment trouvé de la place pour un câlin.'::text),
(379871,42208,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalık koridora ..., her akraba sarılmaya belli ki yer buldu.'::text,'rağmen'::text,'gerçi'::text,'çünkü'::text,'Kalabalık koridora rağmen, her akraba sarılmaya belli ki yer buldu.'::text),
(379872,42208,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zsúfolt folyosó ... minden rokon nyilván talált helyet egy ölelésre.'::text,'ellenére'::text,'bár'::text,'mert'::text,'A zsúfolt folyosó ellenére minden rokon nyilván talált helyet egy ölelésre.'::text),
(379875,42209,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich wussten wir alle, dass dieser Verwandte wieder den größten Kuchen ...'::text,'mitbringen würde'::text,'mitbringen wird'::text,'mitbringt'::text,'Natürlich wussten wir alle, dass dieser Verwandte wieder den größten Kuchen mitbringen würde.'::text),
(379879,42209,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, ми всі знали, що цей родич знову ... найбільший торт.'::text,'принесе'::text,'принесе'::text,'несе'::text,'Звісно, ми всі знали, що цей родич знову принесе найбільший торт.'::text),
(379878,42209,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, todos sabíamos que este pariente ... otra vez el pastel más grande.'::text,'traería'::text,'traerá'::text,'está trayendo'::text,'Obviamente, todos sabíamos que este pariente traería otra vez el pastel más grande.'::text),
(379877,42209,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, on savait tous que ce proche ... encore le plus gros gâteau.'::text,'apporterait'::text,'apportera'::text,'apporte'::text,'Évidemment, on savait tous que ce proche apporterait encore le plus gros gâteau.'::text),
(379880,42209,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki hepimiz bu akrabanın yine en büyük pastayı ... biliyorduk.'::text,'getireceğini'::text,'getireceğini'::text,'getirdiğini'::text,'Tabii ki hepimiz bu akrabanın yine en büyük pastayı getireceğini biliyorduk.'::text),
(379881,42209,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván mindannyian tudtuk, hogy ez a rokon megint a legnagyobb tortát ...'::text,'hozza majd'::text,'fogja hozni'::text,'hozza'::text,'Nyilván mindannyian tudtuk, hogy ez a rokon megint a legnagyobb tortát hozza majd.'::text),
(379884,42210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Verwandten ... sich gerade in diesen winzigen Flur, das ist echt Chaos.'::text,'quetschen'::text,'quetschen'::text,'haben gequetscht'::text,'Bro, die Verwandten quetschen sich gerade in diesen winzigen Flur, das ist echt Chaos.'::text),
(379888,42210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, родичі прямо зараз ... в цей крихітний коридор, реально хаос.'::text,'втискаються'::text,'втискаються'::text,'втиснулися'::text,'Бро, родичі прямо зараз втискаються в цей крихітний коридор, реально хаос.'::text),
(379887,42210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, los parientes se ... en este pasillo diminuto ahora mismo, es un caos, en serio.'::text,'están metiendo'::text,'meten'::text,'han metido'::text,'Bro, los parientes se están metiendo en este pasillo diminuto ahora mismo, es un caos, en serio.'::text),
(379886,42210,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, la famille ... dans ce petit couloir en ce moment, c''est le chaos, sérieux.'::text,'s''entasse'::text,'s''entasse'::text,'s''est entassée'::text,'Frérot, la famille s''entasse dans ce petit couloir en ce moment, c''est le chaos, sérieux.'::text),
(379889,42210,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, akrabalar şu an bu minicik koridora ..., resmen kaos.'::text,'sıkışıyor'::text,'sıkışır'::text,'sıkıştı'::text,'Kanka, akrabalar şu an bu minicik koridora sıkışıyor, resmen kaos.'::text),
(379890,42210,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a rokonok most épp ... ebbe a pici előszobába, ez komolyan káosz.'::text,'préselődnek be'::text,'préselődnek be'::text,'préselődtek be'::text,'Tesó, a rokonok most épp préselődnek be ebbe a pici előszobába, ez komolyan káosz.'::text),
(379902,42212,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 20 Uhr wird sich jeder Verwandte dem Toast auf der Familienagenda ...'::text,'angeschlossen haben'::text,'anschließen'::text,'anschließt'::text,'Bis 20 Uhr wird sich jeder Verwandte dem Toast auf der Familienagenda angeschlossen haben.'::text),
(379906,42212,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 20:00 кожен родич ... до тосту з сімейного порядку денного.'::text,'приєднається'::text,'приєднається'::text,'приєднується'::text,'До 20:00 кожен родич приєднається до тосту з сімейного порядку денного.'::text),
(379905,42212,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para las 20:00, cada pariente ... al brindis de la agenda familiar.'::text,'se habrá unido'::text,'se unirá'::text,'se une'::text,'Para las 20:00, cada pariente se habrá unido al brindis de la agenda familiar.'::text),
(379904,42212,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici 20 h, chaque proche ... au toast prévu au programme familial.'::text,'se sera joint'::text,'se joindra'::text,'se joint'::text,'D''ici 20 h, chaque proche se sera joint au toast prévu au programme familial.'::text),
(379907,42212,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 20.00''ye kadar her akraba aile ajandasındaki kadeh kaldırmaya ...'::text,'katılmış olacak'::text,'katılacak'::text,'katılıyor'::text,'Saat 20.00''ye kadar her akraba aile ajandasındaki kadeh kaldırmaya katılmış olacak.'::text),
(379908,42212,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este 8-ra minden rokon ... a családi napirenden szereplő koccintáshoz.'::text,'csatlakozik'::text,'csatlakozni fog'::text,'csatlakozik'::text,'Este 8-ra minden rokon csatlakozik a családi napirenden szereplő koccintáshoz.'::text),
(371352,41262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie den Eid ..., begann Konfetti auf die Menge zu fallen.'::text,'ablegte'::text,'ablegte'::text,'abgelegt hat'::text,'Während sie den Eid ablegte, begann Konfetti auf die Menge zu fallen.'::text),
(371356,41262,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... присягу, на натовп почало падати конфетті.'::text,'складала'::text,'склала'::text,'склала'::text,'Поки вона складала присягу, на натовп почало падати конфетті.'::text),
(371355,41262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... el juramento, empezó a caer confeti sobre la multitud.'::text,'prestaba'::text,'prestó'::text,'ha prestado'::text,'Mientras prestaba el juramento, empezó a caer confeti sobre la multitud.'::text),
(371354,41262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... serment, des confettis ont commencé à tomber sur la foule.'::text,'prêtait'::text,'a prêté'::text,'a prêté'::text,'Pendant qu''elle prêtait serment, des confettis ont commencé à tomber sur la foule.'::text),
(371357,41262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yemin ..., kalabalığın üzerine konfeti yağmaya başladı.'::text,'ederken'::text,'etti'::text,'etmiş'::text,'O yemin ederken, kalabalığın üzerine konfeti yağmaya başladı.'::text),
(371358,41262,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ... az esküt, konfetti kezdett hullani a tömegre.'::text,'letette'::text,'letette'::text,'letette'::text,'Miközben letette az esküt, konfetti kezdett hullani a tömegre.'::text),
(371361,41263,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihr ganzes Leben auf diesen Eid, und jetzt rastet die Menge komplett aus!'::text,'wartet schon'::text,'wartet gerade'::text,'wartet'::text,'Sie wartet schon ihr ganzes Leben auf diesen Eid, und jetzt rastet die Menge komplett aus!'::text),
(371365,41263,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... на цю присягу все життя, а тепер натовп просто кричить!'::text,'чекала'::text,'чекає'::text,'чекає'::text,'Вона чекала на цю присягу все життя, а тепер натовп просто кричить!'::text),
(371364,41263,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... este juramento toda su vida, y ahora la multitud está gritando como loca!'::text,'Ha estado esperando'::text,'Está esperando'::text,'Espera'::text,'¡Ha estado esperando este juramento toda su vida, y ahora la multitud está gritando como loca!'::text),
(371363,41263,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... ce serment toute sa vie, et maintenant la foule hurle carrément !'::text,'a attendu'::text,'attend'::text,'attend'::text,'Elle a attendu ce serment toute sa vie, et maintenant la foule hurle carrément !'::text),
(371366,41263,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün hayatı boyunca bu yemini ..., ve şimdi kalabalık resmen çığlık atıyor!'::text,'bekledi'::text,'bekliyor'::text,'bekler'::text,'Bütün hayatı boyunca bu yemini bekledi, ve şimdi kalabalık resmen çığlık atıyor!'::text),
(371367,41263,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész életében erre az esküre ..., és most a tömeg teljesen őrjöng!'::text,'várt'::text,'vár'::text,'vár'::text,'Egész életében erre az esküre várt, és most a tömeg teljesen őrjöng!'::text),
(371370,41264,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Eid, als plötzlich das Konfetti über der Menge explodierte!'::text,'leistete gerade'::text,'leistete'::text,'hat geleistet'::text,'Sie leistete gerade den Eid, als plötzlich das Konfetti über der Menge explodierte!'::text),
(371374,41264,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... присягу, коли над натовпом раптом вибухнуло конфетті!'::text,'складала'::text,'склала'::text,'склала'::text,'Вона складала присягу, коли над натовпом раптом вибухнуло конфетті!'::text),
(371373,41264,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... el juramento cuando el confeti explotó de repente sobre la multitud!'::text,'Estaba prestando'::text,'Prestó'::text,'Ha prestado'::text,'¡Estaba prestando el juramento cuando el confeti explotó de repente sobre la multitud!'::text),
(371372,41264,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... serment quand les confettis ont soudain explosé au-dessus de la foule !'::text,'prêtait'::text,'a prêté'::text,'a prêté'::text,'Elle prêtait serment quand les confettis ont soudain explosé au-dessus de la foule !'::text),
(371375,41264,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalabalığın üzerinde aniden konfeti patladığında o yemin ...!'::text,'ediyordu'::text,'etti'::text,'etmiş'::text,'Kalabalığın üzerinde aniden konfeti patladığında o yemin ediyordu!'::text),
(371376,41264,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... az esküt, amikor a konfetti hirtelen felrobbant a tömeg felett!'::text,'tette le'::text,'letette'::text,'letette'::text,'Épp tette le az esküt, amikor a konfetti hirtelen felrobbant a tömeg felett!'::text),
(371388,41266,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, angeblich ... das Buch, auf das sie den Eid geschworen hat, sehr alt sein, aber keiner weiß es.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Warte, angeblich könnte das Buch, auf das sie den Eid geschworen hat, sehr alt sein, aber keiner weiß es.'::text),
(371392,41266,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чекай, кажуть, книжка, на якій вона присягала, ... бути дуже старою, але ніхто не знає.'::text,'може'::text,'мусить'::text,'не може'::text,'Чекай, кажуть, книжка, на якій вона присягала, може бути дуже старою, але ніхто не знає.'::text),
(371391,41266,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer el libro sobre el que juró ... ser muy antiguo, pero nadie lo sabe.'::text,'podría'::text,'debe de'::text,'no puede'::text,'Espera, al parecer el libro sobre el que juró podría ser muy antiguo, pero nadie lo sabe.'::text),
(371390,41266,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment le livre sur lequel elle a prêté serment ... être très vieux, mais personne ne sait.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'Attends, apparemment le livre sur lequel elle a prêté serment pourrait être très vieux, mais personne ne sait.'::text),
(371393,41266,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, güya yemin ettiği kitap çok eski ..., ama kimse bilmiyor.'::text,'olabilir'::text,'olmalı'::text,'olamaz'::text,'Dur, güya yemin ettiği kitap çok eski olabilir, ama kimse bilmiyor.'::text),
(371394,41266,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag a könyv, amire az esküt tette, nagyon régi ..., de senki sem tudja.'::text,'lehet'::text,'kell hogy legyen'::text,'nem lehet'::text,'Várj, állítólag a könyv, amire az esküt tette, nagyon régi lehet, de senki sem tudja.'::text),
(371397,41267,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, die Frau, ... den Eid abgelegt hat, war früher Lehrerin, hab ich gehört.'::text,'die'::text,'welche'::text,'deren'::text,'Hör zu, die Frau, die den Eid abgelegt hat, war früher Lehrerin, hab ich gehört.'::text),
(371401,41267,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, жінка, ... склала присягу, раніше була вчителькою, я чула.'::text,'яка'::text,'що'::text,'чия'::text,'Слухай, жінка, яка склала присягу, раніше була вчителькою, я чула.'::text),
(371400,41267,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, la mujer ... prestó juramento antes era profesora, según he oído.'::text,'que'::text,'la cual'::text,'cuya'::text,'Escucha, la mujer que prestó juramento antes era profesora, según he oído.'::text),
(371399,41267,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, la femme ... a prêté serment était prof avant, à ce qu''il paraît.'::text,'qui'::text,'laquelle'::text,'dont'::text,'Écoute, la femme qui a prêté serment était prof avant, à ce qu''il paraît.'::text),
(371402,41267,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, ... yemin eden kadın eskiden öğretmenmiş, öyle duydum.'::text,''::text,NULL::text,NULL::text,'Dinle, yemin eden kadın eskiden öğretmenmiş, öyle duydum.'::text),
(371403,41267,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a nő, ... letette az esküt, korábban tanár volt, azt hallottam.'::text,'aki'::text,'amely'::text,'akinek'::text,'Figyelj, a nő, aki letette az esküt, korábban tanár volt, azt hallottam.'::text),
(371406,41268,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor, sie hat den Reportern erzählt, dass sie ihren Eid am Abend davor ...'::text,'geübt hatte'::text,'geübt hat'::text,'übt'::text,'Stell dir vor, sie hat den Reportern erzählt, dass sie ihren Eid am Abend davor geübt hatte.'::text),
(371410,41268,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона сказала журналістам, що ... присягу напередодні ввечері.'::text,'репетирувала'::text,'репетирувала'::text,'репетирує'::text,'Уяви, вона сказала журналістам, що репетирувала присягу напередодні ввечері.'::text),
(371409,41268,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, les dijo a los periodistas que ... su juramento la noche anterior.'::text,'había ensayado'::text,'ha ensayado'::text,'ensaya'::text,'Adivina qué, les dijo a los periodistas que había ensayado su juramento la noche anterior.'::text),
(371408,41268,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle a dit aux journalistes qu''elle ... son serment la veille au soir.'::text,'avait répété'::text,'a répété'::text,'répète'::text,'Devine quoi, elle a dit aux journalistes qu''elle avait répété son serment la veille au soir.'::text),
(371411,41268,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, gazetecilere yeminini bir gece önce ... söyledi.'::text,'çalışmış olduğunu'::text,'çalıştığını'::text,'çalıştığını'::text,'Bil bakalım ne oldu, gazetecilere yeminini bir gece önce çalışmış olduğunu söyledi.'::text),
(371412,41268,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta az újságíróknak, hogy előző este ... az esküjét.'::text,'gyakorolta'::text,'gyakorolta'::text,'gyakorolja'::text,'Képzeld, azt mondta az újságíróknak, hogy előző este gyakorolta az esküjét.'::text),
(371415,41269,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... so schüchtern, und jetzt legst du vor Tausenden einen Eid ab.'::text,'warst früher'::text,'warst sonst'::text,'warst es gewohnt'::text,'Ehrlich, du warst früher so schüchtern, und jetzt legst du vor Tausenden einen Eid ab.'::text),
(371419,41269,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... така сором''язлива, а тепер складаєш присягу перед тисячами людей.'::text,'раніше була'::text,'бувала'::text,'звикла бути'::text,'Чесно, ти раніше була така сором''язлива, а тепер складаєш присягу перед тисячами людей.'::text),
(371418,41269,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... ser tan tímida, y ahora haces un juramento delante de miles de personas.'::text,'solías'::text,'solías'::text,'estabas acostumbrada a'::text,'La verdad, solías ser tan tímida, y ahora haces un juramento delante de miles de personas.'::text),
(371417,41269,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... si timide, et maintenant tu prêtes serment devant des milliers de gens.'::text,'étais'::text,'étais'::text,'avais l''habitude d''être'::text,'Franchement, tu étais si timide, et maintenant tu prêtes serment devant des milliers de gens.'::text),
(371420,41269,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, ... çok utangaç biriydin, şimdi ise binlerce kişinin önünde yemin ediyorsun.'::text,'eskiden'::text,'eskiden'::text,'eskiden'::text,'Açıkçası, eskiden çok utangaç biriydin, şimdi ise binlerce kişinin önünde yemin ediyorsun.'::text),
(371421,41269,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, régen ... ilyen félénk, most meg ezrek előtt teszel esküt.'::text,'voltál'::text,'voltál'::text,'hozzászoktál, hogy legyél'::text,'Őszintén, régen voltál ilyen félénk, most meg ezrek előtt teszel esküt.'::text),
(371424,41270,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, du hast nicht gezögert, diesen Eid vor der ganzen Menge ...'::text,'abzulegen'::text,'ablegen'::text,'ablegen'::text,'Ganz ehrlich, du hast nicht gezögert, diesen Eid vor der ganzen Menge abzulegen.'::text),
(371428,41270,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти не вагалася ... ту присягу перед усім натовпом.'::text,'скласти'::text,'складання'::text,'скласти'::text,'Не буду брехати, ти не вагалася скласти ту присягу перед усім натовпом.'::text),
(371427,41270,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, no dudaste en ... ese juramento delante de toda la multitud.'::text,'hacer'::text,'haciendo'::text,'hacer'::text,'No te voy a mentir, no dudaste en hacer ese juramento delante de toda la multitud.'::text),
(371426,41270,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu n''as pas hésité ... ce serment devant toute la foule.'::text,'à prêter'::text,'prêtant'::text,'prêter'::text,'Je vais pas mentir, tu n''as pas hésité à prêter ce serment devant toute la foule.'::text),
(371429,41270,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o yemini bütün kalabalığın önünde ... tereddüt etmedin.'::text,'etmekte'::text,'etmek'::text,'et'::text,'Yalan yok, o yemini bütün kalabalığın önünde etmekte tereddüt etmedin.'::text),
(371430,41270,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, nem habóztál ... azt az esküt az egész tömeg előtt.'::text,'letenni'::text,'letevés'::text,'letesz'::text,'Nem fogok hazudni, nem habóztál letenni azt az esküt az egész tömeg előtt.'::text),
(371442,41272,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie den Eid ablegte, ... die Menge stundenlang in der Sonne gewartet.'::text,'hatte'::text,'hat'::text,'wartet'::text,'Bevor sie den Eid ablegte, hatte die Menge stundenlang in der Sonne gewartet.'::text),
(371446,41272,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж вона склала присягу, натовп ... годинами на сонці.'::text,'чекав'::text,'чекає'::text,'чекає'::text,'Перш ніж вона склала присягу, натовп чекав годинами на сонці.'::text),
(371445,41272,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de que prestara juramento, la multitud ... durante horas al sol.'::text,'había estado esperando'::text,'ha estado esperando'::text,'está esperando'::text,'Antes de que prestara juramento, la multitud había estado esperando durante horas al sol.'::text),
(371444,41272,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant qu''elle prête serment, la foule ... pendant des heures au soleil.'::text,'avait attendu'::text,'a attendu'::text,'attend'::text,'Avant qu''elle prête serment, la foule avait attendu pendant des heures au soleil.'::text),
(371447,41272,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yemin etmeden önce kalabalık saatlerdir güneşin altında ...'::text,'bekliyordu'::text,'bekliyor'::text,'bekliyor'::text,'O yemin etmeden önce kalabalık saatlerdir güneşin altında bekliyordu.'::text),
(371448,41272,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt letette az esküt, a tömeg órákig ... a napon.'::text,'várt'::text,'vár'::text,'vár'::text,'Mielőtt letette az esküt, a tömeg órákig várt a napon.'::text),
(394734,43860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie in dieser Sonne weiter klettern, ... ihnen der Schweiß in die Augen.'::text,'läuft'::text,'würde laufen'::text,'lief'::text,'Wenn sie in dieser Sonne weiter klettern, läuft ihnen der Schweiß in die Augen.'::text),
(394738,43860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вони й далі підніматимуться на цьому сонці, піт ... їм в очі.'::text,'затече'::text,'затікав би'::text,'затік'::text,'Якщо вони й далі підніматимуться на цьому сонці, піт затече їм в очі.'::text),
(394737,43860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si siguen subiendo con este sol, el sudor les ... a los ojos.'::text,'caerá'::text,'caería'::text,'cayó'::text,'Si siguen subiendo con este sol, el sudor les caerá a los ojos.'::text),
(394736,43860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils continuent de grimper sous ce soleil, la sueur leur ... dans les yeux.'::text,'coulera'::text,'coulerait'::text,'a coulé'::text,'S''ils continuent de grimper sous ce soleil, la sueur leur coulera dans les yeux.'::text),
(394739,43860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu güneşte tırmanmaya devam ederlerse, ter gözlerine ...'::text,'akacak'::text,'akardı'::text,'aktı'::text,'Bu güneşte tırmanmaya devam ederlerse, ter gözlerine akacak.'::text),
(394740,43860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha tovább másznak ebben a napsütésben, az izzadság a szemükbe ...'::text,'fog folyni'::text,'folyna'::text,'folyt'::text,'Ha tovább másznak ebben a napsütésben, az izzadság a szemükbe fog folyni.'::text),
(394743,43861,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es am Hang Schatten gäbe, ... sie nicht so viel Schweiß.'::text,'verlören'::text,'verlieren'::text,'verlieren'::text,'Wenn es am Hang Schatten gäbe, verlören sie nicht so viel Schweiß.'::text),
(394747,43861,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби на схилі була тінь, вони ... стільки поту.'::text,'не втрачали б'::text,'не втратять'::text,'не втрачають'::text,'Якби на схилі була тінь, вони не втрачали б стільки поту.'::text),
(394746,43861,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera sombra en la ladera, ... tanto sudor.'::text,'no perderían'::text,'no perderán'::text,'no pierden'::text,'Si hubiera sombra en la ladera, no perderían tanto sudor.'::text),
(394745,43861,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il y avait de l''ombre sur la pente, ils ... autant de sueur.'::text,'ne perdraient pas'::text,'ne perdront pas'::text,'ne perdent pas'::text,'S''il y avait de l''ombre sur la pente, ils ne perdraient pas autant de sueur.'::text),
(394748,43861,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yamaçta gölge olsaydı, bu kadar çok ter ...'::text,'dökmezlerdi'::text,'dökmeyecekler'::text,'dökmüyorlar'::text,'Yamaçta gölge olsaydı, bu kadar çok ter dökmezlerdi.'::text),
(394749,43861,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha lenne árnyék a lejtőn, nem ... ennyi izzadságot.'::text,'veszítenének'::text,'fognak veszíteni'::text,'veszítenek'::text,'Ha lenne árnyék a lejtőn, nem veszítenének ennyi izzadságot.'::text),
(394752,43862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schweiß auf seinem Gesicht ... mit seiner Kappe abgewischt.'::text,'wird'::text,'wischt'::text,'wischt gerade'::text,'Der Schweiß auf seinem Gesicht wird mit seiner Kappe abgewischt.'::text),
(394756,43862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Піт з його обличчя ... кепкою.'::text,'витирається'::text,'витирає'::text,'витирає'::text,'Піт з його обличчя витирається кепкою.'::text),
(394755,43862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sudor de su cara ... con su gorra.'::text,'es secado'::text,'seca'::text,'está secando'::text,'El sudor de su cara es secado con su gorra.'::text),
(394754,43862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sueur sur son visage ... avec sa casquette.'::text,'est essuyée'::text,'essuie'::text,'est en train d''essuyer'::text,'La sueur sur son visage est essuyée avec sa casquette.'::text),
(394757,43862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzündeki ter şapkasıyla ...'::text,'siliniyor'::text,'siliyor'::text,'siliyor'::text,'Yüzündeki ter şapkasıyla siliniyor.'::text),
(394758,43862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az izzadságot az arcáról a sapkájával ...'::text,'törlik le'::text,'letörli'::text,'törli'::text,'Az izzadságot az arcáról a sapkájával törlik le.'::text),
(394761,43863,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Wanderer ... sich mit seiner Kappe den Schweiß aus dem Gesicht.'::text,'wischt'::text,'wird gewischt'::text,'wischend'::text,'Ein Wanderer wischt sich mit seiner Kappe den Schweiß aus dem Gesicht.'::text),
(394765,43863,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один турист ... піт з обличчя кепкою.'::text,'витирає'::text,'витирається'::text,'витираючи'::text,'Один турист витирає піт з обличчя кепкою.'::text),
(394764,43863,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un excursionista se ... el sudor de la cara con la gorra.'::text,'seca'::text,'es secado'::text,'secando'::text,'Un excursionista se seca el sudor de la cara con la gorra.'::text),
(394763,43863,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un randonneur ... la sueur de son visage avec sa casquette.'::text,'essuie'::text,'est essuyé'::text,'essuyant'::text,'Un randonneur essuie la sueur de son visage avec sa casquette.'::text),
(394766,43863,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşçülerden biri yüzündeki teri şapkasıyla ...'::text,'siliyor'::text,'siliniyor'::text,'silerek'::text,'Yürüyüşçülerden biri yüzündeki teri şapkasıyla siliyor.'::text),
(394767,43863,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egyik túrázó a sapkájával ... le az izzadságot az arcáról.'::text,'törli'::text,'törlődik'::text,'törölve'::text,'Az egyik túrázó a sapkájával törli le az izzadságot az arcáról.'::text),
(394770,43864,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein entspannter kleiner Spaziergang, ganz klar. Bei so viel Schweiß ... es leicht gewesen sein.'::text,'kann nicht'::text,'muss'::text,'könnte'::text,'Ein entspannter kleiner Spaziergang, ganz klar. Bei so viel Schweiß kann nicht es leicht gewesen sein.'::text),
(394774,43864,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розслаблювальна прогулянка, ясно. З таким потом це ... бути легко.'::text,'не могло'::text,'мусило'::text,'могло'::text,'Розслаблювальна прогулянка, ясно. З таким потом це не могло бути легко.'::text),
(394773,43864,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un paseíto relajante, claro. Con tanto sudor, ... haber sido fácil.'::text,'no puede'::text,'debe de'::text,'podría'::text,'Un paseíto relajante, claro. Con tanto sudor, no puede haber sido fácil.'::text),
(394772,43864,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une petite balade relaxante, clairement. Avec autant de sueur, ça ... être facile.'::text,'n''a pas pu'::text,'a dû'::text,'a pu'::text,'Une petite balade relaxante, clairement. Avec autant de sueur, ça n''a pas pu être facile.'::text),
(394775,43864,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahatlatıcı bir yürüyüş, belli. Bu kadar terle kolay ...'::text,'olmuş olamaz'::text,'olmuş olmalı'::text,'olmuş olabilir'::text,'Rahatlatıcı bir yürüyüş, belli. Bu kadar terle kolay olmuş olamaz.'::text),
(394776,43864,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kis pihentető séta, nyilván. Ennyi izzadsággal ez ... könnyű.'::text,'nem lehetett'::text,'biztos volt'::text,'lehetett'::text,'Egy kis pihentető séta, nyilván. Ennyi izzadsággal ez nem lehetett könnyű.'::text),
(394779,43865,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Wanderer, ... Gesicht voller Schweiß ist, hat einen makellosen Tag.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Wanderer, dessen Gesicht voller Schweiß ist, hat einen makellosen Tag.'::text),
(394783,43865,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Турист, ... обличчя вкрите потом, має бездоганний день.'::text,'чиє'::text,'який'::text,'що'::text,'Турист, чиє обличчя вкрите потом, має бездоганний день.'::text),
(394782,43865,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El excursionista ... cara está cubierta de sudor está teniendo un día perfecto.'::text,'cuya'::text,'que'::text,'el cual'::text,'El excursionista cuya cara está cubierta de sudor está teniendo un día perfecto.'::text),
(394781,43865,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le randonneur ... le visage est couvert de sueur passe une journée parfaite.'::text,'dont'::text,'qui'::text,'que'::text,'Le randonneur dont le visage est couvert de sueur passe une journée parfaite.'::text),
(394784,43865,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... yüzü terden sırılsıklam olan yürüyüşçü kusursuz bir gün geçiriyor.'::text,''::text,NULL::text,NULL::text,'Yüzü terden sırılsıklam olan yürüyüşçü kusursuz bir gün geçiriyor.'::text),
(394785,43865,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annak a túrázónak, ... az arcát beborítja az izzadság, tökéletes napja van.'::text,'akinek'::text,'aki'::text,'ami'::text,'Annak a túrázónak, akinek az arcát beborítja az izzadság, tökéletes napja van.'::text),
(394788,43866,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, der Schweiß ... ihm den ganzen Weg hoch in die Augen gelaufen.'::text,'sei'::text,'ist'::text,'läuft'::text,'Er sagte, der Schweiß sei ihm den ganzen Weg hoch in die Augen gelaufen.'::text),
(394792,43866,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що піт ... йому в очі всю дорогу вгору.'::text,'затікав'::text,'затікає'::text,'затікає'::text,'Він сказав, що піт затікав йому в очі всю дорогу вгору.'::text),
(394791,43866,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que el sudor le ... a los ojos durante toda la subida.'::text,'había estado cayendo'::text,'ha estado cayendo'::text,'está cayendo'::text,'Dijo que el sudor le había estado cayendo a los ojos durante toda la subida.'::text),
(394790,43866,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit que la sueur lui ... dans les yeux pendant toute la montée.'::text,'avait coulé'::text,'a coulé'::text,'coule'::text,'Il a dit que la sueur lui avait coulé dans les yeux pendant toute la montée.'::text),
(394793,43866,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yukarı çıkana kadar terin gözlerine ... söyledi.'::text,'akmış olduğunu'::text,'aktığını'::text,'aktığını'::text,'Yukarı çıkana kadar terin gözlerine akmış olduğunu söyledi.'::text),
(394794,43866,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy az izzadság egész úton felfelé a szemébe ...'::text,'folyt'::text,'folyik'::text,'folyik'::text,'Azt mondta, hogy az izzadság egész úton felfelé a szemébe folyt.'::text),
(394797,43867,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Studenten ... sie jeden Sommer ohne einen Tropfen Schweiß diese Wiese hoch.'::text,'wanderten'::text,'wanderten früher'::text,'waren es gewohnt zu wandern'::text,'Als Studenten wanderten sie jeden Sommer ohne einen Tropfen Schweiß diese Wiese hoch.'::text),
(394801,43867,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Студентами вони ... на цю луку щоліта без краплі поту.'::text,'ходили'::text,'колись ходили'::text,'звикли ходити'::text,'Студентами вони ходили на цю луку щоліта без краплі поту.'::text),
(394800,43867,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De estudiantes, ... esta pradera cada verano sin una gota de sudor.'::text,'subían'::text,'solían subir'::text,'estaban acostumbrados a subir'::text,'De estudiantes, subían esta pradera cada verano sin una gota de sudor.'::text),
(394799,43867,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand ils étaient étudiants, ils ... cette prairie chaque été sans une goutte de sueur.'::text,'montaient'::text,'avaient l''habitude de monter'::text,'étaient habitués à monter'::text,'Quand ils étaient étudiants, ils montaient cette prairie chaque été sans une goutte de sueur.'::text),
(394802,43867,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğrenciyken her yaz bu çayıra tek damla ter dökmeden ...'::text,'tırmanırlardı'::text,'tırmanırlardı'::text,'tırmanmaya alışkındılar'::text,'Öğrenciyken her yaz bu çayıra tek damla ter dökmeden tırmanırlardı.'::text),
(394803,43867,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diákként minden nyáron ... erre a rétre egy csepp izzadság nélkül.'::text,'fel-felmentek'::text,'régen felmentek'::text,'megszokták, hogy felmenjenek'::text,'Diákként minden nyáron fel-felmentek erre a rétre egy csepp izzadság nélkül.'::text),
(394806,43868,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie halten an, um sich den Schweiß aus dem Gesicht ...'::text,'abzuwischen'::text,'abwischen'::text,'abwischen'::text,'Sie halten an, um sich den Schweiß aus dem Gesicht abzuwischen.'::text),
(394810,43868,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони зупиняються, ... піт з облич.'::text,'щоб витерти'::text,'витирання'::text,'витерти'::text,'Вони зупиняються, щоб витерти піт з облич.'::text),
(394809,43868,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se paran ... el sudor de la cara.'::text,'para secarse'::text,'de secarse'::text,'secarse'::text,'Se paran para secarse el sudor de la cara.'::text),
(394808,43868,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils s''arrêtent ... la sueur de leur visage.'::text,'pour essuyer'::text,'d''essuyer'::text,'essuyer'::text,'Ils s''arrêtent pour essuyer la sueur de leur visage.'::text),
(394811,43868,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzlerindeki teri ... duruyorlar.'::text,'silmek için'::text,'silmeyi'::text,'sil'::text,'Yüzlerindeki teri silmek için duruyorlar.'::text),
(394812,43868,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megállnak, ... az izzadságot az arcukról.'::text,'hogy letöröljék'::text,'törölgetni'::text,'letöröl'::text,'Megállnak, hogy letöröljék az izzadságot az arcukról.'::text),
(394815,43869,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... ihm der Schweiß übers Gesicht, und dieser Aufstieg ist ein absoluter Albtraum!'::text,'strömt'::text,'strömt'::text,'ist geströmt'::text,'Gerade strömt ihm der Schweiß übers Gesicht, und dieser Aufstieg ist ein absoluter Albtraum!'::text),
(394819,43869,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз піт ... по його обличчю, а цей підйом — справжній кошмар!'::text,'ллється'::text,'ллється'::text,'полився'::text,'Прямо зараз піт ллється по його обличчю, а цей підйом — справжній кошмар!'::text),
(394818,43869,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ahora mismo el sudor le ... por la cara, y esta subida es una pesadilla total!'::text,'está chorreando'::text,'chorrea'::text,'ha chorreado'::text,'¡Ahora mismo el sudor le está chorreando por la cara, y esta subida es una pesadilla total!'::text),
(394817,43869,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la sueur lui ... sur le visage, et cette montée est un vrai cauchemar !'::text,'dégouline'::text,'dégouline'::text,'a dégouliné'::text,'En ce moment, la sueur lui dégouline sur le visage, et cette montée est un vrai cauchemar !'::text),
(394820,43869,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an ter yüzünden sel gibi ..., ve bu tırmanış tam bir kâbus!'::text,'akıyor'::text,'akar'::text,'aktı'::text,'Şu an ter yüzünden sel gibi akıyor, ve bu tırmanış tam bir kâbus!'::text),
(394821,43869,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... le az arcán az izzadság, és ez a mászás egy abszolút rémálom!'::text,'ömlik'::text,'ömlik'::text,'ömlött'::text,'Épp most ömlik le az arcán az izzadság, és ez a mászás egy abszolút rémálom!'::text),
(345324,38370,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Irgendwie ikonisch: Ich wette, du ... in jedem Land, das du besuchst, eine neue Küche.'::text,'probierst'::text,'wirst probieren'::text,'probierst gerade'::text,'Irgendwie ikonisch: Ich wette, du probierst in jedem Land, das du besuchst, eine neue Küche.'::text),
(345328,38370,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досить культово: б''юся об заклад, ти ... нову кухню в кожній країні, яку відвідаєш.'::text,'спробуєш'::text,'пробуватимеш'::text,'пробуєш'::text,'Досить культово: б''юся об заклад, ти спробуєш нову кухню в кожній країні, яку відвідаєш.'::text),
(345327,38370,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un poco icónico: apuesto a que ... una cocina nueva en cada país que visites.'::text,'probarás'::text,'estarás probando'::text,'estás probando'::text,'Un poco icónico: apuesto a que probarás una cocina nueva en cada país que visites.'::text),
(345326,38370,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un peu iconique : je parie que tu ... une nouvelle cuisine dans chaque pays que tu visites.'::text,'goûteras'::text,'seras en train de goûter'::text,'goûtes'::text,'Un peu iconique : je parie que tu goûteras une nouvelle cuisine dans chaque pays que tu visites.'::text),
(345329,38370,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biraz ikonik: bahse girerim gittiğin her ülkede yeni bir mutfak ...'::text,'deneyeceksin'::text,'deniyor olacaksın'::text,'deniyorsun'::text,'Biraz ikonik: bahse girerim gittiğin her ülkede yeni bir mutfak deneyeceksin.'::text),
(345330,38370,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kicsit ikonikus: lefogadom, hogy minden országban, ahová mész, ... egy új konyhát.'::text,'ki fogsz próbálni'::text,'próbálgatni fogsz'::text,'kipróbálsz'::text,'Kicsit ikonikus: lefogadom, hogy minden országban, ahová mész, ki fogsz próbálni egy új konyhát.'::text),
(345333,38371,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn eine neue Küche auf deinem Tisch ..., ist deine Reaktion jedes Mal ikonisch.'::text,'landet'::text,'landen wird'::text,'landete'::text,'Ehrlich, wenn eine neue Küche auf deinem Tisch landet, ist deine Reaktion jedes Mal ikonisch.'::text),
(345337,38371,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, коли нова кухня ... на твоєму столі, твоя реакція щоразу культова.'::text,'опиняється'::text,'опиниться'::text,'опинилася'::text,'Чесно, коли нова кухня опиняється на твоєму столі, твоя реакція щоразу культова.'::text),
(345336,38371,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, cuando una cocina nueva ... en tu mesa, tu reacción es icónica cada vez.'::text,'aterriza'::text,'aterrizará'::text,'aterrizó'::text,'La verdad, cuando una cocina nueva aterriza en tu mesa, tu reacción es icónica cada vez.'::text),
(345335,38371,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, quand une nouvelle cuisine ... sur ta table, ta réaction est iconique à chaque fois.'::text,'atterrit'::text,'atterrira'::text,'a atterri'::text,'Franchement, quand une nouvelle cuisine atterrit sur ta table, ta réaction est iconique à chaque fois.'::text),
(345338,38371,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, masana yeni bir mutfak ..., tepkin her seferinde ikonik.'::text,'gelince'::text,'gelecek'::text,'geldi'::text,'Açıkçası, masana yeni bir mutfak gelince, tepkin her seferinde ikonik.'::text),
(345339,38371,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha egy új konyha ... az asztalodon, a reakciód minden alkalommal ikonikus.'::text,'landol'::text,'landolni fog'::text,'landolt'::text,'Őszintén, ha egy új konyha landol az asztalodon, a reakciód minden alkalommal ikonikus.'::text),
(345342,38372,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Küche, ... Steak unter einer silbernen Glocke serviert, ist natürlich sehr bescheiden.'::text,'die'::text,'wer'::text,'deren'::text,'Eine Küche, die Steak unter einer silbernen Glocke serviert, ist natürlich sehr bescheiden.'::text),
(345346,38372,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кухня, ... подає стейк під срібним клошем, звісно, дуже скромна.'::text,'яка'::text,'хто'::text,'чия'::text,'Кухня, яка подає стейк під срібним клошем, звісно, дуже скромна.'::text),
(345345,38372,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una cocina ... sirve filete bajo una campana de plata es, obviamente, muy humilde.'::text,'que'::text,'quien'::text,'cuya'::text,'Una cocina que sirve filete bajo una campana de plata es, obviamente, muy humilde.'::text),
(345344,38372,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une cuisine ... sert le steak sous une cloche en argent est évidemment très modeste.'::text,'qui'::text,'qui'::text,'dont'::text,'Une cuisine qui sert le steak sous une cloche en argent est évidemment très modeste.'::text),
(345347,38372,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bifteği gümüş bir kapak altında servis eden bir mutfak tabii ki çok mütevazı.'::text,''::text,NULL::text,NULL::text,'Bifteği gümüş bir kapak altında servis eden bir mutfak tabii ki çok mütevazı.'::text),
(345348,38372,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a konyha, ... ezüst búra alatt szolgálja fel a steaket, nyilván nagyon szerény.'::text,'amely'::text,'aki'::text,'amelynek'::text,'Az a konyha, amely ezüst búra alatt szolgálja fel a steaket, nyilván nagyon szerény.'::text),
(345351,38373,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte dem Kellner, die Küche ... ein bisschen interessant. Eindeutig ein Mann mit wenig Gefühlen.'::text,'sei'::text,'werde sein'::text,'seien'::text,'Er sagte dem Kellner, die Küche sei ein bisschen interessant. Eindeutig ein Mann mit wenig Gefühlen.'::text),
(345355,38373,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав офіціантові, що кухня ... трохи цікава. Явно чоловік небагатьох емоцій.'::text,'була'::text,'буде'::text,'були'::text,'Він сказав офіціантові, що кухня була трохи цікава. Явно чоловік небагатьох емоцій.'::text),
(345354,38373,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dijo al camarero que la cocina ... un poco interesante. Claramente, un hombre de pocas emociones.'::text,'era'::text,'será'::text,'eran'::text,'Le dijo al camarero que la cocina era un poco interesante. Claramente, un hombre de pocas emociones.'::text),
(345353,38373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit au serveur que la cuisine ... un peu intéressante. Clairement un homme peu émotif.'::text,'était'::text,'sera'::text,'étaient'::text,'Il a dit au serveur que la cuisine était un peu intéressante. Clairement un homme peu émotif.'::text),
(345356,38373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Garsona mutfağın biraz ilginç ... söyledi. Belli ki az duygulu bir adam.'::text,'olduğunu'::text,'olacağını'::text,'olduklarını'::text,'Garsona mutfağın biraz ilginç olduğunu söyledi. Belli ki az duygulu bir adam.'::text),
(345357,38373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta a pincérnek, hogy a konyha ... kicsit érdekes. Nyilván egy kevés érzelmű ember.'::text,''::text,'lesz'::text,NULL::text,'Azt mondta a pincérnek, hogy a konyha kicsit érdekes. Nyilván egy kevés érzelmű ember.'::text),
(345360,38374,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... es, neue Küchen auszuprobieren, und jetzt guck ihn dir an, ohne Witz.'::text,'hasste früher'::text,'hasste sonst'::text,'ist es gewohnt zu hassen'::text,'Bro, er hasste früher es, neue Küchen auszuprobieren, und jetzt guck ihn dir an, ohne Witz.'::text),
(345364,38374,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... пробувати нову кухню, а тепер глянь на нього, без брехні.'::text,'колись ненавидів'::text,'ненавидів'::text,'звик ненавидіти'::text,'Бро, він колись ненавидів пробувати нову кухню, а тепер глянь на нього, без брехні.'::text),
(345363,38374,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él ... probar cocinas nuevas, y ahora míralo, sin mentir.'::text,'solía odiar'::text,'odiaba'::text,'está acostumbrado a odiar'::text,'Bro, él solía odiar probar cocinas nuevas, y ahora míralo, sin mentir.'::text),
(345362,38374,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... goûter de nouvelles cuisines, et maintenant regarde-le, sans mentir.'::text,'détestait'::text,'détestait'::text,'a l''habitude de détester'::text,'Frérot, il détestait goûter de nouvelles cuisines, et maintenant regarde-le, sans mentir.'::text),
(345365,38374,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eskiden yeni mutfakları denemekten ..., şimdi şuna bak, yalan yok.'::text,'nefret ederdi'::text,'nefret ederdi'::text,'nefret etmeye alışkın'::text,'Kanka, eskiden yeni mutfakları denemekten nefret ederdi, şimdi şuna bak, yalan yok.'::text),
(345366,38374,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő ... új konyhákat kipróbálni, most meg nézd, komolyan.'::text,'régen utált'::text,'utált'::text,'hozzá van szokva, hogy utáljon'::text,'Tesó, ő régen utált új konyhákat kipróbálni, most meg nézd, komolyan.'::text),
(345369,38375,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er will in jeder Stadt, die er besucht, eine neue Küche ...'::text,'ausprobieren'::text,'Ausprobieren'::text,'probier'::text,'Er will in jeder Stadt, die er besucht, eine neue Küche ausprobieren.'::text),
(345373,38375,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче ... нову кухню в кожному місті, яке відвідує.'::text,'спробувати'::text,'пробування'::text,'спробувати'::text,'Він хоче спробувати нову кухню в кожному місті, яке відвідує.'::text),
(345372,38375,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quiere ... una cocina nueva en cada ciudad que visita.'::text,'probar'::text,'probando'::text,'probar'::text,'Quiere probar una cocina nueva en cada ciudad que visita.'::text),
(345371,38375,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il veut ... une nouvelle cuisine dans chaque ville qu''il visite.'::text,'goûter'::text,'goûtant'::text,'goûter'::text,'Il veut goûter une nouvelle cuisine dans chaque ville qu''il visite.'::text),
(345374,38375,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gittiği her şehirde yeni bir mutfak ... istiyor.'::text,'denemek'::text,'denemeyi'::text,'dene'::text,'Gittiği her şehirde yeni bir mutfak denemek istiyor.'::text),
(345375,38375,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden városban, ahová megy, ... akar egy új konyhát.'::text,'kipróbálni'::text,'kipróbálás'::text,'kipróbál'::text,'Minden városban, ahová megy, kipróbálni akar egy új konyhát.'::text),
(345378,38376,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die marokkanische Küche kocht Eintöpfe in einer Tajine, ...?'::text,'oder?'::text,'nicht wahr?'::text,'stimmt''s?'::text,'Die marokkanische Küche kocht Eintöpfe in einer Tajine, oder?'::text),
(345382,38376,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Марокканська кухня готує рагу в тажині, ...?'::text,'правда?'::text,'хіба ні?'::text,'так?'::text,'Марокканська кухня готує рагу в тажині, правда?'::text),
(345381,38376,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cocina marroquí prepara guisos en un tajín, ¿...?'::text,'verdad?'::text,'no?'::text,'verdad?'::text,'La cocina marroquí prepara guisos en un tajín, ¿verdad?'::text),
(345380,38376,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cuisine marocaine prépare les ragoûts dans un tajine, ... ?'::text,'n''est-ce pas ?'::text,'non ?'::text,'pas vrai ?'::text,'La cuisine marocaine prépare les ragoûts dans un tajine, n''est-ce pas ?'::text),
(345383,38376,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fas mutfağında yahniler tajinde pişirilir, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Fas mutfağında yahniler tajinde pişirilir, değil mi?'::text),
(345384,38376,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A marokkói konyha tajine-ban főzi a ragut, ...?'::text,'ugye?'::text,'nem?'::text,'igaz?'::text,'A marokkói konyha tajine-ban főzi a ragut, ugye?'::text),
(345387,38377,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straßenküche hat ihn umgehauen, und ... der marokkanische Eintopf.'::text,'genauso'::text,'genauso'::text,'auch nicht'::text,'Die Straßenküche hat ihn umgehauen, und genauso der marokkanische Eintopf.'::text),
(345391,38377,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вулична кухня його вразила, і ... марокканське рагу.'::text,'так само'::text,'так само'::text,'ні'::text,'Вулична кухня його вразила, і так само марокканське рагу.'::text),
(345390,38377,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cocina callejera lo dejó alucinado, y ... el guiso marroquí.'::text,'también'::text,'también'::text,'tampoco'::text,'La cocina callejera lo dejó alucinado, y también el guiso marroquí.'::text),
(345389,38377,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La cuisine de rue l''a bluffé, et ... le ragoût marocain.'::text,'tout comme'::text,'tout comme'::text,'ni'::text,'La cuisine de rue l''a bluffé, et tout comme le ragoût marocain.'::text),
(345392,38377,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sokak mutfağı onu çok etkiledi, Fas yahnisi ...'::text,'de öyle'::text,'de öyle'::text,'de etkilemedi'::text,'Sokak mutfağı onu çok etkiledi, Fas yahnisi de öyle.'::text),
(345393,38377,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utcai konyha lenyűgözte, és a marokkói ragu ...'::text,'is'::text,'is'::text,'sem'::text,'Az utcai konyha lenyűgözte, és a marokkói ragu is.'::text),
(345396,38378,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... er gerade die dritte Küche auf seiner Reise.'::text,'probiert'::text,'probiert'::text,'hat probiert'::text,'Hör zu, angeblich probiert er gerade die dritte Küche auf seiner Reise.'::text),
(345400,38378,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, саме зараз він ... третю кухню за поїздку.'::text,'пробує'::text,'пробує'::text,'спробував'::text,'Слухай, кажуть, саме зараз він пробує третю кухню за поїздку.'::text),
(345399,38378,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer ahora mismo ... su tercera cocina del viaje.'::text,'está probando'::text,'prueba'::text,'ha probado'::text,'Escucha, al parecer ahora mismo está probando su tercera cocina del viaje.'::text),
(345398,38378,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment en ce moment il ... sa troisième cuisine du voyage.'::text,'goûte'::text,'goûte'::text,'a goûté'::text,'Écoute, apparemment en ce moment il goûte sa troisième cuisine du voyage.'::text),
(345401,38378,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya şu an yolculuğun üçüncü mutfağını ...'::text,'deniyor'::text,'dener'::text,'denedi'::text,'Dinle, güya şu an yolculuğun üçüncü mutfağını deniyor.'::text),
(345402,38378,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag most épp ... az út harmadik konyháját.'::text,'próbálja'::text,'próbálja'::text,'kipróbálta'::text,'Figyelj, állítólag most épp próbálja az út harmadik konyháját.'::text),
(366582,40732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, als die Sonne unterging, ... du schon stundenlang wie ein Profi in der Hängematte gechillt.'::text,'hattest'::text,'hast'::text,'chillst'::text,'Ehrlich, als die Sonne unterging, hattest du schon stundenlang wie ein Profi in der Hängematte gechillt.'::text),
(366586,40732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, коли сонце сіло, ти вже ... в тому гамаку годинами, як профі.'::text,'валялася'::text,'валялася'::text,'валяєшся'::text,'Чесно, коли сонце сіло, ти вже валялася в тому гамаку годинами, як профі.'::text),
(366585,40732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, cuando se puso el sol, ya ... horas tirada en esa hamaca como una pro.'::text,'habías estado'::text,'has estado'::text,'estás'::text,'La verdad, cuando se puso el sol, ya habías estado horas tirada en esa hamaca como una pro.'::text),
(366584,40732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, quand le soleil s''est couché, tu ... dans ce hamac pendant des heures comme une pro.'::text,'t''étais prélassée'::text,'t''es prélassée'::text,'te prélasses'::text,'Franchement, quand le soleil s''est couché, tu t''étais prélassée dans ce hamac pendant des heures comme une pro.'::text),
(366587,40732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, güneş battığında o hamakta saatlerdir profesyonel gibi ...'::text,'yayılmıştın'::text,'yayıldın'::text,'yayılıyorsun'::text,'Açıkçası, güneş battığında o hamakta saatlerdir profesyonel gibi yayılmıştın.'::text),
(366588,40732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, mire lement a nap, már órák óta ... abban a függőágyban, mint egy profi.'::text,'heverésztél'::text,'heverésztél'::text,'heverészel'::text,'Őszintén, mire lement a nap, már órák óta heverésztél abban a függőágyban, mint egy profi.'::text),
(366591,40733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein echter Profi: Morgen um diese Zeit wird er mit hochgelegten Stiefeln auf dem Sofa ...'::text,'am Rumlümmeln sein'::text,'rumlümmeln'::text,'lümmelt'::text,'Ein echter Profi: Morgen um diese Zeit wird er mit hochgelegten Stiefeln auf dem Sofa am Rumlümmeln sein.'::text),
(366595,40733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Справжній професіонал: завтра в цей час він ... на дивані з закинутими черевиками.'::text,'валятиметься'::text,'поваляється'::text,'валяється'::text,'Справжній професіонал: завтра в цей час він валятиметься на дивані з закинутими черевиками.'::text),
(366594,40733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo un profesional: mañana a esta hora ... tirado en el sofá con las botas en alto.'::text,'estará'::text,'estará'::text,'está'::text,'Todo un profesional: mañana a esta hora estará tirado en el sofá con las botas en alto.'::text),
(366593,40733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un vrai pro : demain à la même heure, il ... sur le canapé, les bottes en l''air.'::text,'sera en train de se prélasser'::text,'se prélassera'::text,'se prélasse'::text,'Un vrai pro : demain à la même heure, il sera en train de se prélasser sur le canapé, les bottes en l''air.'::text),
(366596,40733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçek bir profesyonel: yarın bu saatte botlarını uzatmış kanepede ...'::text,'yayılıyor olacak'::text,'yayılacak'::text,'yayılıyor'::text,'Gerçek bir profesyonel: yarın bu saatte botlarını uzatmış kanepede yayılıyor olacak.'::text),
(366597,40733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Igazi profi: holnap ilyenkor feltett csizmával ... a kanapén.'::text,'fog heverészni'::text,'heverészik majd'::text,'heverészik'::text,'Igazi profi: holnap ilyenkor feltett csizmával fog heverészni a kanapén.'::text),
(366609,40735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn du den ganzen Tag in der Hängematte ..., wirst du irgendwie faul, echt.'::text,'chillst'::text,'chilltest'::text,'chillen wirst'::text,'Bro, wenn du den ganzen Tag in der Hängematte chillst, wirst du irgendwie faul, echt.'::text),
(366613,40735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо ти ... в гамаку цілий день, стаєш якимось лінивим, реально.'::text,'валяєшся'::text,'валявся'::text,'валятимешся'::text,'Бро, якщо ти валяєшся в гамаку цілий день, стаєш якимось лінивим, реально.'::text),
(366612,40735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si ... en una hamaca todo el día, te vuelves medio vago, en serio.'::text,'te tiras'::text,'te tirabas'::text,'te tirarás'::text,'Bro, si te tiras en una hamaca todo el día, te vuelves medio vago, en serio.'::text),
(366611,40735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si tu ... dans un hamac toute la journée, tu deviens un peu flemmard, sérieux.'::text,'te prélasses'::text,'te prélassais'::text,'te prélasseras'::text,'Frérot, si tu te prélasses dans un hamac toute la journée, tu deviens un peu flemmard, sérieux.'::text),
(366614,40735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bütün gün hamakta ..., biraz tembelleşiyorsun, cidden.'::text,'yayılırsan'::text,'yayıldıysan'::text,'yayılacaksan'::text,'Kanka, bütün gün hamakta yayılırsan, biraz tembelleşiyorsun, cidden.'::text),
(366615,40735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha egész nap egy függőágyban ..., elég lusta leszel, komolyan.'::text,'heverészel'::text,'heverésztél'::text,'fogsz heverészni'::text,'Tesó, ha egész nap egy függőágyban heverészel, elég lusta leszel, komolyan.'::text),
(366618,40736,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, wenn er noch länger auf dem Sofa rumlümmelt, ... sein Chef sauer.'::text,'wird'::text,'würde'::text,'wurde'::text,'Nee Bro, wenn er noch länger auf dem Sofa rumlümmelt, wird sein Chef sauer.'::text),
(366622,40736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, якщо він ще довше валятиметься на тому дивані, його бос ...'::text,'розлютиться'::text,'розлютився б'::text,'розлютився'::text,'Не, бро, якщо він ще довше валятиметься на тому дивані, його бос розлютиться.'::text),
