(380580,42287,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El primer amigo retrocedió ante el ganso, y ...'::text,'los otros dos también.'::text,'los otros dos también.'::text,'los otros dos también.'::text,'El primer amigo retrocedió ante el ganso, y los otros dos también.'::text),
(380579,42287,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le premier ami a reculé devant l''oie, et ...'::text,'les deux autres aussi.'::text,'les deux autres aussi.'::text,'les deux autres aussi.'::text,'Le premier ami a reculé devant l''oie, et les deux autres aussi.'::text),
(380582,42287,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlk arkadaş kazdan geri çekildi, ...'::text,'diğer ikisi de öyle.'::text,'diğer ikisi de öyle.'::text,'diğer ikisi de öyle.'::text,'İlk arkadaş kazdan geri çekildi, diğer ikisi de öyle.'::text),
(380583,42287,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az első barát meghátrált a liba elől, és ...'::text,'a másik kettő is.'::text,'a másik kettő is.'::text,'a másik kettő is.'::text,'Az első barát meghátrált a liba elől, és a másik kettő is.'::text),
(380586,42288,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis die Gans wieder schnattert, werden sich die Freunde schon auf den Weg ...'::text,'zurückgezogen haben'::text,'zurückziehen'::text,'am Zurückziehen sein'::text,'Bis die Gans wieder schnattert, werden sich die Freunde schon auf den Weg zurückgezogen haben.'::text),
(380590,42288,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки гуска знову загелготить, друзі вже ... на стежку.'::text,'відступлять'::text,'відступлять'::text,'відступатимуть'::text,'Поки гуска знову загелготить, друзі вже відступлять на стежку.'::text),
(380589,42288,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando el ganso vuelva a graznar, los amigos ... hasta el camino.'::text,'se habrán retirado'::text,'se retirarán'::text,'se estarán retirando'::text,'Para cuando el ganso vuelva a graznar, los amigos se habrán retirado hasta el camino.'::text),
(380588,42288,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''oie cacardera à nouveau, les amis ... jusqu''au chemin.'::text,'auront reculé'::text,'reculeront'::text,'seront en train de reculer'::text,'Quand l''oie cacardera à nouveau, les amis auront reculé jusqu''au chemin.'::text),
(380591,42288,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaz tekrar ötene kadar arkadaşlar patikaya ...'::text,'çekilmiş olacak'::text,'çekilecek'::text,'çekiliyor olacak'::text,'Kaz tekrar ötene kadar arkadaşlar patikaya çekilmiş olacak.'::text),
(380592,42288,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a liba újra gágog, a barátok már ... az ösvényre.'::text,'visszahúzódnak'::text,'vissza fognak húzódni'::text,'épp visszahúzódnak'::text,'Mire a liba újra gágog, a barátok már visszahúzódnak az ösvényre.'::text),
(380595,42289,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Gans am Teich geblieben wäre, ... sie nicht von ihrem Picknick zurückgewichen.'::text,'wären'::text,'werden'::text,'sind'::text,'Wenn die Gans am Teich geblieben wäre, wären sie nicht von ihrem Picknick zurückgewichen.'::text),
(380599,42289,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби гуска лишилася біля ставка, вони ... зі свого пікніка.'::text,'не відступили б'::text,'не відступлять'::text,'не відступили'::text,'Якби гуска лишилася біля ставка, вони не відступили б зі свого пікніка.'::text),
(380598,42289,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el ganso se hubiera quedado junto al estanque, ... de su pícnic.'::text,'no se habrían retirado'::text,'no se retirarán'::text,'no se retiraron'::text,'Si el ganso se hubiera quedado junto al estanque, no se habrían retirado de su pícnic.'::text),
(380597,42289,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''oie était restée près de l''étang, ils ... de leur pique-nique.'::text,'n''auraient pas reculé'::text,'ne reculeront pas'::text,'n''ont pas reculé'::text,'Si l''oie était restée près de l''étang, ils n''auraient pas reculé de leur pique-nique.'::text),
(380600,42289,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaz göletin yanında kalsaydı, piknikten ...'::text,'çekilmezlerdi'::text,'çekilmeyecekler'::text,'çekilmediler'::text,'Kaz göletin yanında kalsaydı, piknikten çekilmezlerdi.'::text),
(380601,42289,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a liba a tónál maradt volna, nem ... a piknikjükről.'::text,'hátráltak volna el'::text,'fognak elhátrálni'::text,'hátráltak el'::text,'Ha a liba a tónál maradt volna, nem hátráltak volna el a piknikjükről.'::text),
(380613,42291,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... früher zurückweichen sollen, aber dieses Sandwich retten? Ziemlich mutig.'::text,'hättest'::text,'durftest nicht'::text,'konntest nicht'::text,'Du hättest früher zurückweichen sollen, aber dieses Sandwich retten? Ziemlich mutig.'::text),
(380617,42291,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тобі ... відступити раніше, але врятувати той сендвіч? Досить сміливо.'::text,'треба було'::text,'не можна було'::text,'не вдалося'::text,'Тобі треба було відступити раніше, але врятувати той сендвіч? Досить сміливо.'::text),
(380616,42291,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... retirarte antes, pero ¿salvar ese sándwich? Bastante valiente.'::text,'Debiste'::text,'No debiste'::text,'No pudiste'::text,'Debiste retirarte antes, pero ¿salvar ese sándwich? Bastante valiente.'::text),
(380615,42291,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... reculer plus tôt, mais sauver ce sandwich ? Plutôt courageux.'::text,'aurais dû'::text,'n''as pas dû'::text,'ne pouvais pas'::text,'Tu aurais dû reculer plus tôt, mais sauver ce sandwich ? Plutôt courageux.'::text),
(380618,42291,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha erken geri ..., ama o sandviçi kurtarmak mı? Epey cesurca.'::text,'çekilmeliydin'::text,'çekilmemiş olmalısın'::text,'çekilemezdin'::text,'Daha erken geri çekilmeliydin, ama o sandviçi kurtarmak mı? Epey cesurca.'::text),
(380619,42291,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hamarabb ... visszavonulni, de megmenteni azt a szendvicset? Elég bátor.'::text,'kellett volna'::text,'nem kellett'::text,'nem tudtál'::text,'Hamarabb kellett volna visszavonulni, de megmenteni azt a szendvicset? Elég bátor.'::text),
(380622,42292,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast die ganze Gruppe in zwei Sekunden vor dieser Gans ... lassen, Respekt.'::text,'zurückweichen'::text,'zurückzuweichen'::text,'zurückgewichen'::text,'Du hast die ganze Gruppe in zwei Sekunden vor dieser Gans zurückweichen lassen, Respekt.'::text),
(380626,42292,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти за дві секунди змусив усю групу ... від тієї гуски, респект.'::text,'відступити'::text,'відступити'::text,'відступила'::text,'Ти за дві секунди змусив усю групу відступити від тієї гуски, респект.'::text),
(380625,42292,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiciste que todo el grupo ... de ese ganso en dos segundos, respeto.'::text,'se retirara'::text,'retirarse'::text,'se retiró'::text,'Hiciste que todo el grupo se retirara de ese ganso en dos segundos, respeto.'::text),
(380624,42292,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as fait ... tout le groupe devant cette oie en deux secondes, respect.'::text,'reculer'::text,'de reculer'::text,'reculé'::text,'Tu as fait reculer tout le groupe devant cette oie en deux secondes, respect.'::text),
(380627,42292,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki saniyede bütün grubu o kazdan ..., saygılar.'::text,'geri çektirdin'::text,'geri çekilmek'::text,'geri çekildi'::text,'İki saniyede bütün grubu o kazdan geri çektirdin, saygılar.'::text),
(380628,42292,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két másodperc alatt ... az egész csapatot attól a libától, respekt.'::text,'meghátráltattad'::text,'meghátrálni'::text,'meghátrált'::text,'Két másodperc alatt meghátráltattad az egész csapatot attól a libától, respekt.'::text),
(380631,42293,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie zurückwichen, ... die Gans die Sandwiches schon erreicht, perfekte Planung.'::text,'hatte'::text,'erreichte'::text,'hat'::text,'Als sie zurückwichen, hatte die Gans die Sandwiches schon erreicht, perfekte Planung.'::text),
(380635,42293,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вони відступили, гуска вже ... до сендвічів, бездоганне планування.'::text,'дісталася'::text,'дісталася'::text,'дісталася'::text,'Коли вони відступили, гуска вже дісталася до сендвічів, бездоганне планування.'::text),
(380634,42293,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se retiraron, el ganso ya ... los sándwiches, planificación impecable.'::text,'había alcanzado'::text,'alcanzó'::text,'ha alcanzado'::text,'Para cuando se retiraron, el ganso ya había alcanzado los sándwiches, planificación impecable.'::text),
(380633,42293,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand ils ont reculé, l''oie ... déjà les sandwichs, organisation parfaite.'::text,'avait atteint'::text,'atteignit'::text,'a atteint'::text,'Quand ils ont reculé, l''oie avait atteint déjà les sandwichs, organisation parfaite.'::text),
(380636,42293,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar geri çekildiğinde kaz çoktan sandviçlere ..., kusursuz planlama.'::text,'ulaşmıştı'::text,'ulaştı'::text,'ulaştı'::text,'Onlar geri çekildiğinde kaz çoktan sandviçlere ulaşmıştı, kusursuz planlama.'::text),
(380637,42293,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire meghátráltak, a liba már ... a szendvicsekhez, hibátlan tervezés.'::text,'odaért'::text,'odaért'::text,'odaért'::text,'Mire meghátráltak, a liba már odaért a szendvicsekhez, hibátlan tervezés.'::text),
(380667,42297,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit ihrer Rückkehr um 9 Uhr ... sie auf dem Bett, statt den Reisebericht zu schreiben.'::text,'liegt'::text,'liegt'::text,'liegt'::text,'Seit ihrer Rückkehr um 9 Uhr liegt sie auf dem Bett, statt den Reisebericht zu schreiben.'::text),
(380671,42297,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після повернення о 9:00 вона ... на ліжку замість того, щоб писати звіт про поїздку.'::text,'лежить'::text,'лежить'::text,'лежить'::text,'Після повернення о 9:00 вона лежить на ліжку замість того, щоб писати звіт про поїздку.'::text),
(380670,42297,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde su regreso a las 9:00, ... tumbada en la cama en vez de escribir el informe del viaje.'::text,'lleva'::text,'está'::text,'está'::text,'Desde su regreso a las 9:00, lleva tumbada en la cama en vez de escribir el informe del viaje.'::text),
(380669,42297,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis son retour à 9 h, elle ... sur le lit au lieu de rédiger le rapport de voyage.'::text,'est allongée'::text,'est allongée'::text,'s''allonge'::text,'Depuis son retour à 9 h, elle est allongée sur le lit au lieu de rédiger le rapport de voyage.'::text),
(380672,42297,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 9''daki dönüşünden beri seyahat raporunu yazmak yerine yatakta ...'::text,'yatıyor'::text,'yatıyor'::text,'yatar'::text,'Saat 9''daki dönüşünden beri seyahat raporunu yazmak yerine yatakta yatıyor.'::text),
(380673,42297,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A 9 órai hazaérkezése óta az ágyon ... ahelyett, hogy megírná az úti jelentést.'::text,'fekszik'::text,'fekszik'::text,'fekszik'::text,'A 9 órai hazaérkezése óta az ágyon fekszik ahelyett, hogy megírná az úti jelentést.'::text),
(380676,42298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei ihrer Rückkehr öffnete sie die Tür und ... ihren Koffer rein, also war er drin.'::text,'zog'::text,'zog gerade'::text,'hat gezogen'::text,'Bei ihrer Rückkehr öffnete sie die Tür und zog ihren Koffer rein, also war er drin.'::text),
(380680,42298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після повернення вона відчинила двері й ... валізу всередину, тож вона була всередині.'::text,'затягла'::text,'затягувала'::text,'затягла'::text,'Після повернення вона відчинила двері й затягла валізу всередину, тож вона була всередині.'::text),
(380679,42298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al volver, abrió la puerta y ... la maleta dentro, así que estaba dentro.'::text,'metió'::text,'estaba metiendo'::text,'ha metido'::text,'Al volver, abrió la puerta y metió la maleta dentro, así que estaba dentro.'::text),
(380678,42298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À son retour, elle a ouvert la porte et ... sa valise à l''intérieur, donc elle était à l''intérieur.'::text,'a tiré'::text,'tirait'::text,'a tiré'::text,'À son retour, elle a ouvert la porte et a tiré sa valise à l''intérieur, donc elle était à l''intérieur.'::text),
(380681,42298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dönüşünde kapıyı açtı ve bavulunu içeri ..., yani bavul içerideydi.'::text,'çekti'::text,'çekiyordu'::text,'çekmiş'::text,'Dönüşünde kapıyı açtı ve bavulunu içeri çekti, yani bavul içerideydi.'::text),
(380682,42298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hazatérésekor kinyitotta az ajtót, és ... a bőröndjét, így az bent volt.'::text,'behúzta'::text,'húzta be'::text,'behúzta'::text,'Hazatérésekor kinyitotta az ajtót, és behúzta a bőröndjét, így az bent volt.'::text),
(380685,42299,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seit ihrer Rückkehr heute Morgen ... sie sich dreimal auf ihr eigenes Bett fallen lassen.'::text,'hat'::text,'hat'::text,'ließ'::text,'Seit ihrer Rückkehr heute Morgen hat sie sich dreimal auf ihr eigenes Bett fallen lassen.'::text),
(380689,42299,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відколи вона повернулася сьогодні вранці, вона ... на своє ліжко тричі.'::text,'плюхнулася'::text,'плюхалася'::text,'плюхнулася'::text,'Відколи вона повернулася сьогодні вранці, вона плюхнулася на своє ліжко тричі.'::text),
(380688,42299,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Desde su regreso esta mañana, se ... en su propia cama tres veces.'::text,'ha tirado'::text,'ha estado tirando'::text,'tiró'::text,'Desde su regreso esta mañana, se ha tirado en su propia cama tres veces.'::text),
(380687,42299,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis son retour ce matin, elle ... sur son propre lit trois fois.'::text,'s''est affalée'::text,'s''affale'::text,'s''est affalée'::text,'Depuis son retour ce matin, elle s''est affalée sur son propre lit trois fois.'::text),
(380690,42299,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabahki dönüşünden beri kendi yatağına üç kez ...'::text,'kendini attı'::text,'kendini atıyor'::text,'kendini attı'::text,'Bu sabahki dönüşünden beri kendi yatağına üç kez kendini attı.'::text),
(380691,42299,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggeli hazaérkezése óta háromszor ... a saját ágyára.'::text,'vetette le magát'::text,'vetette magát'::text,'vetette le magát'::text,'Ma reggeli hazaérkezése óta háromszor vetette le magát a saját ágyára.'::text),
(380694,42300,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor ihrer Rückkehr ... sie einen ganzen Monat weg gewesen.'::text,'war'::text,'ist'::text,'ist'::text,'Vor ihrer Rückkehr war sie einen ganzen Monat weg gewesen.'::text),
(380698,42300,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До свого повернення вона ... у від''їзді цілий місяць.'::text,'була'::text,'була'::text,'є'::text,'До свого повернення вона була у від''їзді цілий місяць.'::text),
(380697,42300,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de su regreso, ... fuera un mes entero.'::text,'había estado'::text,'ha estado'::text,'está'::text,'Antes de su regreso, había estado fuera un mes entero.'::text),
(380696,42300,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant son retour, elle ... partie un mois entier.'::text,'était'::text,'a été'::text,'est'::text,'Avant son retour, elle était partie un mois entier.'::text),
(380699,42300,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dönüşünden önce koca bir ay uzakta ...'::text,'kalmıştı'::text,'kaldı'::text,NULL::text,'Dönüşünden önce koca bir ay uzakta kalmıştı.'::text),
(380700,42300,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hazatérése előtt egy egész hónapig ... távol.'::text,'volt'::text,'volt'::text,'van'::text,'Hazatérése előtt egy egész hónapig volt távol.'::text),
(380703,42301,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihre Rückkehr gut läuft, ... sie den ganzen Nachmittag auf ihrem eigenen Bett.'::text,'liegt'::text,'läge'::text,'lag'::text,'Wenn ihre Rückkehr gut läuft, liegt sie den ganzen Nachmittag auf ihrem eigenen Bett.'::text),
(380707,42301,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо повернення пройде добре, вона ... на своєму ліжку всю другу половину дня.'::text,'лежатиме'::text,'лежала б'::text,'лежала'::text,'Якщо повернення пройде добре, вона лежатиме на своєму ліжку всю другу половину дня.'::text),
(380706,42301,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su regreso va bien, ... en su propia cama toda la tarde.'::text,'se tumbará'::text,'se tumbaría'::text,'se tumbó'::text,'Si su regreso va bien, se tumbará en su propia cama toda la tarde.'::text),
(380705,42301,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si son retour se passe bien, elle ... sur son propre lit tout l''après-midi.'::text,'restera allongée'::text,'resterait allongée'::text,'est restée allongée'::text,'Si son retour se passe bien, elle restera allongée sur son propre lit tout l''après-midi.'::text),
(380708,42301,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dönüşü iyi geçerse bütün öğleden sonra kendi yatağında ...'::text,'yatacak'::text,'yatardı'::text,'yattı'::text,'Dönüşü iyi geçerse bütün öğleden sonra kendi yatağında yatacak.'::text),
(380709,42301,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha jól alakul a hazatérése, egész délután a saját ágyán ...'::text,'fog feküdni'::text,'feküdne'::text,'feküdt'::text,'Ha jól alakul a hazatérése, egész délután a saját ágyán fog feküdni.'::text),
(380712,42302,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, meine Rückkehr ... so glücklich, aber meine Wohnung ist eine absolute Katastrophe!'::text,'wäre'::text,'ist'::text,'wird sein'::text,'Ich wünschte, meine Rückkehr wäre so glücklich, aber meine Wohnung ist eine absolute Katastrophe!'::text),
(380716,42302,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хотіла б я, щоб моє повернення ... таким щасливим, але моя квартира — повна катастрофа!'::text,'було'::text,'є'::text,'буде'::text,'Хотіла б я, щоб моє повернення було таким щасливим, але моя квартира — повна катастрофа!'::text),
(380715,42302,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá mi regreso ... así de feliz, pero mi piso es un desastre total!'::text,'fuera'::text,'es'::text,'será'::text,'¡Ojalá mi regreso fuera así de feliz, pero mi piso es un desastre total!'::text),
(380714,42302,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'J''aimerais que mon retour ... aussi joyeux, mais mon appart est une catastrophe totale !'::text,'soit'::text,'est'::text,'sera'::text,'J''aimerais que mon retour soit aussi joyeux, mais mon appart est une catastrophe totale !'::text),
(380717,42302,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke dönüşüm bu kadar mutlu ..., ama dairem tam bir felaket!'::text,'olsa'::text,NULL::text,'olacak'::text,'Keşke dönüşüm bu kadar mutlu olsa, ama dairem tam bir felaket!'::text),
(380718,42302,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak a hazatérésem ilyen boldog ..., de a lakásom egy abszolút katasztrófa!'::text,'lenne'::text,NULL::text,'lesz'::text,'Bárcsak a hazatérésem ilyen boldog lenne, de a lakásom egy abszolút katasztrófa!'::text),
(380721,42303,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Rückkehr, ... niemand so früh erwartet hatte, war absolut unglaublich!'::text,'die'::text,'welche'::text,'was'::text,'Ihre Rückkehr, die niemand so früh erwartet hatte, war absolut unglaublich!'::text),
(380725,42303,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її повернення, ... ніхто не чекав так скоро, було абсолютно неймовірним!'::text,'якого'::text,'що'::text,'що'::text,'Її повернення, якого ніхто не чекав так скоро, було абсолютно неймовірним!'::text),
(380724,42303,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su regreso, ... nadie esperaba tan pronto, fue absolutamente increíble!'::text,'que'::text,'que'::text,'lo que'::text,'¡Su regreso, que nadie esperaba tan pronto, fue absolutamente increíble!'::text),
(380723,42303,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son retour, ... personne n''attendait si tôt, était absolument incroyable !'::text,'que'::text,'que'::text,'ce que'::text,'Son retour, que personne n''attendait si tôt, était absolument incroyable !'::text),
(380726,42303,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Kimsenin bu kadar erken beklemediği dönüşü kesinlikle inanılmazdı!'::text,''::text,NULL::text,NULL::text,'Kimsenin bu kadar erken beklemediği dönüşü kesinlikle inanılmazdı!'::text),
(380727,42303,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hazatérése, ... senki sem várt ilyen hamar, abszolút hihetetlen volt!'::text,'amit'::text,'amelyet'::text,'ami'::text,'A hazatérése, amit senki sem várt ilyen hamar, abszolút hihetetlen volt!'::text),
(380739,42305,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ihrer langen Reise sah die Wohnung bei ihrer Rückkehr genau gleich aus.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz ihrer langen Reise sah die Wohnung bei ihrer Rückkehr genau gleich aus.'::text),
(380743,42305,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... її довгу подорож, квартира після повернення виглядала точнісінько так само.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри її довгу подорож, квартира після повернення виглядала точнісінько так само.'::text),
(380742,42305,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su largo viaje, el piso estaba exactamente igual a su regreso.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de su largo viaje, el piso estaba exactamente igual a su regreso.'::text),
(380741,42305,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... son long voyage, l''appart était exactement pareil à son retour.'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré son long voyage, l''appart était exactement pareil à son retour.'::text),
(380744,42305,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzun yolculuğuna ..., döndüğünde daire tamamen aynı görünüyordu.'::text,'rağmen'::text,'gerçi'::text,'yüzünden'::text,'Uzun yolculuğuna rağmen, döndüğünde daire tamamen aynı görünüyordu.'::text),
(380745,42305,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hosszú utazása ... a lakás pontosan ugyanúgy nézett ki, amikor hazaért.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Hosszú utazása ellenére a lakás pontosan ugyanúgy nézett ki, amikor hazaért.'::text),
(380748,42306,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis morgen wird sie ihre Rückkehr-Pics überall ..., echt.'::text,'gepostet haben'::text,'posten'::text,'postet'::text,'Bro, bis morgen wird sie ihre Rückkehr-Pics überall gepostet haben, echt.'::text),
(380752,42306,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до завтра вона ... фотки з повернення всюди, реально.'::text,'запостить'::text,'запостить'::text,'постить'::text,'Бро, до завтра вона запостить фотки з повернення всюди, реально.'::text),
(380751,42306,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para mañana ya ... sus fotos de la vuelta por todas partes, en serio.'::text,'habrá subido'::text,'subirá'::text,'sube'::text,'Bro, para mañana ya habrá subido sus fotos de la vuelta por todas partes, en serio.'::text),
(380750,42306,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, d''ici demain elle ... ses photos de retour partout, sérieux.'::text,'aura posté'::text,'postera'::text,'poste'::text,'Frérot, d''ici demain elle aura posté ses photos de retour partout, sérieux.'::text),
(380753,42306,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yarına kadar dönüş fotoğraflarını her yere ..., cidden.'::text,'paylaşmış olacak'::text,'paylaşacak'::text,'paylaşıyor'::text,'Kanka, yarına kadar dönüş fotoğraflarını her yere paylaşmış olacak, cidden.'::text),
(380754,42306,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, holnapra már mindenhova ... a hazaérkezős képeit, komolyan.'::text,'kiposztolja'::text,'ki fogja posztolni'::text,'posztolja'::text,'Tesó, holnapra már mindenhova kiposztolja a hazaérkezős képeit, komolyan.'::text),
(378354,42040,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfekte Planung: Sie ... immer ein Schild mit einem Namen darauf zum Bahnhof mit.'::text,'brachten'::text,'brachten früher'::text,'waren es gewohnt zu bringen'::text,'Perfekte Planung: Sie brachten immer ein Schild mit einem Namen darauf zum Bahnhof mit.'::text),
(378358,42040,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганне планування: вони завжди ... на вокзал табличку з ім''ям.'::text,'приносили'::text,'колись приносили'::text,'звикли приносити'::text,'Бездоганне планування: вони завжди приносили на вокзал табличку з ім''ям.'::text),
(378357,42040,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planificación impecable: siempre ... un cartel con un nombre a la estación de tren.'::text,'llevaban'::text,'solían llevar'::text,'estaban acostumbrados a llevar'::text,'Planificación impecable: siempre llevaban un cartel con un nombre a la estación de tren.'::text),
(378356,42040,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Organisation parfaite : ils ... toujours une pancarte avec un nom dessus à la gare.'::text,'apportaient'::text,'avaient l''habitude d''apporter'::text,'étaient habitués à apporter'::text,'Organisation parfaite : ils apportaient toujours une pancarte avec un nom dessus à la gare.'::text),
(378359,42040,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz planlama: tren istasyonuna hep üzerinde isim yazan bir tabela ...'::text,'getirirlerdi'::text,'getirirlerdi'::text,'getirmeye alışkındılar'::text,'Kusursuz planlama: tren istasyonuna hep üzerinde isim yazan bir tabela getirirlerdi.'::text),
(378360,42040,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan tervezés: mindig ... egy névvel ellátott táblát a vasútállomásra.'::text,'vittek'::text,'régen vittek'::text,'hozzá voltak szokva vinni'::text,'Hibátlan tervezés: mindig vittek egy névvel ellátott táblát a vasútállomásra.'::text),
(378363,42041,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die junge Frau konnte es kaum erwarten, ihm auf dem Bahnsteig in die Arme ...'::text,'zu springen'::text,'springend'::text,'springen'::text,'Die junge Frau konnte es kaum erwarten, ihm auf dem Bahnsteig in die Arme zu springen.'::text),
(378367,42041,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молода жінка не могла дочекатися, коли ... йому в обійми на пероні.'::text,'стрибне'::text,'стрибання'::text,'стрибнути'::text,'Молода жінка не могла дочекатися, коли стрибне йому в обійми на пероні.'::text),
(378366,42041,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La joven no podía esperar para ... a sus brazos en el andén.'::text,'lanzarse'::text,'lanzándose'::text,'lanzarse'::text,'La joven no podía esperar para lanzarse a sus brazos en el andén.'::text),
(378365,42041,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jeune femme avait hâte de ... dans ses bras sur le quai de la gare.'::text,'sauter'::text,'sautant'::text,'saute'::text,'La jeune femme avait hâte de sauter dans ses bras sur le quai de la gare.'::text),
(378368,42041,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç kadın perondaki adamın kollarına ... sabırsızlanıyordu.'::text,'atlamak için'::text,'atlamayı'::text,'atla'::text,'Genç kadın perondaki adamın kollarına atlamak için sabırsızlanıyordu.'::text),
(378369,42041,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal nő alig várta, hogy ... a karjaiba a vasúti peronon.'::text,'ugorjon'::text,'ugrás'::text,'ugrik'::text,'A fiatal nő alig várta, hogy ugorjon a karjaiba a vasúti peronon.'::text),
(378381,42043,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann fuhr auf dieser Bahnstrecke mit dem Zug nach Hause, und ...'::text,'die anderen Fahrgäste auch.'::text,'die anderen Fahrgäste auch.'::text,'die anderen Fahrgäste auch nicht.'::text,'Der Mann fuhr auf dieser Bahnstrecke mit dem Zug nach Hause, und die anderen Fahrgäste auch.'::text),
(378385,42043,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік їхав додому поїздом цією залізницею, і ...'::text,'інші пасажири теж.'::text,'інші пасажири теж.'::text,'інші пасажири теж ні.'::text,'Чоловік їхав додому поїздом цією залізницею, і інші пасажири теж.'::text),
(378384,42043,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre volvió a casa en tren por esta línea, y ...'::text,'los demás pasajeros también.'::text,'los demás pasajeros también.'::text,'los demás pasajeros tampoco.'::text,'El hombre volvió a casa en tren por esta línea, y los demás pasajeros también.'::text),
(378383,42043,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme est rentré chez lui en train sur cette ligne, et ...'::text,'les autres passagers aussi.'::text,'les autres passagers aussi.'::text,'les autres passagers non plus.'::text,'L''homme est rentré chez lui en train sur cette ligne, et les autres passagers aussi.'::text),
(378386,42043,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam bu demiryolunda trenle eve döndü, ...'::text,'diğer yolcular da öyle.'::text,'diğer yolcular da öyle.'::text,'diğer yolcular da dönmedi.'::text,'Adam bu demiryolunda trenle eve döndü, diğer yolcular da öyle.'::text),
(378387,42043,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi ezen a vasútvonalon vonattal utazott haza, és ...'::text,'a többi utas is.'::text,'a többi utas is.'::text,'a többi utas sem.'::text,'A férfi ezen a vasútvonalon vonattal utazott haza, és a többi utas is.'::text),
(378390,42044,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... stundenlang verzweifelt am Bahnhof gewartet, bevor er endlich ankam!'::text,'hatte'::text,'hat'::text,'wartete'::text,'Sie hatte stundenlang verzweifelt am Bahnhof gewartet, bevor er endlich ankam!'::text),
(378394,42044,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... у відчаї на вокзалі годинами, поки він нарешті не приїхав!'::text,'чекала'::text,'чекає'::text,'чекала'::text,'Вона чекала у відчаї на вокзалі годинами, поки він нарешті не приїхав!'::text),
(378393,42044,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... desesperada en la estación de tren durante horas antes de que por fin llegara!'::text,'Había estado esperando'::text,'Ha estado esperando'::text,'Estaba esperando'::text,'¡Había estado esperando desesperada en la estación de tren durante horas antes de que por fin llegara!'::text),
(378392,42044,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... désespérément à la gare pendant des heures avant qu''il arrive enfin !'::text,'avait attendu'::text,'a attendu'::text,'attendait'::text,'Elle avait attendu désespérément à la gare pendant des heures avant qu''il arrive enfin !'::text),
(378395,42044,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sonunda gelene kadar tren istasyonunda saatlerce çaresizce ...!'::text,'beklemişti'::text,'bekledi'::text,'bekliyordu'::text,'O sonunda gelene kadar tren istasyonunda saatlerce çaresizce beklemişti!'::text),
(378396,42044,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órákig ... kétségbeesetten a vasútállomáson, mire végre megérkezett!'::text,'várt'::text,'vár'::text,'várt'::text,'Órákig várt kétségbeesetten a vasútállomáson, mire végre megérkezett!'::text),
(378399,42045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wird diese Bahn Tausende verzweifelte Familien wieder ...!'::text,'zusammengebracht haben'::text,'zusammenbringen'::text,'am Zusammenbringen sein'::text,'Bis heute Abend wird diese Bahn Tausende verzweifelte Familien wieder zusammengebracht haben!'::text),
(378403,42045,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора ця залізниця ... тисячі зневірених родин знову разом!'::text,'збере'::text,'збере'::text,'збиратиме'::text,'До вечора ця залізниця збере тисячі зневірених родин знову разом!'::text),
(378402,42045,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para esta noche, esta línea de tren ... a miles de familias desesperadas!'::text,'habrá reunido'::text,'reunirá'::text,'estará reuniendo'::text,'¡Para esta noche, esta línea de tren habrá reunido a miles de familias desesperadas!'::text),
(378401,42045,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, cette ligne de train ... des milliers de familles désespérées !'::text,'aura réuni'::text,'réunira'::text,'sera en train de réunir'::text,'D''ici ce soir, cette ligne de train aura réuni des milliers de familles désespérées !'::text),
(378404,42045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar bu demiryolu binlerce çaresiz aileyi yeniden ...!'::text,'bir araya getirmiş olacak'::text,'bir araya getirecek'::text,'bir araya getiriyor olacak'::text,'Bu akşama kadar bu demiryolu binlerce çaresiz aileyi yeniden bir araya getirmiş olacak!'::text),
(378405,42045,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma estére ez a vasút több ezer kétségbeesett családot ...!'::text,'egyesít újra'::text,'fog újra egyesíteni'::text,'épp egyesíteni fog'::text,'Ma estére ez a vasút több ezer kétségbeesett családot egyesít újra!'::text),
(378408,42046,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Dezember wird er schon ein ganzes Jahr auf dieser Bahnstrecke ..., und alle vermissen ihn schrecklich!'::text,'unterwegs gewesen sein'::text,'unterwegs sein'::text,'reisen'::text,'Im Dezember wird er schon ein ganzes Jahr auf dieser Bahnstrecke unterwegs gewesen sein, und alle vermissen ihn schrecklich!'::text),
(378412,42046,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У грудні він ... цією залізницею вже цілий рік, і всі страшенно за ним сумують!'::text,'їздитиме'::text,'їздитиме'::text,'поїде'::text,'У грудні він їздитиме цією залізницею вже цілий рік, і всі страшенно за ним сумують!'::text),
(378411,42046,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡En diciembre, ... por esta línea de tren durante un año entero, y todos lo echan muchísimo de menos!'::text,'habrá estado viajando'::text,'estará viajando'::text,'viajará'::text,'¡En diciembre, habrá estado viajando por esta línea de tren durante un año entero, y todos lo echan muchísimo de menos!'::text),
(378410,42046,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En décembre, il ... sur cette ligne pendant une année entière, et il manque terriblement à tout le monde !'::text,'aura voyagé'::text,'sera en train de voyager'::text,'voyagera'::text,'En décembre, il aura voyagé sur cette ligne pendant une année entière, et il manque terriblement à tout le monde !'::text),
(378413,42046,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aralık ayında bu demiryolunda tam bir yıldır ..., ve herkes onu çok özlüyor!'::text,'yolculuk ediyor olacak'::text,'yolculuk ediyor olacak'::text,'yolculuk edecek'::text,'Aralık ayında bu demiryolunda tam bir yıldır yolculuk ediyor olacak, ve herkes onu çok özlüyor!'::text),
(378414,42046,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Decemberre már egy teljes éve ... ezen a vasútvonalon, és mindenkinek borzasztóan hiányzik!'::text,'utazik'::text,'fog utazni'::text,'utazik majd'::text,'Decemberre már egy teljes éve utazik ezen a vasútvonalon, és mindenkinek borzasztóan hiányzik!'::text),
(378417,42047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Zug Verspätung gehabt hätte, ... die Familie so lange auf dem Bahnsteig gewartet.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn der Zug Verspätung gehabt hätte, hätte die Familie so lange auf dem Bahnsteig gewartet.'::text),
(378421,42047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби поїзд запізнився, родина ... так довго на пероні.'::text,'чекала б'::text,'чекатиме'::text,'чекала'::text,'Якби поїзд запізнився, родина чекала б так довго на пероні.'::text),
(378420,42047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el tren se hubiera retrasado, la familia ... tanto tiempo en el andén.'::text,'habría esperado'::text,'esperará'::text,'esperó'::text,'Si el tren se hubiera retrasado, la familia habría esperado tanto tiempo en el andén.'::text),
(378419,42047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le train avait été en retard, la famille ... aussi longtemps sur le quai.'::text,'aurait attendu'::text,'attendra'::text,'a attendu'::text,'Si le train avait été en retard, la famille aurait attendu aussi longtemps sur le quai.'::text),
(378422,42047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tren gecikseydi aile peronda o kadar uzun ...'::text,'beklerdi'::text,'bekleyecek'::text,'bekledi'::text,'Tren gecikseydi aile peronda o kadar uzun beklerdi.'::text),
(378423,42047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a vonat késett volna, a család olyan sokáig ... a peronon.'::text,'várt volna'::text,'fog várni'::text,'várt'::text,'Ha a vonat késett volna, a család olyan sokáig várt volna a peronon.'::text),
(378426,42048,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er seinen Zug verpasst hätte, ... sich die Familie jetzt nicht auf dem Bahnsteig.'::text,'umarmte'::text,'hätte umarmt'::text,'wird umarmen'::text,'Wenn er seinen Zug verpasst hätte, umarmte sich die Familie jetzt nicht auf dem Bahnsteig.'::text),
(378430,42048,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він пропустив свій поїзд, родина ... на пероні прямо зараз.'::text,'не обіймалася б'::text,'не обійнялася б'::text,'не обійметься'::text,'Якби він пропустив свій поїзд, родина не обіймалася б на пероні прямо зараз.'::text),
(378429,42048,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera perdido el tren, la familia ... en el andén ahora mismo.'::text,'no estaría abrazándose'::text,'no se habría abrazado'::text,'no se abrazará'::text,'Si hubiera perdido el tren, la familia no estaría abrazándose en el andén ahora mismo.'::text),
(378428,42048,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait raté son train, la famille ... sur le quai en ce moment.'::text,'ne serait pas en train de s''enlacer'::text,'ne se serait pas enlacée'::text,'ne s''enlacera pas'::text,'S''il avait raté son train, la famille ne serait pas en train de s''enlacer sur le quai en ce moment.'::text),
(378431,42048,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trenini kaçırsaydı, aile şu an peronda ...'::text,'sarılmıyor olurdu'::text,'sarılmamış olurdu'::text,'sarılmayacak'::text,'Trenini kaçırsaydı, aile şu an peronda sarılmıyor olurdu.'::text),
(378432,42048,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha lekéste volna a vonatot, a család most nem ... a peronon.'::text,'ölelkezne'::text,'ölelkezett volna'::text,'fog ölelkezni'::text,'Ha lekéste volna a vonatot, a család most nem ölelkezne a peronon.'::text),
(378435,42049,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Bahnstrecke soll diese Stadt seit über hundert Jahren mit der Hauptstadt ...'::text,'verbunden haben'::text,'verbinden'::text,'verbindend'::text,'Die Bahnstrecke soll diese Stadt seit über hundert Jahren mit der Hauptstadt verbunden haben.'::text),
(378439,42049,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що залізниця ... це місто зі столицею понад сто років.'::text,'з''єднувала'::text,'з''єднує'::text,'з''єднання'::text,'Кажуть, що залізниця з''єднувала це місто зі столицею понад сто років.'::text),
(378438,42049,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que el ferrocarril ... esta ciudad con la capital desde hace más de cien años.'::text,'ha conectado'::text,'conecta'::text,'conectando'::text,'Se dice que el ferrocarril ha conectado esta ciudad con la capital desde hace más de cien años.'::text),
(378437,42049,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que la voie ferrée ... cette ville à la capitale depuis plus de cent ans.'::text,'a relié'::text,'relie'::text,'reliant'::text,'On dit que la voie ferrée a relié cette ville à la capitale depuis plus de cent ans.'::text),
(378440,42049,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demiryolunun bu kasabayı yüz yılı aşkın süredir başkente ... söyleniyor.'::text,'bağladığı'::text,'bağlayacağı'::text,'bağlaması'::text,'Demiryolunun bu kasabayı yüz yılı aşkın süredir başkente bağladığı söyleniyor.'::text),
(378441,42049,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, hogy a vasút több mint száz éve ... ezt a várost a fővárossal.'::text,'összeköti'::text,'összekötni'::text,'összekötve'::text,'Azt mondják, hogy a vasút több mint száz éve összeköti ezt a várost a fővárossal.'::text),
(393249,43695,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... auf ihrem Abendspaziergang an den Blumenständen vorbei, als die Laternen angingen.'::text,'lief gerade'::text,'lief'::text,'ist gelaufen'::text,'Sie lief gerade auf ihrem Abendspaziergang an den Blumenständen vorbei, als die Laternen angingen.'::text),
(393253,43695,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... повз квіткові ятки під час вечірньої прогулянки, коли засвітилися ліхтарики.'::text,'йшла'::text,'пройшла'::text,'пройшла'::text,'Вона йшла повз квіткові ятки під час вечірньої прогулянки, коли засвітилися ліхтарики.'::text),
(393252,43695,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... junto a los puestos de flores en su paseo de la tarde cuando se encendieron los farolillos.'::text,'Caminaba'::text,'Caminó'::text,'Ha caminado'::text,'Caminaba junto a los puestos de flores en su paseo de la tarde cuando se encendieron los farolillos.'::text),
(393251,43695,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... devant les étals de fleurs pendant sa balade du soir quand les lanternes se sont allumées.'::text,'passait'::text,'est passée'::text,'est passée'::text,'Elle passait devant les étals de fleurs pendant sa balade du soir quand les lanternes se sont allumées.'::text),
(393254,43695,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fenerler yandığında akşam yürüyüşünde çiçek tezgâhlarının önünden ...'::text,'geçiyordu'::text,'geçti'::text,'geçmiş'::text,'Fenerler yandığında akşam yürüyüşünde çiçek tezgâhlarının önünden geçiyordu.'::text),
(393255,43695,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a virágárusok standjai mellett az esti sétáján, amikor kigyulladtak a lampionok.'::text,'sétált el'::text,'elsétált'::text,'elsétált'::text,'Épp sétált el a virágárusok standjai mellett az esti sétáján, amikor kigyulladtak a lampionok.'::text),
(393258,43696,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn ich ihren Vibe hätte, ... ich jeden Abend so spazieren.'::text,'ginge'::text,'werde gehen'::text,'gehe'::text,'Bro, wenn ich ihren Vibe hätte, ginge ich jeden Abend so spazieren.'::text),
(393262,43696,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби в мене був її вайб, я ... на таку прогулянку щовечора.'::text,'ходив би'::text,'піду'::text,'ходжу'::text,'Бро, якби в мене був її вайб, я ходив би на таку прогулянку щовечора.'::text),
(393261,43696,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si tuviera su vibe, ... a dar un paseo así todas las noches.'::text,'iría'::text,'iré'::text,'voy'::text,'Bro, si tuviera su vibe, iría a dar un paseo así todas las noches.'::text),
(393260,43696,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si j''avais son vibe, ... faire une balade comme ça tous les soirs.'::text,'j''irais'::text,'j''irai'::text,'je vais'::text,'Frérot, si j''avais son vibe, j''irais faire une balade comme ça tous les soirs.'::text),
(393263,43696,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun vibe''ı bende olsaydı, her akşam öyle bir yürüyüşe ...'::text,'çıkardım'::text,'çıkacağım'::text,'çıkıyorum'::text,'Kanka, onun vibe''ı bende olsaydı, her akşam öyle bir yürüyüşe çıkardım.'::text),
(393264,43696,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nekem is ilyen vibe-om lenne, minden este ... egy ilyen sétára.'::text,'elmennék'::text,'el fogok menni'::text,'elmegyek'::text,'Tesó, ha nekem is ilyen vibe-om lenne, minden este elmennék egy ilyen sétára.'::text),
(393267,43697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der gestrige Spaziergang ... um 3 Meilensteine herum geplant: die Gasse, der Markt und die Dachterrasse.'::text,'wurde'::text,'wird'::text,'plante'::text,'Der gestrige Spaziergang wurde um 3 Meilensteine herum geplant: die Gasse, der Markt und die Dachterrasse.'::text),
(393271,43697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вчорашня прогулянка ... навколо 3 ключових етапів: провулок, ринок і дах.'::text,'була спланована'::text,'спланована'::text,'спланувала'::text,'Вчорашня прогулянка була спланована навколо 3 ключових етапів: провулок, ринок і дах.'::text),
(393270,43697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El paseo de ayer ... en torno a 3 hitos: el callejón, el mercado y la azotea.'::text,'fue planificado'::text,'es planificado'::text,'planificó'::text,'El paseo de ayer fue planificado en torno a 3 hitos: el callejón, el mercado y la azotea.'::text),
(393269,43697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La balade d''hier ... autour de 3 étapes clés : la ruelle, le marché et le toit.'::text,'a été planifiée'::text,'est planifiée'::text,'a planifié'::text,'La balade d''hier a été planifiée autour de 3 étapes clés : la ruelle, le marché et le toit.'::text),
(393272,43697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dünkü yürüyüş 3 kilometre taşı etrafında ...: ara sokak, pazar ve çatı.'::text,'planlandı'::text,'planlanıyor'::text,'planladı'::text,'Dünkü yürüyüş 3 kilometre taşı etrafında planlandı: ara sokak, pazar ve çatı.'::text),
(393273,43697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tegnapi sétát 3 mérföldkő köré ...: a sikátor, a piac és a tetőterasz.'::text,'tervezték'::text,'tervezik'::text,'tervezte'::text,'A tegnapi sétát 3 mérföldkő köré tervezték: a sikátor, a piac és a tetőterasz.'::text),
(393276,43698,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... einen langsamen Spaziergang, also ging sie langsam.'::text,'machte'::text,'wurde gemacht'::text,'machend'::text,'Sie machte einen langsamen Spaziergang, also ging sie langsam.'::text),
(393280,43698,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... повільну прогулянку, тож ішла повільно.'::text,'вийшла на'::text,'була виведена на'::text,'виходячи на'::text,'Вона вийшла на повільну прогулянку, тож ішла повільно.'::text),
(393279,43698,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un paseo lento, así que caminó despacio.'::text,'Dio'::text,'Fue dado'::text,'Dando'::text,'Dio un paseo lento, así que caminó despacio.'::text),
(393278,43698,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... une balade lente, donc elle a marché lentement.'::text,'a fait'::text,'a été faite'::text,'faisant'::text,'Elle a fait une balade lente, donc elle a marché lentement.'::text),
(393281,43698,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavaş bir yürüyüş ..., yani yavaş yürüdü.'::text,'yaptı'::text,'yapıldı'::text,'yaparak'::text,'Yavaş bir yürüyüş yaptı, yani yavaş yürüdü.'::text),
(393282,43698,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... egy lassú sétát, ezért lassan sétált.'::text,'tett'::text,'tétetett'::text,'téve'::text,'Ő tett egy lassú sétát, ezért lassan sétált.'::text),
(393285,43699,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das langsame Tempo zeigt klar, dass der Spaziergang dem Vergnügen dienen ..., nicht dem Training.'::text,'muss'::text,'kann nicht'::text,'könnte'::text,'Das langsame Tempo zeigt klar, dass der Spaziergang dem Vergnügen dienen muss, nicht dem Training.'::text),
(393289,43699,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повільний темп чітко вказує, що прогулянка ... бути для задоволення, а не для тренування.'::text,'мусить'::text,'не може'::text,'може'::text,'Повільний темп чітко вказує, що прогулянка мусить бути для задоволення, а не для тренування.'::text),
(393288,43699,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ritmo lento indica claramente que el paseo ... ser por placer, no por ejercicio.'::text,'debe de'::text,'no puede'::text,'podría'::text,'El ritmo lento indica claramente que el paseo debe de ser por placer, no por ejercicio.'::text),
(393287,43699,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le rythme lent indique clairement que la balade ... être pour le plaisir, pas pour le sport.'::text,'doit'::text,'ne peut pas'::text,'pourrait'::text,'Le rythme lent indique clairement que la balade doit être pour le plaisir, pas pour le sport.'::text),
(393290,43699,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavaş tempo, yürüyüşün egzersiz için değil keyif için ... açıkça gösteriyor.'::text,'olması gerektiğini'::text,'olamayacağını'::text,'olabileceğini'::text,'Yavaş tempo, yürüyüşün egzersiz için değil keyif için olması gerektiğini açıkça gösteriyor.'::text),
(393291,43699,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lassú tempó egyértelműen jelzi, hogy a séta ... kedvtelésből van, nem edzésből.'::text,'biztosan'::text,'nem lehet, hogy'::text,'lehet, hogy'::text,'A lassú tempó egyértelműen jelzi, hogy a séta biztosan kedvtelésből van, nem edzésből.'::text),
(393303,43701,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, dass du einen Spaziergang aufs Dach ..., und ehrlich, was für eine Aussicht.'::text,'machen würdest'::text,'machen wirst'::text,'machst'::text,'Du hast gesagt, dass du einen Spaziergang aufs Dach machen würdest, und ehrlich, was für eine Aussicht.'::text),
(393307,43701,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказала, що ... на прогулянку на дах, і чесно, який краєвид.'::text,'підеш'::text,'підеш'::text,'ходиш'::text,'Ти сказала, що підеш на прогулянку на дах, і чесно, який краєвид.'::text),
(393306,43701,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste que ... un paseo hasta la azotea, y la verdad, qué vistas.'::text,'darías'::text,'darás'::text,'das'::text,'Dijiste que darías un paseo hasta la azotea, y la verdad, qué vistas.'::text),
(393305,43701,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que tu ... une balade jusqu''au toit, et franchement, quelle vue.'::text,'ferais'::text,'feras'::text,'fais'::text,'Tu as dit que tu ferais une balade jusqu''au toit, et franchement, quelle vue.'::text),
(393308,43701,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatıya bir yürüyüş ... söyledin, ve açıkçası, ne manzara ama.'::text,'yapacağını'::text,'yapacağını'::text,'yaptığını'::text,'Çatıya bir yürüyüş yapacağını söyledin, ve açıkçası, ne manzara ama.'::text),
(393309,43701,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy ... egy sétát a tetőre, és őszintén, micsoda kilátás.'::text,'teszel'::text,'fogsz tenni'::text,'teszel'::text,'Azt mondtad, hogy teszel egy sétát a tetőre, és őszintén, micsoda kilátás.'::text),
(393312,43702,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... langsame Spaziergänge? Ehrlich, dieser hier sagt was anderes.'::text,'hasstest früher'::text,'hasstest sonst'::text,'warst gewohnt zu hassen'::text,'Du hasstest früher langsame Spaziergänge? Ehrlich, dieser hier sagt was anderes.'::text),
(393316,43702,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... повільні прогулянки? Чесно, ця каже протилежне.'::text,'колись ненавиділа'::text,'ненавиділа'::text,'звикла ненавидіти'::text,'Ти колись ненавиділа повільні прогулянки? Чесно, ця каже протилежне.'::text),
(393315,43702,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... odiar los paseos lentos? La verdad, este dice lo contrario.'::text,'Solías'::text,'Solías'::text,'Estabas acostumbrada a'::text,'¿Solías odiar los paseos lentos? La verdad, este dice lo contrario.'::text),
(393314,43702,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... les balades lentes ? Franchement, celle-ci dit le contraire.'::text,'détestais'::text,'détestais'::text,'avais l''habitude de détester'::text,'Tu détestais les balades lentes ? Franchement, celle-ci dit le contraire.'::text),
(393317,43702,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yavaş yürüyüşlerden ...? Açıkçası, bu yürüyüş tam tersini söylüyor.'::text,'eskiden nefret mi ederdin'::text,'nefret mi ederdin'::text,'nefret etmeye alışkın mıydın'::text,'Yavaş yürüyüşlerden eskiden nefret mi ederdin? Açıkçası, bu yürüyüş tam tersini söylüyor.'::text),
(393318,43702,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ... a lassú sétákat? Őszintén, ez az ellenkezőjét mutatja.'::text,'régen utáltad'::text,'utáltad'::text,'hozzá voltál szokva, hogy utáld'::text,'Te régen utáltad a lassú sétákat? Őszintén, ez az ellenkezőjét mutatja.'::text),
(393321,43703,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie vermied es, irgendetwas Schnelleres als einen Spaziergang ..., ein echter Profi.'::text,'zu machen'::text,'machen'::text,'mach'::text,'Sie vermied es, irgendetwas Schnelleres als einen Spaziergang zu machen, ein echter Profi.'::text),
(393325,43703,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона уникала ... будь-чого швидшого за прогулянку, справжня професіоналка.'::text,'робити'::text,'робити'::text,'роби'::text,'Вона уникала робити будь-чого швидшого за прогулянку, справжня професіоналка.'::text),
(393324,43703,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evitó ... cualquier cosa más rápida que un paseo, toda una profesional.'::text,'hacer'::text,'hacer'::text,'haz'::text,'Evitó hacer cualquier cosa más rápida que un paseo, toda una profesional.'::text),
(393323,43703,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a évité de ... quoi que ce soit de plus rapide qu''une balade, une vraie pro.'::text,'faire'::text,'faire'::text,'fais'::text,'Elle a évité de faire quoi que ce soit de plus rapide qu''une balade, une vraie pro.'::text),
(393326,43703,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşten daha hızlı herhangi bir şey ... kaçındı, gerçek bir profesyonel.'::text,'yapmaktan'::text,'yapmak'::text,'yap'::text,'Yürüyüşten daha hızlı herhangi bir şey yapmaktan kaçındı, gerçek bir profesyonel.'::text),
(393327,43703,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kerülte, hogy bármi gyorsabbat ..., mint egy séta, igazi profi.'::text,'csináljon'::text,'csinálni'::text,'csinál'::text,'Kerülte, hogy bármi gyorsabbat csináljon, mint egy séta, igazi profi.'::text),
(393339,43705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... erst fünf Minuten gelaufen, als ihr Spaziergang sie zum Blumenmarkt führte.'::text,'war'::text,'lief'::text,'lief gerade'::text,'Sie war erst fünf Minuten gelaufen, als ihr Spaziergang sie zum Blumenmarkt führte.'::text),
(393343,43705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... п''ять хвилин, коли прогулянка привела її на квітковий ринок.'::text,'ішла'::text,'пройшлася'::text,'ішла'::text,'Вона ішла п''ять хвилин, коли прогулянка привела її на квітковий ринок.'::text),
(393342,43705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... durante cinco minutos cuando su paseo la llevó al mercado de flores.'::text,'Había estado caminando'::text,'Caminó'::text,'Estaba caminando'::text,'Había estado caminando durante cinco minutos cuando su paseo la llevó al mercado de flores.'::text),
(393341,43705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... depuis cinq minutes quand sa balade l''a menée au marché aux fleurs.'::text,'marchait'::text,'a marché'::text,'marchait'::text,'Elle marchait depuis cinq minutes quand sa balade l''a menée au marché aux fleurs.'::text),
(393344,43705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşü onu çiçek pazarına getirdiğinde beş dakikadır ...'::text,'yürüyordu'::text,'yürüdü'::text,'yürüyordu'::text,'Yürüyüşü onu çiçek pazarına getirdiğinde beş dakikadır yürüyordu.'::text),
(393345,43705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öt perce ..., amikor a sétája a virágpiacra vitte.'::text,'sétált'::text,'sétált'::text,'sétált'::text,'Öt perce sétált, amikor a sétája a virágpiacra vitte.'::text),
(382116,42458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mein Mitbewohner ... diesen Müllsack seit drei Tagen, diese Wohnung ist eine komplette Katastrophe!'::text,'ignoriert'::text,'ignoriert gerade'::text,'ignoriert'::text,'Mein Mitbewohner ignoriert diesen Müllsack seit drei Tagen, diese Wohnung ist eine komplette Katastrophe!'::text),
(382120,42458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мій сусід по квартирі ... той мішок зі сміттям уже три дні, ця квартира — повна катастрофа!'::text,'ігнорує'::text,'ігнорує'::text,'ігнорує'::text,'Мій сусід по квартирі ігнорує той мішок зі сміттям уже три дні, ця квартира — повна катастрофа!'::text),
(382119,42458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mi compañero de piso ... esa bolsa de basura desde hace tres días, este piso es un desastre total!'::text,'lleva ignorando'::text,'está ignorando'::text,'ignora'::text,'¡Mi compañero de piso lleva ignorando esa bolsa de basura desde hace tres días, este piso es un desastre total!'::text),
(382118,42458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mon coloc ... ce sac poubelle depuis trois jours, cet appart est une catastrophe totale !'::text,'ignore'::text,'est en train d''ignorer'::text,'ignore'::text,'Mon coloc ignore ce sac poubelle depuis trois jours, cet appart est une catastrophe totale !'::text),
(382121,42458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev arkadaşım üç gündür o çöp torbasını ..., bu ev tam bir felaket!'::text,'görmezden geliyor'::text,'görmezden geliyor'::text,'görmezden gelir'::text,'Ev arkadaşım üç gündür o çöp torbasını görmezden geliyor, bu ev tam bir felaket!'::text),
(382122,42458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lakótársam három napja ... azt a szemeteszsákot, ez a lakás egy totális katasztrófa!'::text,'ignorálja'::text,'ignorálja'::text,'ignorálja'::text,'A lakótársam három napja ignorálja azt a szemeteszsákot, ez a lakás egy totális katasztrófa!'::text),
(382134,42460,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir erzählt, dass sein Mitbewohner diese Woche zweimal den Müll ...'::text,'rausgebracht hat'::text,'rausgebracht hat'::text,'rausbringt'::text,'Girl, er hat mir erzählt, dass sein Mitbewohner diese Woche zweimal den Müll rausgebracht hat.'::text),
(382138,42460,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що його сусід цього тижня двічі ... сміття.'::text,'виніс'::text,'виносив'::text,'виносить'::text,'Подруго, він сказав мені, що його сусід цього тижня двічі виніс сміття.'::text),
(382137,42460,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que su compañero de piso ... la basura dos veces esta semana.'::text,'ha sacado'::text,'ha estado sacando'::text,'está sacando'::text,'Amiga, me dijo que su compañero de piso ha sacado la basura dos veces esta semana.'::text),
(382136,42460,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit que son coloc ... les poubelles deux fois cette semaine.'::text,'a sorti'::text,'a sorti'::text,'sort'::text,'Meuf, il m''a dit que son coloc a sorti les poubelles deux fois cette semaine.'::text),
(382139,42460,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana ev arkadaşının bu hafta çöpü iki kez ... söyledi.'::text,'çıkardığını'::text,'çıkardığını'::text,'çıkarmakta olduğunu'::text,'Kızım, bana ev arkadaşının bu hafta çöpü iki kez çıkardığını söyledi.'::text),
(382140,42460,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy a lakótársa ezen a héten kétszer ... a szemetet.'::text,'vitte ki'::text,'vitte ki'::text,'viszi ki'::text,'Csajszi, azt mondta, hogy a lakótársa ezen a héten kétszer vitte ki a szemetet.'::text),
(382143,42461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... sein Mitbewohner die Pasta schon gekocht, bevor das Spiel überhaupt anfing.'::text,'hatte'::text,'hat'::text,'kocht'::text,'Okay, also angeblich hatte sein Mitbewohner die Pasta schon gekocht, bevor das Spiel überhaupt anfing.'::text),
(382147,42461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, його сусід ... пасту ще до того, як гра взагалі почалася.'::text,'зварив'::text,'зварив'::text,'варить'::text,'Коротше, кажуть, його сусід зварив пасту ще до того, як гра взагалі почалася.'::text),
(382146,42461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer su compañero de piso ... la pasta antes de que empezara la partida.'::text,'había cocinado'::text,'ha cocinado'::text,'cocina'::text,'Vale, pues al parecer su compañero de piso había cocinado la pasta antes de que empezara la partida.'::text),
(382145,42461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment son coloc ... les pâtes avant même que la partie commence.'::text,'avait cuisiné'::text,'a cuisiné'::text,'cuisine'::text,'Bon, apparemment son coloc avait cuisiné les pâtes avant même que la partie commence.'::text),
(382148,42461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, güya ev arkadaşı oyun başlamadan önce makarnayı ...'::text,'pişirmişti'::text,'pişirdi'::text,'pişiriyor'::text,'Neyse, güya ev arkadaşı oyun başlamadan önce makarnayı pişirmişti.'::text),
(382149,42461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag a lakótársa ... a tésztát, még mielőtt a játék elkezdődött volna.'::text,'megfőzte'::text,'megfőzte'::text,'főzi'::text,'Szóval, állítólag a lakótársa megfőzte a tésztát, még mielőtt a játék elkezdődött volna.'::text),
(382152,42462,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat gesagt, ich soll nicht um Mitternacht anrufen, weil er und sein Mitbewohner dann ...'::text,'gerade zocken werden'::text,'zocken werden'::text,'zocken'::text,'Hör zu, er hat gesagt, ich soll nicht um Mitternacht anrufen, weil er und sein Mitbewohner dann gerade zocken werden.'::text),
(382156,42462,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав не дзвонити опівночі, бо він і його сусід ... в ігри.'::text,'гратимуть'::text,'пограють'::text,'грають'::text,'Слухай, він сказав не дзвонити опівночі, бо він і його сусід гратимуть в ігри.'::text),
(382155,42462,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que no llamara a medianoche, porque él y su compañero de piso ... a videojuegos.'::text,'estarán jugando'::text,'jugarán'::text,'juegan'::text,'Escucha, me dijo que no llamara a medianoche, porque él y su compañero de piso estarán jugando a videojuegos.'::text),
(382154,42462,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit de ne pas appeler à minuit, parce que lui et son coloc ... aux jeux vidéo.'::text,'seront en train de jouer'::text,'joueront'::text,'jouent'::text,'Écoute, il m''a dit de ne pas appeler à minuit, parce que lui et son coloc seront en train de jouer aux jeux vidéo.'::text),
(382157,42462,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, gece yarısı aramamamı söyledi, çünkü o ve ev arkadaşı oyun ...'::text,'oynuyor olacaklar'::text,'oynayacaklar'::text,'oynarlar'::text,'Dinle, gece yarısı aramamamı söyledi, çünkü o ve ev arkadaşı oyun oynuyor olacaklar.'::text),
(382158,42462,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, ne hívjam éjfélkor, mert ő és a lakótársa ...'::text,'épp játszani fognak'::text,'játszani fognak'::text,'játszanak'::text,'Figyelj, azt mondta, ne hívjam éjfélkor, mert ő és a lakótársa épp játszani fognak.'::text),
(382161,42463,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich verspreche, ich ... nächstes Mal den Müll raus, Mitbewohner; deine Pasta ist ehrlich die beste.'::text,'bringe'::text,'werde gerade bringen'::text,'bringe gerade'::text,'Ich verspreche, ich bringe nächstes Mal den Müll raus, Mitbewohner; deine Pasta ist ehrlich die beste.'::text),
(382165,42463,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обіцяю, наступного разу я ... сміття, сусіде; твоя паста чесно найкраща.'::text,'винесу'::text,'виноситиму'::text,'виношу'::text,'Обіцяю, наступного разу я винесу сміття, сусіде; твоя паста чесно найкраща.'::text),
(382164,42463,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te prometo que la próxima vez ... yo la basura, compi; tu pasta es la mejor, de verdad.'::text,'sacaré'::text,'estaré sacando'::text,'saco'::text,'Te prometo que la próxima vez sacaré yo la basura, compi; tu pasta es la mejor, de verdad.'::text),
(382163,42463,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je te promets que la prochaine fois, je ... les poubelles, coloc ; tes pâtes sont franchement les meilleures.'::text,'sortirai'::text,'serai en train de sortir'::text,'sors'::text,'Je te promets que la prochaine fois, je sortirai les poubelles, coloc ; tes pâtes sont franchement les meilleures.'::text),
(382166,42463,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söz, bir dahaki sefere çöpü ben ..., ev arkadaşım; senin makarnan cidden en iyisi.'::text,'çıkaracağım'::text,'çıkarıyor olacağım'::text,'çıkarıyorum'::text,'Söz, bir dahaki sefere çöpü ben çıkaracağım, ev arkadaşım; senin makarnan cidden en iyisi.'::text),
(382167,42463,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ígérem, legközelebb én ... le a szemetet, lakótárs; a tésztád őszintén a legjobb.'::text,'viszem'::text,'fogom vinni'::text,'viszem épp'::text,'Ígérem, legközelebb én viszem le a szemetet, lakótárs; a tésztád őszintén a legjobb.'::text),
(382170,42464,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Mitbewohner bei Schere, Stein, Papier ..., bringt er den Müll raus.'::text,'verliert'::text,'verlor'::text,'verlieren wird'::text,'Wenn ein Mitbewohner bei Schere, Stein, Papier verliert, bringt er den Müll raus.'::text),
(382174,42464,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо сусід ... в «камінь-ножиці-папір», він виносить сміття.'::text,'програє'::text,'програв'::text,'програватиме'::text,'Якщо сусід програє в «камінь-ножиці-папір», він виносить сміття.'::text),
(382173,42464,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un compañero de piso ... a piedra, papel o tijera, saca la basura.'::text,'pierde'::text,'perdió'::text,'perderá'::text,'Si un compañero de piso pierde a piedra, papel o tijera, saca la basura.'::text),
(382172,42464,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un coloc ... à pierre-feuille-ciseaux, il sort la poubelle.'::text,'perd'::text,'a perdu'::text,'perdra'::text,'Si un coloc perd à pierre-feuille-ciseaux, il sort la poubelle.'::text),
(382175,42464,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev arkadaşı taş-kâğıt-makasta ..., çöpü o çıkarır.'::text,'kaybederse'::text,'kaybettiyse'::text,'kaybedecekse'::text,'Ev arkadaşı taş-kâğıt-makasta kaybederse, çöpü o çıkarır.'::text),
(382176,42464,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy lakótárs ... kő-papír-ollóban, ő viszi le a szemetet.'::text,'veszít'::text,'veszített'::text,'veszíteni fog'::text,'Ha egy lakótárs veszít kő-papír-ollóban, ő viszi le a szemetet.'::text),
(382179,42465,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sein Mitbewohner die nächste Runde verliert, ... er den Müllsack raus.'::text,'bringt'::text,'brächte'::text,'brachte'::text,'Wenn sein Mitbewohner die nächste Runde verliert, bringt er den Müllsack raus.'::text),
(382183,42465,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо його сусід програє наступний раунд, він ... мішок зі сміттям.'::text,'винесе'::text,'виніс би'::text,'виніс'::text,'Якщо його сусід програє наступний раунд, він винесе мішок зі сміттям.'::text),
(382182,42465,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su compañero de piso pierde la próxima ronda, ... la bolsa de basura.'::text,'sacará'::text,'sacaría'::text,'sacó'::text,'Si su compañero de piso pierde la próxima ronda, sacará la bolsa de basura.'::text),
(382181,42465,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si son coloc perd la prochaine manche, il ... le sac poubelle.'::text,'sortira'::text,'sortirait'::text,'a sorti'::text,'Si son coloc perd la prochaine manche, il sortira le sac poubelle.'::text),
(382184,42465,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev arkadaşı bir sonraki turu kaybederse, çöp torbasını ...'::text,'çıkaracak'::text,'çıkarırdı'::text,'çıkardı'::text,'Ev arkadaşı bir sonraki turu kaybederse, çöp torbasını çıkaracak.'::text),
(382185,42465,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a lakótársa elveszíti a következő kört, ő ... le a szemeteszsákot.'::text,'viszi'::text,'vinné'::text,'vitte'::text,'Ha a lakótársa elveszíti a következő kört, ő viszi le a szemeteszsákot.'::text),
(382188,42466,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sein Mitbewohner jeden Abend kochen würde, ... die Wohnung wie ein Restaurant.'::text,'röche'::text,'wird riechen'::text,'riecht'::text,'Wenn sein Mitbewohner jeden Abend kochen würde, röche die Wohnung wie ein Restaurant.'::text),
(382192,42466,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби його сусід готував щовечора, квартира ... як ресторан.'::text,'пахла б'::text,'пахнутиме'::text,'пахне'::text,'Якби його сусід готував щовечора, квартира пахла б як ресторан.'::text),
(382191,42466,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su compañero de piso cocinara todas las noches, el piso ... a restaurante.'::text,'olería'::text,'olerá'::text,'huele'::text,'Si su compañero de piso cocinara todas las noches, el piso olería a restaurante.'::text),
(382190,42466,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si son coloc cuisinait tous les soirs, l''appart ... comme un restaurant.'::text,'sentirait'::text,'sentira'::text,'sent'::text,'Si son coloc cuisinait tous les soirs, l''appart sentirait comme un restaurant.'::text),
(382193,42466,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev arkadaşı her akşam yemek yapsaydı, ev restoran gibi ...'::text,'kokardı'::text,'kokacak'::text,'kokuyor'::text,'Ev arkadaşı her akşam yemek yapsaydı, ev restoran gibi kokardı.'::text),
(382194,42466,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a lakótársa minden este főzne, a lakásnak olyan illata ..., mint egy étteremnek.'::text,'lenne'::text,'lesz'::text,'van'::text,'Ha a lakótársa minden este főzne, a lakásnak olyan illata lenne, mint egy étteremnek.'::text),
(382197,42467,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In dieser Wohnung ... der Müll von demjenigen Mitbewohner rausgebracht, der das Spiel verliert, wie hier beobachtet.'::text,'wird'::text,'bringt'::text,'brachte'::text,'In dieser Wohnung wird der Müll von demjenigen Mitbewohner rausgebracht, der das Spiel verliert, wie hier beobachtet.'::text),
(382201,42467,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У цій квартирі сміття ... тим сусідом, який програє гру, як тут спостерігається.'::text,'виноситься'::text,'виносить'::text,'виносив'::text,'У цій квартирі сміття виноситься тим сусідом, який програє гру, як тут спостерігається.'::text),
(382200,42467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este piso, la basura ... por el compañero que pierde la partida, como se observa aquí.'::text,'es sacada'::text,'saca'::text,'estaba sacando'::text,'En este piso, la basura es sacada por el compañero que pierde la partida, como se observa aquí.'::text),
(382199,42467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans cet appart, la poubelle ... par le coloc qui perd la partie, comme on l''observe ici.'::text,'est sortie'::text,'sort'::text,'sortait'::text,'Dans cet appart, la poubelle est sortie par le coloc qui perd la partie, comme on l''observe ici.'::text),
(382202,42467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu evde, burada gözlemlendiği gibi, çöp oyunu kaybeden ev arkadaşı tarafından ...'::text,'çıkarılır'::text,'çıkarır'::text,'çıkarıyordu'::text,'Bu evde, burada gözlemlendiği gibi, çöp oyunu kaybeden ev arkadaşı tarafından çıkarılır.'::text),
(382203,42467,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a lakásban a szemetet az a lakótárs ..., aki elveszíti a játékot, ahogy itt megfigyelhető.'::text,'viszi le'::text,'viszi le'::text,'vitte le'::text,'Ebben a lakásban a szemetet az a lakótárs viszi le, aki elveszíti a játékot, ahogy itt megfigyelhető.'::text),
(382206,42468,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Müllsack ... endlich von meinem Mitbewohner rausgebracht, der Albtraum ist vorbei!'::text,'wurde'::text,'brachte'::text,'bringend'::text,'Der Müllsack wurde endlich von meinem Mitbewohner rausgebracht, der Albtraum ist vorbei!'::text),
(382210,42468,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мішок зі сміттям нарешті ... моїм сусідом, кошмар скінчився!'::text,'був винесений'::text,'виніс'::text,'виносячи'::text,'Мішок зі сміттям нарешті був винесений моїм сусідом, кошмар скінчився!'::text),
(382209,42468,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La bolsa de basura por fin ... por mi compañero de piso, la pesadilla ha terminado!'::text,'fue sacada'::text,'sacó'::text,'sacando'::text,'¡La bolsa de basura por fin fue sacada por mi compañero de piso, la pesadilla ha terminado!'::text),
(382208,42468,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sac poubelle ... enfin par mon coloc, le cauchemar est terminé !'::text,'a été sorti'::text,'a sorti'::text,'sortant'::text,'Le sac poubelle a été sorti enfin par mon coloc, le cauchemar est terminé !'::text),
(382211,42468,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çöp torbası sonunda ev arkadaşım tarafından ..., kâbus bitti!'::text,'çıkarıldı'::text,'çıkardı'::text,'çıkararak'::text,'Çöp torbası sonunda ev arkadaşım tarafından çıkarıldı, kâbus bitti!'::text),
(382212,42468,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szemeteszsákot végre ... a lakótársam, vége a rémálomnak!'::text,'levitte'::text,'levitte'::text,'levive'::text,'A szemeteszsákot végre levitte a lakótársam, vége a rémálomnak!'::text),
(392052,43562,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ist schon oben, also ... sie die Treppe hochgerannt sein! Absolut unglaublich!'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Sie ist schon oben, also muss sie die Treppe hochgerannt sein! Absolut unglaublich!'::text),
(392056,43562,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона вже нагорі, тож вона ... цими сходами! Абсолютно неймовірно!'::text,'напевно, збігла'::text,'могла збігти'::text,'не могла збігти'::text,'Вона вже нагорі, тож вона напевно, збігла цими сходами! Абсолютно неймовірно!'::text),
(392055,43562,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ya está arriba, así que ... haber subido corriendo esos escalones! ¡Absolutamente increíble!'::text,'debe de'::text,'podría'::text,'no puede'::text,'¡Ya está arriba, así que debe de haber subido corriendo esos escalones! ¡Absolutamente increíble!'::text),
(392054,43562,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est déjà en haut, donc elle ... monter ces marches en courant ! Absolument incroyable !'::text,'a dû'::text,'a pu'::text,'n''a pas pu'::text,'Elle est déjà en haut, donc elle a dû monter ces marches en courant ! Absolument incroyable !'::text),
(392057,43562,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zaten tepede, demek ki o basamakları koşarak ...! İnanılmaz!'::text,'çıkmış olmalı'::text,'çıkmış olabilir'::text,'çıkmış olamaz'::text,'Zaten tepede, demek ki o basamakları koşarak çıkmış olmalı! İnanılmaz!'::text),
(392058,43562,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már fent van, szóval ... felrohant azokon a lépcsőkön! Abszolút hihetetlen!'::text,'biztos'::text,'talán'::text,'nem lehet, hogy'::text,'Már fent van, szóval biztos felrohant azokon a lépcsőkön! Abszolút hihetetlen!'::text),
(392061,43563,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, die Stufen, ... sie hochgestiegen ist, führen angeblich bis ganz zum Gipfel.'::text,'die'::text,'wer'::text,'deren'::text,'Bestie, die Stufen, die sie hochgestiegen ist, führen angeblich bis ganz zum Gipfel.'::text),
(392065,43563,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, сходи, ... вона піднялася, ведуть аж на вершину, кажуть.'::text,'якими'::text,'хто'::text,'чиї'::text,'Подруго, сходи, якими вона піднялася, ведуть аж на вершину, кажуть.'::text),
(392064,43563,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, los escalones ... subió llegan hasta la cima, al parecer.'::text,'que'::text,'quien'::text,'cuyos'::text,'Amiga, los escalones que subió llegan hasta la cima, al parecer.'::text),
(392063,43563,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, les marches ... elle est montée vont jusqu''au sommet, apparemment.'::text,'par lesquelles'::text,'qui'::text,'dont'::text,'Ma belle, les marches par lesquelles elle est montée vont jusqu''au sommet, apparemment.'::text),
(392066,43563,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... tırmandığı basamaklar güya ta zirveye kadar gidiyormuş.'::text,''::text,NULL::text,NULL::text,'Kanka, tırmandığı basamaklar güya ta zirveye kadar gidiyormuş.'::text),
(392067,43563,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a lépcső, ... felment, állítólag egészen a csúcsig vezet.'::text,'amelyen'::text,'aki'::text,'amelynek'::text,'Csajszi, a lépcső, amelyen felment, állítólag egészen a csúcsig vezet.'::text),
(392070,43564,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt, dass sie jede einzelne Stufe ohne Pause ...'::text,'genommen hatte'::text,'genommen hat'::text,'nimmt'::text,'Hör zu, sie hat gesagt, dass sie jede einzelne Stufe ohne Pause genommen hatte.'::text),
(392074,43564,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що ... кожну сходинку без перерви.'::text,'пройшла'::text,'пройшла'::text,'проходить'::text,'Слухай, вона сказала, що пройшла кожну сходинку без перерви.'::text),
(392073,43564,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, dijo que ... cada escalón sin descanso.'::text,'había subido'::text,'ha subido'::text,'sube'::text,'Escucha, dijo que había subido cada escalón sin descanso.'::text),
(392072,43564,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit qu''elle ... chaque marche sans pause.'::text,'avait gravi'::text,'a gravi'::text,'gravit'::text,'Écoute, elle a dit qu''elle avait gravi chaque marche sans pause.'::text),
(392075,43564,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, her bir basamağı mola vermeden ... söyledi.'::text,'çıkmış olduğunu'::text,'çıktığını'::text,'çıkıyor olduğunu'::text,'Dinle, her bir basamağı mola vermeden çıkmış olduğunu söyledi.'::text),
(392076,43564,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy minden egyes lépcsőfokot szünet nélkül ...'::text,'megmászott'::text,'megmászott'::text,'megmászik'::text,'Figyelj, azt mondta, hogy minden egyes lépcsőfokot szünet nélkül megmászott.'::text),
(392079,43565,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor Jahren ... es hier keine Stufen, nur einen staubigen Pfad.'::text,'gab'::text,'gab früher'::text,'war gewohnt'::text,'Vor Jahren gab es hier keine Stufen, nur einen staubigen Pfad.'::text),
(392083,43565,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кілька років тому тут ... сходів, лише пильна стежка.'::text,'не було'::text,'не бувало'::text,'не звикло бути'::text,'Кілька років тому тут не було сходів, лише пильна стежка.'::text),
(392082,43565,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace años, aquí no ... escalones, solo un sendero polvoriento.'::text,'solía haber'::text,'habría'::text,'estaba acostumbrado a haber'::text,'Hace años, aquí no solía haber escalones, solo un sendero polvoriento.'::text),
(392081,43565,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a des années, il n''y ... pas de marches ici, seulement un chemin poussiéreux.'::text,'avait'::text,'aurait'::text,'avait l''habitude d''avoir'::text,'Il y a des années, il n''y avait pas de marches ici, seulement un chemin poussiéreux.'::text),
(392084,43565,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıllar önce burada basamak ..., sadece tozlu bir patika vardı.'::text,'yoktu'::text,'olmazdı'::text,'olmamaya alışkındı'::text,'Yıllar önce burada basamak yoktu, sadece tozlu bir patika vardı.'::text),
(392085,43565,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évekkel ezelőtt itt ... lépcső, csak egy poros ösvény.'::text,'régen nem volt'::text,'nem szokott lenni'::text,'hozzá volt szokva, hogy ne legyen'::text,'Évekkel ezelőtt itt régen nem volt lépcső, csak egy poros ösvény.'::text),
(392088,43566,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Stufen weiter hoch, ohne sich umzudrehen.'::text,'stieg'::text,'zu steigen'::text,'steig'::text,'Sie stieg die Stufen weiter hoch, ohne sich umzudrehen.'::text),
(392092,43566,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона продовжувала ... сходами, не озираючись.'::text,'підніматися'::text,'піднятися'::text,'піднімайся'::text,'Вона продовжувала підніматися сходами, не озираючись.'::text),
(392091,43566,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siguió ... los escalones sin mirar atrás.'::text,'subiendo'::text,'subir'::text,'sube'::text,'Siguió subiendo los escalones sin mirar atrás.'::text),
(392090,43566,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a continué ... les marches sans se retourner.'::text,'à monter'::text,'de monter'::text,'monte'::text,'Elle a continué à monter les marches sans se retourner.'::text),
(392093,43566,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkasına bakmadan basamakları ... devam etti.'::text,'çıkmaya'::text,'çıkmak'::text,'çık'::text,'Arkasına bakmadan basamakları çıkmaya devam etti.'::text),
(392094,43566,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tovább ... a lépcsőn, hátra sem nézve.'::text,'mászott'::text,'mászni'::text,'mássz'::text,'Tovább mászott a lépcsőn, hátra sem nézve.'::text),
(392097,43567,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Steinstufen waren steil, ...?'::text,'oder?'::text,'nicht?'::text,'stimmt''s?'::text,'Die Steinstufen waren steil, oder?'::text),
(392101,43567,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ті кам''яні сходи були круті, ...?'::text,'правда?'::text,'хіба ні?'::text,'так?'::text,'Ті кам''яні сходи були круті, правда?'::text),
(392100,43567,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esos escalones de piedra eran empinados, ¿...?'::text,'verdad?'::text,'no?'::text,'verdad?'::text,'Esos escalones de piedra eran empinados, ¿verdad?'::text),
(392099,43567,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces marches en pierre étaient raides, ... ?'::text,'non ?'::text,'pas vrai ?'::text,'n''est-ce pas ?'::text,'Ces marches en pierre étaient raides, non ?'::text),
(392102,43567,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O taş basamaklar dikti, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'O taş basamaklar dikti, değil mi?'::text),
(392103,43567,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azok a kőlépcsők meredekek voltak, ...?'::text,'ugye?'::text,'nem?'::text,'igaz?'::text,'Azok a kőlépcsők meredekek voltak, ugye?'::text),
(392115,43569,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... eine Stunde lang die Stufen hochgestiegen, bevor sie oben ankam, ganz klar ein gemütlicher Spaziergang.'::text,'war'::text,'ist'::text,'stieg'::text,'Sie war eine Stunde lang die Stufen hochgestiegen, bevor sie oben ankam, ganz klar ein gemütlicher Spaziergang.'::text),
(392119,43569,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... сходами годину, перш ніж дісталася вершини, явно легка прогулянка.'::text,'піднімалася'::text,'піднімається'::text,'піднімалася'::text,'Вона піднімалася сходами годину, перш ніж дісталася вершини, явно легка прогулянка.'::text),
(392118,43569,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una hora subiendo los escalones antes de llegar arriba, claramente un paseo tranquilo.'::text,'Llevaba'::text,'Lleva'::text,'Estaba'::text,'Llevaba una hora subiendo los escalones antes de llegar arriba, claramente un paseo tranquilo.'::text),
(392117,43569,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les marches pendant une heure avant d''arriver en haut, clairement une petite balade tranquille.'::text,'avait gravi'::text,'a gravi'::text,'gravissait'::text,'Elle avait gravi les marches pendant une heure avant d''arriver en haut, clairement une petite balade tranquille.'::text),
(392120,43569,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tepeye varmadan önce bir saat boyunca basamakları ..., belli ki hafif bir yürüyüş.'::text,'tırmanmıştı'::text,'tırmanıyor'::text,'tırmanıyordu'::text,'Tepeye varmadan önce bir saat boyunca basamakları tırmanmıştı, belli ki hafif bir yürüyüş.'::text),
(392121,43569,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órán át ... a lépcsőn, mire felért, nyilván egy könnyed séta.'::text,'mászott'::text,'mászik'::text,'mászott'::text,'Egy órán át mászott a lépcsőn, mire felért, nyilván egy könnyed séta.'::text),
(392133,43571,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang wird sie zehn Stunden lang diese Stufen rauf und runter ..., ganz klar ein kurzer Spaziergang.'::text,'gelaufen sein'::text,'laufen'::text,'am Laufen sein'::text,'Bis Sonnenuntergang wird sie zehn Stunden lang diese Stufen rauf und runter gelaufen sein, ganz klar ein kurzer Spaziergang.'::text),
(392137,43571,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця вона ... цими сходами вгору-вниз уже десять годин, явно коротка прогулянка.'::text,'ходитиме'::text,'пройде'::text,'ходитиме'::text,'До заходу сонця вона ходитиме цими сходами вгору-вниз уже десять годин, явно коротка прогулянка.'::text),
(392136,43571,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, ... diez horas subiendo y bajando estos escalones, claramente un paseíto.'::text,'llevará'::text,'caminará'::text,'estará'::text,'Para el atardecer, llevará diez horas subiendo y bajando estos escalones, claramente un paseíto.'::text),
(392135,43571,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, elle ... ces marches pendant dix heures, clairement une petite promenade.'::text,'aura monté et descendu'::text,'montera et descendra'::text,'sera en train de monter et descendre'::text,'D''ici le coucher du soleil, elle aura monté et descendu ces marches pendant dix heures, clairement une petite promenade.'::text),
(392138,43571,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar on saattir bu basamaklarda aşağı yukarı ..., belli ki kısa bir yürüyüş.'::text,'yürüyor olacak'::text,'yürüyecek'::text,'yürüyor olacak'::text,'Gün batımına kadar on saattir bu basamaklarda aşağı yukarı yürüyor olacak, belli ki kısa bir yürüyüş.'::text),
(392139,43571,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementére már tíz órája ... fel-le ezen a lépcsőn, nyilván egy rövid séta.'::text,'járkál'::text,'fog járkálni'::text,'járkálni fog'::text,'Naplementére már tíz órája járkál fel-le ezen a lépcsőn, nyilván egy rövid séta.'::text),
(392142,43572,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Stufen nicht gefunden hätte, ... sie für immer auf diesem Berg verloren gewesen!'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn sie die Stufen nicht gefunden hätte, wäre sie für immer auf diesem Berg verloren gewesen!'::text),
(392146,43572,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не знайшла сходи, вона ... загублена на цій горі назавжди!'::text,'була б'::text,'буде'::text,'була'::text,'Якби вона не знайшла сходи, вона була б загублена на цій горі назавжди!'::text),
(392145,43572,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no hubiera encontrado los escalones, ... perdida en esta montaña para siempre!'::text,'habría estado'::text,'estará'::text,'estaba'::text,'¡Si no hubiera encontrado los escalones, habría estado perdida en esta montaña para siempre!'::text),
(392144,43572,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas trouvé les marches, elle ... perdue sur cette montagne pour toujours !'::text,'aurait été'::text,'sera'::text,'était'::text,'Si elle n''avait pas trouvé les marches, elle aurait été perdue sur cette montagne pour toujours !'::text),
(392147,43572,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Basamakları bulmasaydı, bu dağda sonsuza kadar kaybolmuş ...!'::text,'olurdu'::text,'olacak'::text,'idi'::text,'Basamakları bulmasaydı, bu dağda sonsuza kadar kaybolmuş olurdu!'::text),
(392148,43572,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem találta volna meg a lépcsőt, örökre ... ezen a hegyen!'::text,'eltévedt volna'::text,'el fog tévedni'::text,'eltévedt'::text,'Ha nem találta volna meg a lépcsőt, örökre eltévedt volna ezen a hegyen!'::text),
(382377,42487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Route nicht an der Tafel studiert hätte, ... sie jetzt im Wald verloren.'::text,'wäre'::text,'wäre gewesen'::text,'wird sein'::text,'Wenn sie die Route nicht an der Tafel studiert hätte, wäre sie jetzt im Wald verloren.'::text),
(382381,42487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не вивчила маршрут біля дошки, вона ... зараз загублена в лісі.'::text,'була б'::text,'була б'::text,'буде'::text,'Якби вона не вивчила маршрут біля дошки, вона була б зараз загублена в лісі.'::text),
(382380,42487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera estudiado la ruta en el panel, ahora ... perdida en el bosque.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si no hubiera estudiado la ruta en el panel, ahora estaría perdida en el bosque.'::text),
(382379,42487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas étudié l''itinéraire au panneau, elle ... perdue dans la forêt maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si elle n''avait pas étudié l''itinéraire au panneau, elle serait perdue dans la forêt maintenant.'::text),
(382382,42487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabeladaki rotayı incelemeseydi, şimdi ormanda kaybolmuş ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Tabeladaki rotayı incelemeseydi, şimdi ormanda kaybolmuş olurdu.'::text),
(382383,42487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem tanulmányozta volna az útvonalat a táblánál, most ... az erdőben.'::text,'bolyongana'::text,'bolyongott volna'::text,'bolyongani fog'::text,'Ha nem tanulmányozta volna az útvonalat a táblánál, most bolyongana az erdőben.'::text),
(382386,42488,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Route soll seit Hunderten von Jahren von Wanderern ...'::text,'genutzt worden sein'::text,'nutzen'::text,'nutzend'::text,'Diese Route soll seit Hunderten von Jahren von Wanderern genutzt worden sein.'::text),
(382390,42488,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що цим маршрутом туристи ... сотні років.'::text,'користувалися'::text,'користуватися'::text,'користування'::text,'Кажуть, що цим маршрутом туристи користувалися сотні років.'::text),
(382389,42488,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que esta ruta ... por excursionistas durante cientos de años.'::text,'ha sido usada'::text,'usar'::text,'usando'::text,'Se dice que esta ruta ha sido usada por excursionistas durante cientos de años.'::text),
(382388,42488,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que cet itinéraire ... par des randonneurs depuis des centaines d''années.'::text,'a été utilisé'::text,'utiliser'::text,'utilisant'::text,'On dit que cet itinéraire a été utilisé par des randonneurs depuis des centaines d''années.'::text),
(382391,42488,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu rotanın yüzlerce yıldır yürüyüşçüler tarafından ... söyleniyor.'::text,'kullanıldığı'::text,'kullanmak'::text,'kullanarak'::text,'Bu rotanın yüzlerce yıldır yürüyüşçüler tarafından kullanıldığı söyleniyor.'::text),
(382392,42488,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, ezt az útvonalat évszázadok óta ... a túrázók.'::text,'használják'::text,'használni'::text,'használva'::text,'Azt mondják, ezt az útvonalat évszázadok óta használják a túrázók.'::text),
(382395,42489,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schlug vor, die längere Route am Felsbrocken vorbei ...'::text,'zu nehmen'::text,'nehmen'::text,'nahm'::text,'Sie schlug vor, die längere Route am Felsbrocken vorbei zu nehmen.'::text),
(382399,42489,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона запропонувала ... довший маршрут повз валун.'::text,'обрати'::text,'обрати'::text,'обрала'::text,'Вона запропонувала обрати довший маршрут повз валун.'::text),
(382398,42489,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Propuso ... la ruta más larga pasando por la roca.'::text,'tomar'::text,'tomar'::text,'tomó'::text,'Propuso tomar la ruta más larga pasando por la roca.'::text),
(382397,42489,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a proposé de ... l''itinéraire plus long en passant par le rocher.'::text,'prendre'::text,'prendre'::text,'a pris'::text,'Elle a proposé de prendre l''itinéraire plus long en passant par le rocher.'::text),
(382400,42489,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayanın yanından geçen daha uzun rotayı ... önerdi.'::text,'seçmeyi'::text,'seçmek'::text,'seçti'::text,'Kayanın yanından geçen daha uzun rotayı seçmeyi önerdi.'::text),
(382401,42489,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt javasolta, hogy ... a hosszabb útvonalat a szikla mellett.'::text,'válasszák'::text,'választani'::text,'választotta'::text,'Azt javasolta, hogy válasszák a hosszabb útvonalat a szikla mellett.'::text),
(382404,42490,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich die Route gut gemerkt haben, denn sie hat nie wieder auf die Karte geschaut.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Sie muss sich die Route gut gemerkt haben, denn sie hat nie wieder auf die Karte geschaut.'::text),
(382408,42490,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... маршрут добре, бо більше жодного разу не глянула на мапу.'::text,'напевно, запам''ятала'::text,'мала запам''ятати'::text,'не могла запам''ятати'::text,'Вона напевно, запам''ятала маршрут добре, бо більше жодного разу не глянула на мапу.'::text),
(382407,42490,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... memorizado bien la ruta, porque no volvió a mirar el mapa.'::text,'Debe de haber'::text,'Debería haber'::text,'No puede haber'::text,'Debe de haber memorizado bien la ruta, porque no volvió a mirar el mapa.'::text),
(382406,42490,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... bien mémoriser l''itinéraire, parce qu''elle n''a plus jamais regardé la carte.'::text,'a dû'::text,'aurait dû'::text,'n''a pas pu'::text,'Elle a dû bien mémoriser l''itinéraire, parce qu''elle n''a plus jamais regardé la carte.'::text),
(382409,42490,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rotayı iyi ezberlemiş ..., çünkü haritaya bir daha hiç bakmadı.'::text,'olmalı'::text,'olmalıydı'::text,'olamaz'::text,'Rotayı iyi ezberlemiş olmalı, çünkü haritaya bir daha hiç bakmadı.'::text),
(382410,42490,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... jól megjegyezte az útvonalat, mert többé rá sem nézett a térképre.'::text,'Biztosan'::text,'Kellett volna'::text,'Nem lehet, hogy'::text,'Biztosan jól megjegyezte az útvonalat, mert többé rá sem nézett a térképre.'::text),
(382413,42491,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nicht nur ... hat sie die Route gelernt, sie ist sie auch in Rekordzeit gelaufen.'::text,''::text,NULL::text,NULL::text,'Nicht nur hat sie die Route gelernt, sie ist sie auch in Rekordzeit gelaufen.'::text),
(382417,42491,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона не тільки ... вивчила маршрут, а й пробігла його за рекордний час.'::text,''::text,NULL::text,NULL::text,'Вона не тільки вивчила маршрут, а й пробігла його за рекордний час.'::text),
(382416,42491,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No solo ... se aprendió la ruta, sino que también la corrió en tiempo récord.'::text,''::text,NULL::text,NULL::text,'No solo se aprendió la ruta, sino que también la corrió en tiempo récord.'::text),
(382415,42491,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non seulement ... elle a appris l''itinéraire, mais elle l''a aussi couru en un temps record.'::text,''::text,NULL::text,NULL::text,'Non seulement elle a appris l''itinéraire, mais elle l''a aussi couru en un temps record.'::text),
(382418,42491,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rotayı ... öğrenmekle kalmadı, bir de rekor sürede koştu.'::text,''::text,NULL::text,NULL::text,'Rotayı öğrenmekle kalmadı, bir de rekor sürede koştu.'::text),
(382419,42491,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nemcsak ... megtanulta az útvonalat, de rekordidő alatt le is futotta.'::text,''::text,NULL::text,NULL::text,'Nemcsak megtanulta az útvonalat, de rekordidő alatt le is futotta.'::text),
(382431,42493,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, ich ... die Route so gut; mein Orientierungssinn ist natürlich makellos.'::text,'kennte'::text,'kenne'::text,'würde kennen'::text,'Ich wünschte, ich kennte die Route so gut; mein Orientierungssinn ist natürlich makellos.'::text),
(382435,42493,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хотіла б я ... маршрут так добре; моє чуття напрямку, звісно, бездоганне.'::text,'знати'::text,'знаю'::text,'знала б'::text,'Хотіла б я знати маршрут так добре; моє чуття напрямку, звісно, бездоганне.'::text),
(382434,42493,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ojalá ... la ruta así de bien; mi sentido de la orientación es impecable, obviamente.'::text,'me supiera'::text,'me sé'::text,'me sabría'::text,'Ojalá me supiera la ruta así de bien; mi sentido de la orientación es impecable, obviamente.'::text),
(382433,42493,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si seulement je ... l''itinéraire aussi bien ; mon sens de l''orientation est impeccable, évidemment.'::text,'connaissais'::text,'connais'::text,'connaîtrais'::text,'Si seulement je connaissais l''itinéraire aussi bien ; mon sens de l''orientation est impeccable, évidemment.'::text),
(382436,42493,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke rotayı bu kadar iyi ...; yön duygum kusursuz, tabii ki.'::text,'bilsem'::text,'biliyorum'::text,'bilecek olsam'::text,'Keşke rotayı bu kadar iyi bilsem; yön duygum kusursuz, tabii ki.'::text),
(382437,42493,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak ilyen jól ... az útvonalat; a tájékozódási képességem hibátlan, nyilván.'::text,'ismerném'::text,'ismerem'::text,'ismerni fogom'::text,'Bárcsak ilyen jól ismerném az útvonalat; a tájékozódási képességem hibátlan, nyilván.'::text),
(382440,42494,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Route, ... rote Linie die halbe Karte füllt, ist natürlich ein kurzer kleiner Lauf.'::text,'deren'::text,'die'::text,'welche'::text,'Die Route, deren rote Linie die halbe Karte füllt, ist natürlich ein kurzer kleiner Lauf.'::text),
(382444,42494,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маршрут, ... червона лінія займає пів мапи, — явно коротенька пробіжка.'::text,'чия'::text,'який'::text,'що'::text,'Маршрут, чия червона лінія займає пів мапи, — явно коротенька пробіжка.'::text),
(382443,42494,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La ruta, ... línea roja ocupa medio mapa, es claramente un trotecito corto.'::text,'cuya'::text,'la cual'::text,'que'::text,'La ruta, cuya línea roja ocupa medio mapa, es claramente un trotecito corto.'::text),
(382442,42494,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''itinéraire, ... la ligne rouge occupe la moitié de la carte, est clairement un petit footing.'::text,'dont'::text,'qui'::text,'que'::text,'L''itinéraire, dont la ligne rouge occupe la moitié de la carte, est clairement un petit footing.'::text),
(382445,42494,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kırmızı çizgisi haritanın yarısını kaplayan rota belli ki kısa bir koşu.'::text,''::text,NULL::text,NULL::text,'Kırmızı çizgisi haritanın yarısını kaplayan rota belli ki kısa bir koşu.'::text),
(382446,42494,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az útvonal, ... piros vonala a térkép felét kitölti, nyilván egy rövid kis kocogás.'::text,'amelynek'::text,'amely'::text,'ami'::text,'Az útvonal, amelynek piros vonala a térkép felét kitölti, nyilván egy rövid kis kocogás.'::text),
(382449,42495,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat die ganze Route ... geschafft, ganz allein!'::text,'zu Fuß'::text,'zu dem Fuß'::text,'zu einem Fuß'::text,'Sie hat die ganze Route zu Fuß geschafft, ganz allein!'::text),
(382453,42495,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона пройшла весь маршрут ..., зовсім сама!'::text,'пішки'::text,'пішки'::text,'пішки'::text,'Вона пройшла весь маршрут пішки, зовсім сама!'::text),
(382452,42495,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Recorrió toda la ruta ..., completamente sola!'::text,'a pie'::text,'al pie'::text,'a un pie'::text,'¡Recorrió toda la ruta a pie, completamente sola!'::text),
(382451,42495,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a parcouru tout l''itinéraire ..., complètement seule !'::text,'à pied'::text,'au pied'::text,'à un pied'::text,'Elle a parcouru tout l''itinéraire à pied, complètement seule !'::text),
(382454,42495,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün rotayı ... tamamladı, tamamen yalnız!'::text,'yürüyerek'::text,'yürüyerek'::text,'yürüyerek'::text,'Bütün rotayı yürüyerek tamamladı, tamamen yalnız!'::text),
(382455,42495,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész útvonalat ... tette meg, teljesen egyedül!'::text,'gyalog'::text,'gyalog'::text,'gyalog'::text,'Az egész útvonalat gyalog tette meg, teljesen egyedül!'::text),
(382458,42496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der schrecklichen Hitze schaffte sie die ganze Route ohne Pause!'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz der schrecklichen Hitze schaffte sie die ganze Route ohne Pause!'::text),
(382462,42496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... жахливу спеку, вона пройшла весь маршрут без перерви!'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри жахливу спеку, вона пройшла весь маршрут без перерви!'::text),
(382461,42496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... ese calor terrible, terminó toda la ruta sin descanso!'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'¡A pesar de ese calor terrible, terminó toda la ruta sin descanso!'::text),
(382460,42496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la chaleur terrifiante, elle a fini tout l''itinéraire sans pause !'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré la chaleur terrifiante, elle a fini tout l''itinéraire sans pause !'::text),
(382463,42496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korkunç sıcağa ..., bütün rotayı mola vermeden bitirdi!'::text,'rağmen'::text,'gerçi'::text,'yüzünden'::text,'Korkunç sıcağa rağmen, bütün rotayı mola vermeden bitirdi!'::text),
(382464,42496,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A borzasztó hőség ... az egész útvonalat szünet nélkül végigcsinálta!'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A borzasztó hőség ellenére az egész útvonalat szünet nélkül végigcsinálta!'::text),
(382467,42497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, sie hat mir gesagt, sie wusste, dass sie die Route in unter einer Stunde ...'::text,'schaffen würde'::text,'schaffen wird'::text,'gerade schafft'::text,'Girl, sie hat mir gesagt, sie wusste, dass sie die Route in unter einer Stunde schaffen würde.'::text),
(382471,42497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала, що знала, що ... маршрут менше ніж за годину.'::text,'пройде'::text,'пройде'::text,'проходить'::text,'Подруго, вона сказала, що знала, що пройде маршрут менше ніж за годину.'::text),
(382470,42497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que sabía que ... la ruta en menos de una hora.'::text,'terminaría'::text,'terminará'::text,'está terminando'::text,'Amiga, me dijo que sabía que terminaría la ruta en menos de una hora.'::text),
(382469,42497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit qu''elle savait qu''elle ... l''itinéraire en moins d''une heure.'::text,'finirait'::text,'finira'::text,'est en train de finir'::text,'Meuf, elle m''a dit qu''elle savait qu''elle finirait l''itinéraire en moins d''une heure.'::text),
(382472,42497,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana rotayı bir saatten kısa sürede ... bildiğini söyledi.'::text,'bitireceğini'::text,'bitireceğini'::text,'bitirdiğini'::text,'Kızım, bana rotayı bir saatten kısa sürede bitireceğini bildiğini söyledi.'::text),
(382473,42497,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, tudta, hogy kevesebb mint egy óra alatt ... az útvonalat.'::text,'teljesíti'::text,'teljesíteni fogja'::text,'épp teljesíti'::text,'Csajszi, azt mondta, tudta, hogy kevesebb mint egy óra alatt teljesíti az útvonalat.'::text),
(338547,37617,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zur nächsten Station wird er einen Platz im Waggon ...'::text,'gefunden haben'::text,'finden'::text,'am Suchen sein'::text,'Bis zur nächsten Station wird er einen Platz im Waggon gefunden haben.'::text),
(338551,37617,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступної станції він ... місце у вагоні.'::text,'знайде'::text,'знайде'::text,'шукатиме'::text,'До наступної станції він знайде місце у вагоні.'::text),
(338550,37617,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para la próxima estación, ... un asiento en el vagón.'::text,'habrá encontrado'::text,'encontrará'::text,'estará encontrando'::text,'Para la próxima estación, habrá encontrado un asiento en el vagón.'::text),
(338549,37617,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la prochaine gare, il ... une place dans le wagon.'::text,'aura trouvé'::text,'trouvera'::text,'sera en train de trouver'::text,'D''ici la prochaine gare, il aura trouvé une place dans le wagon.'::text),
(338552,37617,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sonraki istasyona kadar vagonda bir koltuk ...'::text,'bulmuş olacak'::text,'bulacak'::text,'buluyor olacak'::text,'Bir sonraki istasyona kadar vagonda bir koltuk bulmuş olacak.'::text),
(338553,37617,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A következő állomásig ... egy helyet a kocsiban.'::text,'talál'::text,'találni fog'::text,'keresni fog'::text,'A következő állomásig talál egy helyet a kocsiban.'::text),
(338556,37618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er diese Waggontür verpasst hätte, ... er absolut alles verloren!'::text,'hätte'::text,'würde'::text,'hat'::text,'Wenn er diese Waggontür verpasst hätte, hätte er absolut alles verloren!'::text),
(338560,37618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не встиг до тих дверей вагона, він ... абсолютно все!'::text,'втратив би'::text,'втратив би'::text,'втратив'::text,'Якби він не встиг до тих дверей вагона, він втратив би абсолютно все!'::text),
(338559,37618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no hubiera alcanzado esa puerta del vagón, ... absolutamente todo!'::text,'habría perdido'::text,'perdería'::text,'perdió'::text,'¡Si no hubiera alcanzado esa puerta del vagón, habría perdido absolutamente todo!'::text),
(338558,37618,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait raté cette porte du wagon, il ... absolument tout !'::text,'aurait perdu'::text,'perdrait'::text,'a perdu'::text,'S''il avait raté cette porte du wagon, il aurait perdu absolument tout !'::text),
(338561,37618,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O vagon kapısını kaçırsaydı, kesinlikle her şeyini ...!'::text,'kaybetmiş olurdu'::text,'kaybederdi'::text,'kaybetti'::text,'O vagon kapısını kaçırsaydı, kesinlikle her şeyini kaybetmiş olurdu!'::text),
(338562,37618,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha lekéste volna azt a kocsiajtót, abszolút mindent ...!'::text,'elveszített volna'::text,'elveszítene'::text,'elveszített'::text,'Ha lekéste volna azt a kocsiajtót, abszolút mindent elveszített volna!'::text),
(338565,37619,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er stritt ab, in letzter Sekunde in den fahrenden Waggon ..., unglaublich!'::text,'gesprungen zu sein'::text,'zu springen'::text,'sprang'::text,'Er stritt ab, in letzter Sekunde in den fahrenden Waggon gesprungen zu sein, unglaublich!'::text),
(338569,37619,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він заперечив, що ... в рухомий вагон в останню секунду. Неймовірно!'::text,'застрибнув'::text,'застрибне'::text,'застрибнув'::text,'Він заперечив, що застрибнув в рухомий вагон в останню секунду. Неймовірно!'::text),
(338568,37619,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... al vagón en marcha en el último segundo. ¡Increíble!'::text,'haber saltado'::text,'saltar'::text,'saltó'::text,'Negó haber saltado al vagón en marcha en el último segundo. ¡Increíble!'::text),
(338567,37619,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a nié ... dans le wagon en marche à la dernière seconde. Incroyable !'::text,'avoir sauté'::text,'sauter'::text,'a sauté'::text,'Il a nié avoir sauté dans le wagon en marche à la dernière seconde. Incroyable !'::text),
(338570,37619,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son saniyede hareket eden vagona ... inkâr etti. İnanılmaz!'::text,'atladığını'::text,'atlamayı'::text,'atladı'::text,'Son saniyede hareket eden vagona atladığını inkâr etti. İnanılmaz!'::text),
(338571,37619,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy az utolsó pillanatban ... a mozgó kocsiba. Hihetetlen!'::text,'beugrott'::text,'beugrani'::text,'beugrott'::text,'Tagadta, hogy az utolsó pillanatban beugrott a mozgó kocsiba. Hihetetlen!'::text),
(338574,37620,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, er hat mir gesagt, er ... früher von zu Hause losgehen sollen, statt dem Waggon hinterherzurennen.'::text,'hätte'::text,'musste'::text,'konnte nicht'::text,'Girl, er hat mir gesagt, er hätte früher von zu Hause losgehen sollen, statt dem Waggon hinterherzurennen.'::text),
(338578,37620,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ... вийти з дому раніше, а не ганятися за тим вагоном.'::text,'мав би'::text,'мусив'::text,'не міг'::text,'Подруго, він сказав мені, що мав би вийти з дому раніше, а не ганятися за тим вагоном.'::text),
(338577,37620,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ... salido de casa antes en vez de perseguir ese vagón.'::text,'debería haber'::text,'debe de haber'::text,'no puede haber'::text,'Amiga, me dijo que debería haber salido de casa antes en vez de perseguir ese vagón.'::text),
(338576,37620,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''il ... partir de chez lui plus tôt au lieu de courir après ce wagon.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Meuf, il m''a dit qu''il aurait dû partir de chez lui plus tôt au lieu de courir après ce wagon.'::text),
(338579,37620,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana o vagonun peşinden koşmak yerine evden daha erken ... söyledi.'::text,'çıkması gerektiğini'::text,'çıkmış olması gerektiğini'::text,'çıkmış olamayacağını'::text,'Kızım, bana o vagonun peşinden koşmak yerine evden daha erken çıkması gerektiğini söyledi.'::text),
(338580,37620,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy korábban ... elindulnia otthonról ahelyett, hogy azt a kocsit kergesse.'::text,'kellett volna'::text,'biztosan kellett'::text,'nem lehetett'::text,'Csajszi, azt mondta, hogy korábban kellett volna elindulnia otthonról ahelyett, hogy azt a kocsit kergesse.'::text),
(338583,37621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich hat er den Schaffner dazu gebracht, ihm die Waggontür offen ...'::text,'zu halten'::text,'halten'::text,'hielt'::text,'Hör zu, angeblich hat er den Schaffner dazu gebracht, ihm die Waggontür offen zu halten.'::text),
(338587,37621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, він умовив провідника ... йому двері вагона відчиненими.'::text,'потримати'::text,'потримати'::text,'потримав'::text,'Слухай, кажуть, він умовив провідника потримати йому двері вагона відчиненими.'::text),
(338586,37621,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, al parecer consiguió que el revisor le ... abierta la puerta del vagón.'::text,'sujetara'::text,'sujetar'::text,'sujetó'::text,'Escucha, al parecer consiguió que el revisor le sujetara abierta la puerta del vagón.'::text),
(338585,37621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il a convaincu le contrôleur de lui ... la porte du wagon ouverte.'::text,'tenir'::text,'tenir'::text,'a tenu'::text,'Écoute, apparemment il a convaincu le contrôleur de lui tenir la porte du wagon ouverte.'::text),
(338588,37621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya kondüktöre vagon kapısını kendisi için açık ...'::text,'tutturmuş'::text,'tutmak'::text,'tuttu'::text,'Dinle, güya kondüktöre vagon kapısını kendisi için açık tutturmuş.'::text),
(338589,37621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag rávette a kalauzt, hogy ... neki nyitva a kocsiajtót.'::text,'tartsa'::text,'tartani'::text,'tartotta'::text,'Figyelj, állítólag rávette a kalauzt, hogy tartsa neki nyitva a kocsiajtót.'::text),
(338592,37622,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er wünscht sich lowkey, er ... den Waggon ohne das ganze Sprinten erwischt.'::text,'hätte'::text,'erwischte'::text,'würde'::text,'Bro, er wünscht sich lowkey, er hätte den Waggon ohne das ganze Sprinten erwischt.'::text),
(338596,37622,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він чесно хотів би, щоб ... на той вагон без усього цього бігу.'::text,'встиг'::text,'встигає'::text,'встиг би'::text,'Бро, він чесно хотів би, щоб встиг на той вагон без усього цього бігу.'::text),
(338595,37622,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, en el fondo ojalá ... ese vagón sin tanto sprint.'::text,'hubiera pillado'::text,'pillara'::text,'pillaría'::text,'Bro, en el fondo ojalá hubiera pillado ese vagón sin tanto sprint.'::text),
(338594,37622,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, en vrai il aimerait ... ce wagon sans tout ce sprint.'::text,'avoir attrapé'::text,'attraper'::text,'attraperait'::text,'Frérot, en vrai il aimerait avoir attrapé ce wagon sans tout ce sprint.'::text),
(338597,37622,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, içten içe keşke o vagonu bu kadar koşmadan ... diyor.'::text,'yakalasaydım'::text,'yakalasam'::text,'yakalayacak olsam'::text,'Kanka, içten içe keşke o vagonu bu kadar koşmadan yakalasaydım diyor.'::text),
(338598,37622,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, titkon azt kívánja, bárcsak ... azt a kocsit ennyi sprintelés nélkül.'::text,'elérte volna'::text,'elérné'::text,'el fogná érni'::text,'Tesó, titkon azt kívánja, bárcsak elérte volna azt a kocsit ennyi sprintelés nélkül.'::text),
(338601,37623,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Typ, ... Tasche fast aus dem Waggon gefallen wäre, ist irgendwie mein Held.'::text,'dessen'::text,'der'::text,'welcher'::text,'Yo, der Typ, dessen Tasche fast aus dem Waggon gefallen wäre, ist irgendwie mein Held.'::text),
(338605,37623,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, той чувак, ... сумка мало не випала з вагона, трохи мій герой.'::text,'чия'::text,'який'::text,'що'::text,'Йо, той чувак, чия сумка мало не випала з вагона, трохи мій герой.'::text),
(338604,37623,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, el tío ... bolsa casi se cae del vagón es medio mi héroe.'::text,'cuya'::text,'que'::text,'el cual'::text,'Oye, el tío cuya bolsa casi se cae del vagón es medio mi héroe.'::text),
(338603,37623,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, le mec ... le sac a failli tomber du wagon est un peu mon héros.'::text,'dont'::text,'qui'::text,'que'::text,'Yo, le mec dont le sac a failli tomber du wagon est un peu mon héros.'::text),
(338606,37623,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... çantası neredeyse vagondan düşen adam resmen kahramanım.'::text,''::text,NULL::text,NULL::text,'Yo, çantası neredeyse vagondan düşen adam resmen kahramanım.'::text),
