(338610,37624,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er fährt ... zum Meeting um 10:00 und sitzt im letzten Waggon.'::text,'mit dem Zug'::text,'mit dem Zug'::text,'mit einem Zug'::text,'Er fährt mit dem Zug zum Meeting um 10:00 und sitzt im letzten Waggon.'::text),
