(338628,37626,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... er wieder im selben Waggon.'::text,'sitzt gerade'::text,'wird sitzen'::text,'sitzt'::text,'Morgen um diese Zeit sitzt gerade er wieder im selben Waggon.'::text),
(338632,37626,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він знову ... в тому самому вагоні.'::text,'сидітиме'::text,'сяде'::text,'сидить'::text,'Завтра в цей час він знову сидітиме в тому самому вагоні.'::text),
