(338630,37626,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, il ... de nouveau dans le même wagon.'::text,'sera assis'::text,'s''assiéra'::text,'s''assoit'::text,'Demain à la même heure, il sera assis de nouveau dans le même wagon.'::text),
